	/** 把“某个物品类”登记为食材来源；该类本身会再生成别的物品时（切配：生蘑菇 → 切好蘑菇），产出物也算来源 */
	void AddItemSupply(TSet<int32>& OutItemIDs, TSubclassOf<AItemActor> ItemClass)
	{
		if (!ItemClass)
		{
			return;
		}
		const AItemActor* CDO = ItemClass->GetDefaultObject<AItemActor>();
		if (!CDO)
		{
			return;
		}
		if (const int32 ItemID = CDO->GetItemID(); ItemID >= 0)
		{
			OutItemIDs.Add(ItemID);
		}
		if (const AItemActor* OutputCDO = CDO->SpawnItemActorClass ? CDO->SpawnItemActorClass->GetDefaultObject<AItemActor>() : nullptr)
		{
			if (const int32 OutputID = OutputCDO->GetItemID(); OutputID >= 0)
			{
				OutItemIDs.Add(OutputID);
			}
		}
	}
}

// Sets default values
AOrderSystem::AOrderSystem()
{
 	// Set this actor to call Tick() every frame.  You can turn this off to improve performance if you don't need it.
	PrimaryActorTick.bCanEverTick = true;
}

// Called when the game starts or when spawned
void AOrderSystem::BeginPlay()
{
	Super::BeginPlay();

	// 研究炉解锁菜谱 / 关卡目标解锁食材后，订单池要立刻跟上：
	// 否则新菜得等下一关才点得到，或客人一直点“还没解锁/没食材”的菜
	if (UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr)
	{
		GI->OnRecipesUnlocked.AddDynamic(this, &AOrderSystem::HandleRecipesUnlocked);
		GI->OnIngredientsUnlocked.AddDynamic(this, &AOrderSystem::HandleIngredientsUnlocked);
	}
}

void AOrderSystem::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
	// 解除 GameInstance 广播绑定：GameInstance 跨关卡存活，绑定到本 Actor 会指向已销毁对象
	if (UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr)
	{
		GI->OnRecipesUnlocked.RemoveDynamic(this, &AOrderSystem::HandleRecipesUnlocked);
		GI->OnIngredientsUnlocked.RemoveDynamic(this, &AOrderSystem::HandleIngredientsUnlocked);
		if (GI->businessSimulation && GI->businessSimulation->TimeSystem)
			GI->businessSimulation->TimeSystem->SetGoalDrivenBusiness(false);
	}

	// 清空所有未完成订单：waitList 是 UPROPERTY，句柄会随本 Actor 一起被 GC 回收，无需 AddToRoot。
	waitList.Empty();
	// 解除所有蓝图委托绑定，避免退出时回调到已销毁的蓝图对象
	OnStartOrder.Clear();
	OnFinishOrder.Clear();
	OnFailOrder.Clear();
	OnOrderCanceled.Clear();
	Super::EndPlay(EndPlayReason);
}

// Called every frame
void AOrderSystem::Tick(float DeltaTime)
{
	RefreshKitchenShift();
	if (UBaseGameInstance* GI = Cast<UBaseGameInstance>(GetGameInstance()))
	{
		if (GI->businessSimulation && GI->businessSimulation->TimeSystem)
		{
			UTimeSystem* Time = GI->businessSimulation->TimeSystem;
			const int32 Target = GetFirstDayServiceTarget();
			Time->SetGoalDrivenBusiness(Target > 0);
			// 结算卡前退出后读档：赛季已结算，但经营日期尚未确认换日，直接续到第二天，避免重复收支。
			if (IsStarted && Target > 0 && GetFirstDayOrdersServed() >= Target
				&& !Time->IsEndOfDayReached() && GI->curSaveGameData && GI->curSaveGameData->SeasonDay > 1)
			{
				GI->businessSimulation->SkipNextDaySettlement();
				Time->AdvanceDays(1);
				Time->SetGoalDrivenBusiness(false);
				GI->businessSimulation->Save();
			}
			// 上菜调用栈结束后再日结，避免清场修改正在完成的订单或吞掉品质奖励。
			else if (IsStarted && Target > 0 && GetFirstDayOrdersServed() >= Target && Time->IsBusinessOpen())
				Time->FinishBusinessDayEarly();
		}
	}
	if (IsStarted)
	{
		// 天数变化后重建订单池：菜品可配置 UnlockDay，跨天后才允许出现的菜需要重新入池
		const int32 Today = GetCurrentBusinessDay();
		if (PoolBuiltDay != Today)
		{
			RebuildOrderPool();
		}

		CurTime += DeltaTime;

		// —— 订单超时检查（无论订单来自定时生成还是客人点餐）——
		// 倒序遍历，便于超时后直接从列表移除
		for (int i = waitList.Num() - 1; i >= 0; i--)
		{
			UOrderHandle* orderHandle = waitList[i];
			if (!orderHandle)
			{
				continue;
			}

			orderHandle->waitTime += DeltaTime;
			if (orderHandle->IsExpired())
			{
				// 野味订单有价格倍率，但超时惩罚仍按基础价，避免"只奖励不惩罚"被放大
				ABaseLevelBP::AddScore(this, -orderHandle->GetBaseOrderPrice());
				ResetOnTimeStreak();
				OnFailOrder.Broadcast(orderHandle, orderHandle->OrderData);
				GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, TEXT("订单超时"));

				// 记录绑定客人后移除订单，并通知其离场（订单生命周期与客人绑定）
				AGuestCharacter* OrderedGuest = orderHandle->Guest;
				waitList.RemoveAt(i);

				if (OrderedGuest)
				{
					OrderedGuest->OnOrderFailed();
				}
			}
		}

		// —— 定时自动生成订单（默认关闭）——
		// 关闭后订单只在客人坐下点餐时产生（见 RequestOrderForGuest）。
		if (bAutoGenerateByTime && orderCfg && orderCfg->AppearTimes.Num() > 0)
		{
			int num = orderCfg->AppearTimes.Num();
			if (CurOrderIndex >= num)
			{
				CurOrderIndex = 0;
				CurTime = 0;
				GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, TEXT("最后的订单了"));
				//最后订单		
			}
			else
			{
				auto nextOrder = orderCfg->AppearTimes[CurOrderIndex];
				if (CurTime >= nextOrder.AppearTime && CanAcceptNewOrder())
				{
					// 定时生成的订单同样从"按菜品表构建的订单池"里随机取（不再按 AppearOrderID 索引 Orders）
					if (FOrderData* data = GetRandomOrder())
					{
						UOrderHandle* orderHandle = NewObject<UOrderHandle>(this);
						orderHandle->orderId = OrderID;
						OrderID++;
						orderHandle->OrderData = *data;
						orderHandle->waitTime = 0;
						orderHandle->RefreshOrderStats();
						orderHandle->SetCoopWaitTimeScale(GetCoopWaitTimeScale());
						orderHandle->InitializePatience(orderCfg, GetCurrentBusinessDay());
						waitList.Add(orderHandle);
						OnStartOrder.Broadcast(orderHandle, orderHandle->OrderData);
						CurOrderIndex++;
					}
				}
			}
		}
	}
	Super::Tick(DeltaTime);

}
void AOrderSystem::InitCfg(ULevelOrderCfg* cfg)
{
	orderCfg = cfg;
	waitList.Empty(orderCfg ? orderCfg->Orders.Num() : 0);
	CurOrderIndex = 0;
	// 关卡（重新）开始：配置订单的顺序游标从第一单重新开始
	CurConfigOrderIndex = 0;
	OrderID = 0;
	// 新的一天：野味订单计数归零（下一次点餐会再按 UTimeSystem::Day 校准）
	WildOrderDay = INDEX_NONE;
	WildOrdersIssuedToday = 0;
	ActivePrepWindowGrace = 0.f;
	bPrepWindowActive = false;

	// 订单池改为按菜品表（MenuDataTable / FMenuData）构建
	RebuildOrderPool();
}

void AOrderSystem::RebuildOrderPool()
{
	ON_SCOPE_EXIT { UpdateKitchenShiftMenu(); };
	OrderPool.Reset();
	OrderWeights.Reset();
	PoolBuiltDay = GetCurrentBusinessDay();

	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem : nullptr;
	if (!FS)
	{
		UE_LOG(LogTemp, Error, TEXT("[OrderSystem] 构建订单池失败：找不到 UFoodSystem（GameInstance->foodSystem 为空）"));
		if (GEngine)
		{
			GEngine->AddOnScreenDebugMessage(-1, 8.f, FColor::Red,
				TEXT("[订单] 构建订单池失败：GameInstance->foodSystem 为空（请检查 MenuDataTable 配置）"));
		}
		return;
	}

	// 价格 / 等待时间不再写进订单（FOrderData 只留"点了什么"），这里只做数据体检
	int32 BadPrice = 0;
	int32 BadWait = 0;

	// 本关能拿到的食材来源：没有来源的食材不进订单，杜绝“表里加了菜但没摆箱子”的无解订单
	CollectPreparedFoodIDs(CachedPreparedFoodIDs);
	CollectSuppliedItemIDs(CachedSuppliedItemIDs);
	// 本关实际存在的加工机器：菜谱指定的机器不在场，同样做不出来
	CollectAvailableMachineIDs(CachedAvailableMachineIDs);
	RefreshDailyMenu();
	int32 BlockedByLock = 0;
	int32 BlockedBySupply = 0;
	auto IsServableOrLog = [this, FS, &BlockedByLock, &BlockedBySupply](int32 FoodID) -> bool
	{
		FString Reason;
		if (IsMenuServable(FoodID, CachedSuppliedItemIDs, Reason)
			&& IsMenuMachinePresent(FoodID, CachedAvailableMachineIDs, Reason))
		{
			return true;
		}
		if (Reason.Contains(TEXT("未解锁")))
		{
			BlockedByLock++;
		}
		else
		{
			BlockedBySupply++;
		}
		UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 跳过菜品 %d（%s）：%s"), FoodID, *FS->GetMenuData(FoodID).FoodName, *Reason);
		return false;
	};

	// 订单里只存 FoodIDs（菜品表 FoodID），其余信息（价格/等待/菜名/机器）全部由菜品表派生
	auto BuildOrder = [FS, &BadPrice, &BadWait](const TArray<int32>& FoodIDs) -> FOrderData
	{
		FOrderData Data;
		Data.FoodIDs = FoodIDs;

		int32 TotalPrice = 0;
		float MaxWait = 0.f;
		for (const int32 FoodID : FoodIDs)
		{
			const FMenuData Menu = FS->GetMenuData(FoodID);
			if (Menu.FoodID < 0)
			{
				continue;
			}
			TotalPrice += Menu.Price;
			MaxWait = FMath::Max(MaxWait, Menu.MaxWaitTime);
		}

		if (TotalPrice <= 0)
		{
			BadPrice++;
		}
		if (MaxWait <= 0.f)
		{
			BadWait++;
		}
		return Data;
	};

	// 权重：自定义套餐取各菜品 Probabilitys 的平均值
	auto WeightOf = [FS](const TArray<int32>& FoodIDs) -> float
	{
		float Sum = 0.f;
		int32 Count = 0;
		for (const int32 FoodID : FoodIDs)
		{
			const FMenuData Menu = FS->GetMenuData(FoodID);
			if (Menu.FoodID < 0)
			{
				continue;
			}
			Sum += FMath::Max(Menu.Probabilitys, 0.f);
			Count++;
		}
		return Count > 0 ? Sum / static_cast<float>(Count) : 0.f;
	};

	// 1) 关卡里配置的自定义套餐（一单多道菜）：只取 FoodIDs，其余全部由菜品表派生
	if (orderCfg && !orderCfg->bEnableDailyMenu)
	{
		for (const FOrderData& Custom : orderCfg->Orders)
		{
			if (Custom.FoodIDs.Num() == 0)
			{
				continue;
			}
			// 含野外专属菜品的套餐不进常规池：只在备料窗口作为限时野味订单发放
			bool bHasWildMenu = false;
			for (const int32 FoodID : Custom.FoodIDs)
			{
				if (FS->GetMenuData(FoodID).bRequiresWildIngredient)
				{
					bHasWildMenu = true;
					break;
				}
			}
			if (bHasWildMenu)
			{
				continue;
			}

			// 套餐里任何一道菜没解锁 / 食材没来源，整单都不发，避免客人点出做不齐的单
			bool bServable = true;
			for (const int32 FoodID : Custom.FoodIDs)
			{
				if (!IsServableOrLog(FoodID))
				{
					bServable = false;
					break;
				}
			}
			if (!bServable)
			{
				continue;
			}
			OrderPool.Add(BuildOrder(Custom.FoodIDs));
			OrderWeights.Add(WeightOf(Custom.FoodIDs));
		}
	}

	// 2) 菜品表里每道 Probabilitys>0 的菜各成一单（野味菜品除外）
	for (const int32 FoodID : FS->GetFoodIDsByMachine(0))
	{
		const FMenuData Menu = FS->GetMenuData(FoodID);
		if (Menu.FoodID < 0 || Menu.Probabilitys <= 0.f || Menu.bRequiresWildIngredient)
		{
			continue;
		}
		if (orderCfg && orderCfg->bEnableDailyMenu && !DailyMenuIDs.Contains(FoodID))
		{
			continue;
		}
		if (!IsServableOrLog(FoodID))
		{
			continue;
		}

		TArray<int32> FoodIDs;
		FoodIDs.Add(FoodID);
		OrderPool.Add(BuildOrder(FoodIDs));
		OrderWeights.Add(FMath::Max(Menu.Probabilitys, 0.f));
	}

	// 刷新展示数据，但不改变已接订单的等待期限。
	for (UOrderHandle* Handle : waitList)
	{
		if (Handle)
		{
			Handle->RefreshOrderStats();
		}
	}

	if (OrderPool.Num() == 0)
	{
		UE_LOG(LogTemp, Error, TEXT("[OrderSystem] 订单池为空：菜品表里没有可出的菜（检查 Probabilitys>0、菜谱解锁、食材来源），也没有自定义套餐（ULevelOrderCfg::Orders）"));
		if (GEngine)
		{
			GEngine->AddOnScreenDebugMessage(-1, 8.f, FColor::Red,
				TEXT("[订单] 订单池为空！检查菜品 Probabilitys>0、菜谱是否解锁、本关是否摆了对应食材来源"));
		}
	}
	else
	{
		UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 订单池已按菜品表构建：%d 条（含自定义套餐 %d 条；因未解锁跳过 %d、因缺食材/机器跳过 %d）"),
			OrderPool.Num(), orderCfg ? orderCfg->Orders.Num() : 0, BlockedByLock, BlockedBySupply);
		if (BadPrice > 0 || BadWait > 0)
		{
			UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 订单池里有 %d 条价格<=0、%d 条等待时间<=0（请在 MenuDataTable 给菜品配 Price / MaxWaitTime）"),
				BadPrice, BadWait);
		}
	}
}
void AOrderSystem::HandleRecipesUnlocked(const TArray<int32>& UnlockedFoodIDs)
{
	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 菜谱解锁 %d 个，重建订单池"), UnlockedFoodIDs.Num());
	RebuildOrderPool();
	if (orderCfg && orderCfg->bEnableDailyMenu)
	{
		const TArray<int32> Available = GetAvailableDailyDishes();
		for (const int32 ID : UnlockedFoodIDs)
		{
			if (!Available.Contains(ID)) continue;
			PendingTastingIDs.AddUnique(ID);
			if (!DailyMenuIDs.Contains(ID))
			{
				if (DailyMenuIDs.Num() >= FMath::Max(1, orderCfg->DailyMenuCapacity))
					DailyMenuIDs.Pop();
				DailyMenuIDs.Add(ID);
			}
		}
		SaveDailyMenu();
		RebuildOrderPool();
	}
}

TArray<int32> AOrderSystem::GetAvailableDailyDishes() const
{
	TArray<int32> Result;
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem.Get() : nullptr;
	if (!FS) return Result;
	TSet<int32> MenuIngredientIDs = CachedSuppliedItemIDs;
	const int32 Day = GetCurrentBusinessDay();
	if (Day >= 2 && Day <= 3 && UGameplayStatics::GetCurrentLevelName(this) == TEXT("Kitchen_New"))
	{
		// An empty box describes today's stock, not whether this recipe belongs on the menu.
		// Keep the player's menu selections while the opening card tells them what to refill.
		for (TActorIterator<AFoodSpawner> It(GetWorld()); It; ++It)
			if (!It->IsDayLocked()) AddItemSupply(MenuIngredientIDs, It->SpawnItemActorClass);
	}
	for (const int32 ID : FS->GetFoodIDsByMachine(0))
	{
		const FMenuData Menu = FS->GetMenuData(ID);
		FString Reason;
		if (Menu.Price > 0 && Menu.Probabilitys > 0.f && !Menu.bRequiresWildIngredient
			&& IsMenuServable(ID, MenuIngredientIDs, Reason)
			&& IsMenuMachinePresent(ID, CachedAvailableMachineIDs, Reason))
			Result.Add(ID);
	}
	Result.Sort();
	return Result;
}

TArray<int32> AOrderSystem::GetTeachingOrderFoodIDs(int32 Day) const
{
	const FOrderData* Sequence = orderCfg ? orderCfg->DayFoodSequences.Find(Day) : nullptr;
	return Sequence ? Sequence->FoodIDs : TArray<int32>();
}

bool AOrderSystem::IsDailyMenuEditable() const
{
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	const UTimeSystem* TS = GI && GI->businessSimulation ? GI->businessSimulation->TimeSystem.Get() : nullptr;
	return orderCfg && orderCfg->bEnableDailyMenu && TS && !TS->IsBusinessOpen()
		&& GetCurrentBusinessDay() > orderCfg->FixedTutorialThroughDay;
}

void AOrderSystem::SaveDailyMenu() const
{
	if (UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr)
	{
		if (GI->curSaveGameData)
		{
			GI->curSaveGameData->DailyMenuFoodIDs = DailyMenuIDs;
			GI->SaveGameData();
		}
	}
}

void AOrderSystem::RefreshDailyMenu()
{
	if (!orderCfg || !orderCfg->bEnableDailyMenu) return;
	const TArray<int32> Available = GetAvailableDailyDishes();
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	if (DailyMenuIDs.IsEmpty() && GI && GI->curSaveGameData)
		DailyMenuIDs = GI->curSaveGameData->DailyMenuFoodIDs;
	DailyMenuIDs.RemoveAll([&](int32 ID) { return !Available.Contains(ID); });
	const int32 Capacity = FMath::Max(1, orderCfg->DailyMenuCapacity);
	if (DailyMenuIDs.Num() > Capacity) DailyMenuIDs.SetNum(Capacity);
	const bool bNeedsDefault = DailyMenuIDs.IsEmpty();
	for (int32 ID : Available)
	{
		if (DailyMenuIDs.Num() >= Capacity) break;
		if (bNeedsDefault || (bDailyMenuInitialized && !KnownAvailableDishes.Contains(ID)))
			DailyMenuIDs.AddUnique(ID);
	}
	KnownAvailableDishes = TSet<int32>(Available);
	bDailyMenuInitialized = true;
}

bool AOrderSystem::ToggleDailyMenuDish(int32 FoodID)
{
	if (!IsDailyMenuEditable() || !GetAvailableDailyDishes().Contains(FoodID)) return false;
	if (DailyMenuIDs.Contains(FoodID))
	{
		if (DailyMenuIDs.Num() <= 1) return false;
		DailyMenuIDs.Remove(FoodID);
	}
	else
	{
		if (DailyMenuIDs.Num() >= FMath::Max(1, orderCfg->DailyMenuCapacity)) return false;
		DailyMenuIDs.Add(FoodID);
	}
	SaveDailyMenu();
	RebuildOrderPool();
	return true;
}

bool AOrderSystem::TryBuildTastingOrder(FOrderData& OutOrder)
{
	if (!orderCfg || !orderCfg->bEnableDailyMenu
		|| GetCurrentBusinessDay() <= orderCfg->FixedTutorialThroughDay) return false;
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	if (!GI || !GI->curSaveGameData) return false;
	TArray<int32> Candidates = PendingTastingIDs;
	Candidates.Append(DailyMenuIDs);
	for (int32 ID : Candidates)
	{
		if (!DailyMenuIDs.Contains(ID) || GI->curSaveGameData->TastedFoodIDs.Contains(ID)) continue;
		FString Reason;
		if (!IsMenuServable(ID, CachedSuppliedItemIDs, Reason)
			|| !IsMenuMachinePresent(ID, CachedAvailableMachineIDs, Reason)) continue;
		OutOrder.FoodIDs = {ID};
		PendingTastingIDs.Remove(ID);
		GI->curSaveGameData->TastedFoodIDs.AddUnique(ID);
		GI->SaveGameData();
		return true;
	}
	return false;
}

void AOrderSystem::HandleIngredientsUnlocked(const TArray<int32>& UnlockedIDs)
{
	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 食材解锁 %d 个，重建订单池"), UnlockedIDs.Num());
	RebuildOrderPool();
}

void AOrderSystem::CollectSuppliedItemIDs(TSet<int32>& OutItemIDs) const
{
	OutItemIDs.Reset();
	UWorld* World = GetWorld();
	if (!World)
	{
		return;
	}

	UBaseGameInstance* GI = Cast<UBaseGameInstance>(World->GetGameInstance());
	// 仓库驱动模式下箱子能不能出料取决于当时的库存，不能用“此刻空箱”判定本关没有这种食材
	const bool bWarehouseDriven = GI && GI->bLinkSpawnerToWarehouse;

	for (TActorIterator<AFoodSpawner> It(World); It; ++It)
	{
		// 还没到开放天数的食材箱（例如第 1 天隐藏的番茄箱）不算来源，仓库模式也一样
		if (It->IsDayLocked())
		{
			continue;
		}
		if (bWarehouseDriven || It->CanSpawn())
		{
			AddItemSupply(OutItemIDs, It->SpawnItemActorClass);
		}
	}

	// 野外散布点：当季不长的采集物不算来源，否则会点出“要等到明年”的单
	for (TActorIterator<AItemScatterSpawner> It(World); It; ++It)
	{
		const ESeason Season = It->GetCurrentSeason();
		for (const FScatterSpawnEntry& Entry : It->Entries)
		{
			if (Entry.Seasons.Num() > 0 && !Entry.Seasons.Contains(Season))
			{
				continue;
			}
			AddItemSupply(OutItemIDs, Entry.ItemClass);
		}
	}

	// 可采植株：还没解锁的作物不算来源（对应 IngredientUnlockID 门闩）
	for (TActorIterator<APlant> It(World); It; ++It)
	{
		if (It->IngredientUnlockID >= 0 && GI && !GI->IsIngredientUnlocked(It->IngredientUnlockID))
		{
			continue;
		}
		if (const FPlantInfo* Info = It->PlantInfoRow.GetRow<FPlantInfo>(TEXT("OrderSystem::CollectSuppliedItemIDs")))
		{
			AddItemSupply(OutItemIDs, Info->FruitClass);
		}
	}

	// 猎物掉落（鸡腿 / 鹿肉等）
	for (TActorIterator<AAnimalCharacter> It(World); It; ++It)
	{
		UClass* DropClass = It->DropActorClass.Get();
		if (DropClass && DropClass->IsChildOf(AItemActor::StaticClass()))
		{
			AddItemSupply(OutItemIDs, DropClass);
		}
	}

	// 加工链：上一级有来源且菜谱已解锁时，加工产物也算来源（生蘑菇 → 切好蘑菇）。
	// 只回溯一层，够覆盖“切配后再下锅”这一层，也不至于把整张表递归扫一遍。
	if (GI && GI->foodSystem)
	{
		UFoodSystem* FS = GI->foodSystem;
		for (const int32 FoodID : FS->GetFoodIDsByMachine(0))
		{
			FString Reason;
			if (!IsMenuServable(FoodID, OutItemIDs, Reason))
			{
				continue;
			}
			const FMenuData Menu = FS->GetMenuData(FoodID);
			if (!Menu.CookedActorClass)
			{
				continue;
			}
			if (const AItemActor* OutputCDO = Cast<AItemActor>(Menu.CookedActorClass->GetDefaultObject()))
			{
				if (const int32 OutputID = OutputCDO->GetItemID(); OutputID >= 0)
				{
					OutItemIDs.Add(OutputID);
				}
			}
		}
	}
}

void AOrderSystem::CollectPreparedFoodPortions(TMap<int32, int32>& Available) const
{
	Available.Reset();
	// The last ingredient may already be in the pan when the guest orders.
	for (TActorIterator<ACookingMachine> It(GetWorld()); It; ++It)
	{
		const ACookingMachine* Machine = *It;
		const int32 FoodID = Machine->TargetMenuData.FoodID;
		if (Machine->IsFull && (Machine->IsCooking || Machine->IsFinish)
			&& !Machine->OnFire && !Machine->Repairing && FoodID >= 0)
		{
			++Available.FindOrAdd(FoodID);
		}
	}
	for (TActorIterator<AItemActor> It(GetWorld()); It; ++It)
	{
		const AItemActor* Dish = *It;
		if (!Dish->bPickable || Dish->bIsDirtyPlate || Dish->bIsEmptyPlate
			|| Dish->GetItemState() == EItemState::EIS_Cooking) continue;
		// A plated child is counted by its containing plate; served plates belong to a seat.
		const AActor* Parent = Dish->GetAttachParentActor();
		if (Parent && (Parent->IsA<AItemActor>() || Parent->IsA<AChairSeat>() || Parent->IsA<AGuestCharacter>())) continue;
		if (!Dish->FoodIdArray.IsEmpty())
		{
			for (int32 ID : Dish->FoodIdArray) if (ID >= 0) ++Available.FindOrAdd(ID);
		}
		else if (Dish->GetMenuFoodID() >= 0) ++Available.FindOrAdd(Dish->GetMenuFoodID());
	}
}

void AOrderSystem::CollectPreparedFoodIDs(TSet<int32>& OutFoodIDs) const
{
	OutFoodIDs.Reset();
	TMap<int32, int32> Available;
	CollectPreparedFoodPortions(Available);
	// Reserve existing orders first, so the same last dish cannot promise another order.
	for (const UOrderHandle* Handle : waitList)
		if (Handle)
			for (int32 ID : Handle->OrderData.FoodIDs) --Available.FindOrAdd(ID);
	for (const TPair<int32, int32>& Pair : Available)
		if (Pair.Value > 0) OutFoodIDs.Add(Pair.Key);
}

bool AOrderSystem::IsMenuServable(int32 FoodID, const TSet<int32>& SuppliedItemIDs, FString& OutReason,
	bool bCheckSupplies) const
{
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem : nullptr;
	if (!FS)
	{
		OutReason = TEXT("找不到 UFoodSystem");
		return false;
	}

	const FMenuData Menu = FS->GetMenuData(FoodID);
	if (Menu.FoodID < 0)
	{
		OutReason = TEXT("菜品行无效");
		return false;
	}
	if (!GI->IsRecipeUnlocked(FoodID))
	{
		OutReason = TEXT("菜谱未解锁（需研究炉研究）");
		return false;
	}
	// 菜品配置的最早营业日：例如番茄类菜设为第 2 天，新手第一天的订单里就不会出现
	if (Menu.UnlockDay > 0 && GetCurrentBusinessDay() < Menu.UnlockDay)
	{
		OutReason = FString::Printf(TEXT("未到可点天数（第 %d 天开放）"), Menu.UnlockDay);
		return false;
	}
	if (CachedPreparedFoodIDs.Contains(FoodID)) return true;
	if (Menu.MenuItems.Num() == 0)
	{
		OutReason = TEXT("菜品没配食材");
		return false;
	}
	for (const TPair<int32, int32>& Item : Menu.MenuItems)
	{
		if (bCheckSupplies && Item.Value > 0 && !SuppliedItemIDs.Contains(Item.Key))
		{
			OutReason = FString::Printf(TEXT("缺少食材 ItemID=%d（本关没有对应箱子/植株/采集点）"), Item.Key);
			return false;
		}
	}
	return true;
}

bool AOrderSystem::IsMenuMachinePresent(int32 FoodID, const TSet<int32>& AvailableMachineIDs, FString& OutReason) const
{
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem : nullptr;
	if (!FS)
	{
		OutReason = TEXT("找不到 UFoodSystem");
		return false;
	}

	// MachineID=0 表示通用，任何机器都能做
	const int32 MachineID = FS->GetMenuData(FoodID).MachineID;
	if (MachineID > 0 && !AvailableMachineIDs.Contains(MachineID))
	{
		OutReason = FString::Printf(TEXT("本关没有 MachineID=%d 的加工机器"), MachineID);
		return false;
	}
	return true;
}

void AOrderSystem::CollectAvailableMachineIDs(TSet<int32>& OutMachineIDs) const
{
	OutMachineIDs.Reset();
	UWorld* World = GetWorld();
	if (!World)
	{
		return;
	}
	for (TActorIterator<ACookingMachine> It(World); It; ++It)
	{
		// 商店未解锁的设备（如未购买的榨汁机）不算“本关存在的机器”，否则会出无解订单
		if (It->MachineID > 0 && It->IsShopUnlocked())
		{
			OutMachineIDs.Add(It->MachineID);
		}
	}
}

