void AOrderSystem::ClearAllOrders()
{
	ResetOnTimeStreak();
	// 静默清空：不广播 OnFailOrder，避免切换关卡时误扣分数/声誉。
	// 句柄为本 Actor 创建的 UObject，随 waitList 清空后被 GC 回收。
	waitList.Empty();
}

void AOrderSystem::FailAllPendingOrders()
{
	ResetOnTimeStreak();
	if (waitList.Num() == 0)
	{
		return;
	}

	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 打烊：%d 个未完成订单按超时失败结算"), waitList.Num());
	GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red,
		FString::Printf(TEXT("打烊：%d 个未完成订单计为失败"), waitList.Num()));

	// 与 Tick 中超时同款结算：按基础价扣分、广播失败、让绑定客人离场
	for (int32 i = waitList.Num() - 1; i >= 0; --i)
	{
		UOrderHandle* orderHandle = waitList[i];
		if (!orderHandle)
		{
			continue;
		}
		ABaseLevelBP::AddScore(this, -orderHandle->GetBaseOrderPrice());
		OnFailOrder.Broadcast(orderHandle, orderHandle->OrderData);
		if (AGuestCharacter* OrderedGuest = orderHandle->Guest)
		{
			OrderedGuest->OnOrderFailed();
		}
	}
	waitList.Empty();
}

FOrderData* AOrderSystem::GetRandomOrder()
{
	// 池为空时兜底重建一次（例如菜单表比订单系统晚初始化）
	if (OrderPool.Num() == 0)
	{
		RebuildOrderPool();
		if (OrderPool.Num() == 0)
		{
			return nullptr;
		}
	}

	// 优先按菜品表里的 Probabilitys 加权随机；全为 0（或负）时退化为均匀随机
	float TotalWeight = 0.f;
	for (const float W : OrderWeights)
	{
		TotalWeight += FMath::Max(W, 0.f);
	}

	if (TotalWeight <= 0.f)
	{
		return &OrderPool[FMath::RandRange(0, OrderPool.Num() - 1)];
	}

	float R = FMath::FRandRange(0.f, TotalWeight);
	for (int32 i = 0; i < OrderPool.Num(); ++i)
	{
		R -= FMath::Max(OrderWeights.IsValidIndex(i) ? OrderWeights[i] : 0.f, 0.f);
		if (R <= 0.f)
		{
			return &OrderPool[i];
		}
	}
	return &OrderPool.Last();
}

bool AOrderSystem::GetNextConfigOrder(FOrderData& OutOrder, bool* bOutNoneServable)
{
	if (bOutNoneServable)
	{
		*bOutNoneServable = false;
	}
	if (!orderCfg || orderCfg->Orders.Num() == 0)
	{
		return false;
	}

	const int32 NumOrders = orderCfg->Orders.Num();
	int32 SkippedNotServable = 0;

	// 按 Orders 数组顺序依次发单：一轮最多尝试 NumOrders 次，避免全是空配置时死循环
	for (int32 Tried = 0; Tried < NumOrders; ++Tried)
	{
		if (CurConfigOrderIndex >= NumOrders)
		{
			if (!bLoopConfigOrders)
			{
				// 配置里的订单已发完且不循环：不再出单（客人会因点不到单而离场）
				return false;
			}
			CurConfigOrderIndex = 0;
		}

		const FOrderData& Config = orderCfg->Orders[CurConfigOrderIndex];
		const int32 ServedIndex = CurConfigOrderIndex;
		++CurConfigOrderIndex;

		// 没填菜品的配置项跳过，继续取下一项
		if (Config.FoodIDs.Num() == 0)
		{
			continue;
		}

		// 今天还发不了的配置单（例如第 1 天轮到第 2 天才开放的番茄汤）直接跳过，取下一项
		FString Reason;
		if (!IsOrderServableToday(Config, Reason))
		{
			++SkippedNotServable;
			UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 跳过关卡配置第 %d/%d 单：%s"), ServedIndex + 1, NumOrders, *Reason);
			continue;
		}

		OutOrder = Config;
		UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 按关卡配置出单：第 %d/%d 单"), ServedIndex + 1, NumOrders);
		return true;
	}

	if (SkippedNotServable > 0)
	{
		// 一整轮的配置单今天都发不了：交给调用方退回随机订单池（池子已按当天条件过滤）
		if (bOutNoneServable)
		{
			*bOutNoneServable = true;
		}
		UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 关卡配置订单今天都发不了（%d 单被过滤），改用随机订单池"), SkippedNotServable);
		return false;
	}

	UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 关卡订单配置（ULevelOrderCfg::Orders）里没有填菜品的订单，请检查 LevelOrderConfigs 指向的资产"));
	return false;
}

bool AOrderSystem::IsOrderServableToday(const FOrderData& Order, FString& OutReason, bool bCheckSupplies) const
{
	if (Order.FoodIDs.Num() == 0)
	{
		OutReason = TEXT("订单没有菜品");
		return false;
	}
	for (const int32 FoodID : Order.FoodIDs)
	{
		if (!IsMenuServable(FoodID, CachedSuppliedItemIDs, OutReason, bCheckSupplies)
			|| !IsMenuMachinePresent(FoodID, CachedAvailableMachineIDs, OutReason))
		{
			OutReason = FString::Printf(TEXT("菜品 %d %s"), FoodID, *OutReason);
			return false;
		}
	}
	return true;
}

// ==================== 备料窗口 / 限时野味订单（第 16 节 P0） ====================

void AOrderSystem::SetPrepWindowGrace(float Seconds, bool bWindowActive)
{
	ActivePrepWindowGrace = FMath::Max(0.f, Seconds);
	bPrepWindowActive = bWindowActive;

	for (UOrderHandle* Handle : waitList)
	{
		if (Handle)
		{
			Handle->SetPrepWindowGraceSeconds(bWindowActive ? ActivePrepWindowGrace : 0.f);
		}
	}

	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 备料窗口 %s：在场 %d 单宽限 %.1fs"),
		bWindowActive ? TEXT("开启") : TEXT("关闭"), waitList.Num(),
		bWindowActive ? ActivePrepWindowGrace : 0.f);
}

int32 AOrderSystem::GetCurrentBusinessDay() const
{
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UTimeSystem* TS = GI && GI->businessSimulation ? GI->businessSimulation->TimeSystem.Get() : nullptr;
	return TS ? TS->GetBusinessDayNumber() : 0;
}

int32 AOrderSystem::GetEffectiveWildOrderDailyLimit() const
{
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	const int32 Players = GI ? FMath::Max(GI->GetCoopActorCount(), 1) : 1;
	return WildOrderDailyLimit + CoopExtraWildOrdersPerPlayer * (Players - 1);
}

float AOrderSystem::GetCoopWaitTimeScale() const
{
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	const int32 Players = GI ? FMath::Max(GI->GetCoopActorCount(), 1) : 1;
	// 每多 1 人等待 ×(1 - Reduction)；下限 0.5 防止多玩家时订单苛刻到无解
	return FMath::Max(1.f - CoopWaitTimeReductionPerExtraPlayer * (Players - 1), 0.5f);
}

bool AOrderSystem::TryBuildWildOrder(FOrderData& OutOrder, const TSet<int32>& SuppliedItemIDs, const TSet<int32>& AvailableMachineIDs) const
{
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem : nullptr;
	if (!FS)
	{
		return false;
	}

	TArray<int32> Candidates;
	for (const int32 FoodID : FS->GetFoodIDsByMachine(0))
	{
		const FMenuData Menu = FS->GetMenuData(FoodID);
		if (Menu.FoodID < 0 || !Menu.bRequiresWildIngredient)
		{
			continue;
		}
		// 野味菜同样要“已解锁 + 食材当季有来源 + 本关有对应机器”，否则限时单也是无解订单
		FString Reason;
		if (IsMenuServable(FoodID, SuppliedItemIDs, Reason)
			&& IsMenuMachinePresent(FoodID, AvailableMachineIDs, Reason))
		{
			Candidates.Add(FoodID);
		}
		else
		{
			UE_LOG(LogTemp, Verbose, TEXT("[OrderSystem] 野味订单跳过菜品 %d：%s"), FoodID, *Reason);
		}
	}
	if (Candidates.Num() == 0)
	{
		// 表里没配野味菜品：静默跳过，订单来源完全退回旧逻辑
		return false;
	}

	OutOrder = FOrderData();
	OutOrder.FoodIDs.Add(Candidates[FMath::RandRange(0, Candidates.Num() - 1)]);
	return true;
}

bool AOrderSystem::CanAcceptNewOrder() const
{
	const int32 MaxOrders = orderCfg ? FMath::Max(1, orderCfg->MaxWaitOrderNum) : 4;
	const int32 Target = GetFirstDayServiceTarget();
	return IsStarted && waitList.Num() < MaxOrders
		&& (Target <= 0 || GetFirstDayOrdersServed() + waitList.Num() < Target);
}

int32 AOrderSystem::GetFirstDayServiceTarget() const
{
	return orderCfg && GetCurrentBusinessDay() == 1 ? FMath::Max(0, orderCfg->FirstDayServiceTarget) : 0;
}

int32 AOrderSystem::GetFirstDayOrdersServed() const
{
	const UBaseGameInstance* GI = Cast<UBaseGameInstance>(GetGameInstance());
	return GI && GI->curSaveGameData
		? FMath::Max(0, GI->curSaveGameData->FirstDayOrdersServed)
		: FirstDayOrdersServed;
}

int32 AOrderSystem::GetRemainingFirstDayEggOrders() const
{
	const int32 Remaining = GetFirstDayServiceTarget() - GetFirstDayOrdersServed();
	if (!IsStarted || Remaining <= 0 || UGameplayStatics::GetCurrentLevelName(this) != TEXT("Kitchen_New"))
	{
		return 0;
	}

	const FOrderData* Sequence = orderCfg->DayFoodSequences.Find(1);
	return Sequence && Sequence->FoodIDs.Num() == 1 && Sequence->FoodIDs[0] == 1001 ? Remaining : 0;
}

void AOrderSystem::RecordFirstDayOrderServed()
{
	if (GetFirstDayServiceTarget() <= 0) return;
	FirstDayOrdersServed = GetFirstDayOrdersServed() + 1;
	if (UBaseGameInstance* GI = Cast<UBaseGameInstance>(GetGameInstance()))
	{
		if (GI->curSaveGameData)
		{
			GI->curSaveGameData->FirstDayOrdersServed = FirstDayOrdersServed;
			GI->SaveGameData();
		}
	}
	ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::ServeGuests, -1);
}

UOrderHandle* AOrderSystem::RequestOrderForGuest(AGuestCharacter* Guest)
{
	if (!IsStarted || !Guest)
	{
		return nullptr;
	}

	for (UOrderHandle* Handle : waitList)
	{
		if (Handle && Handle->Guest == Guest)
		{
			return Handle;
		}
	}

	if (!CanAcceptNewOrder())
	{
		return nullptr;
	}

	RefreshKitchenShift();

	// 跨日重置野味订单计数（UTimeSystem::Day；拿不到时钟时固定为 0，行为退化为只发一次）
	const int32 Today = GetCurrentBusinessDay();
	if (Today != WildOrderDay)
	{
		WildOrderDay = Today;
		WildOrdersIssuedToday = 0;
	}

	FOrderData OrderData;
	bool bWildOrder = false;

	// Preparation can refill an empty box after the daily pool was built.
	// Compare live sources before validating the next teaching/configured order;
	// otherwise yesterday's empty egg box can block day two even after restocking.
	TSet<int32> CurrentSuppliedItemIDs;
	TSet<int32> CurrentAvailableMachineIDs;
	TSet<int32> CurrentPreparedFoodIDs;
	CollectSuppliedItemIDs(CurrentSuppliedItemIDs);
	CollectAvailableMachineIDs(CurrentAvailableMachineIDs);
	CollectPreparedFoodIDs(CurrentPreparedFoodIDs);
	if (PoolBuiltDay != Today
		|| !CachedSuppliedItemIDs.Includes(CurrentSuppliedItemIDs)
		|| !CurrentSuppliedItemIDs.Includes(CachedSuppliedItemIDs)
		|| !CachedAvailableMachineIDs.Includes(CurrentAvailableMachineIDs)
		|| !CurrentAvailableMachineIDs.Includes(CachedAvailableMachineIDs)
		|| !CachedPreparedFoodIDs.Includes(CurrentPreparedFoodIDs)
		|| !CurrentPreparedFoodIDs.Includes(CachedPreparedFoodIDs))
	{
		RebuildOrderPool();
	}

	// 新手引导按天覆盖的前 N 单顺序（ULevelOrderCfg::DayFoodSequences）：
	// 优先于常规出单逻辑，依次发放；序列发完后当天剩余订单走随机池（该天不再用配置顺序单）
	bool bTutorialOrder = false;
	const FOrderData* DaySeq = orderCfg ? orderCfg->DayFoodSequences.Find(Today) : nullptr;
	if (DaySeq)
	{
		// The first-day lesson replenishes lost ingredients until all three plates are served.
		const bool bFirstDayEggLesson = GetRemainingFirstDayEggOrders() > 0;
		if (Today != TutorialSeqDay)
		{
			TutorialSeqDay = Today;
			TutorialSeqCursor = 0;
			if (Today == 2 || Today == 3)
				if (const UBaseGameInstance* GI = Cast<UBaseGameInstance>(GetGameInstance()))
					if (GI->curSaveGameData)
						if (const FTutorialDaySave* Saved = GI->curSaveGameData->TutorialDays.Find(Today))
							TutorialSeqCursor = FMath::Clamp(Saved->Served, 0, DaySeq->FoodIDs.Num());
		}
		// 目标制试营业持续使用教学菜，直到完成目标；客人离场后的补位也能正常点单。
		if (GetFirstDayServiceTarget() > 0 && TutorialSeqCursor >= DaySeq->FoodIDs.Num())
		{
			TutorialSeqCursor = 0;
		}
		// 序列里今天还发不了的菜（未到 UnlockDay / 缺食材）跳过，避免引导单绕过当天过滤
		while (TutorialSeqCursor < DaySeq->FoodIDs.Num())
		{
			FOrderData Candidate;
			Candidate.FoodIDs = { DaySeq->FoodIDs[TutorialSeqCursor] };

			FString Reason;
			if (!IsOrderServableToday(Candidate, Reason, !bFirstDayEggLesson))
			{
				// Keep the promised teaching dish at the front until it is available.
				if (bFirstDayEggLesson || Today == 2 || Today == 3)
				{
					UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 第 %d 天教学单 %d 暂不可接：%s"),
						Today, TutorialSeqCursor + 1, *Reason);
					return nullptr;
				}
				++TutorialSeqCursor;
				UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 新手引导序列跳过第 %d 单：%s"), TutorialSeqCursor, *Reason);
				continue;
			}

			OrderData = MoveTemp(Candidate);
			++TutorialSeqCursor;
			bTutorialOrder = true;
			UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 新手引导顺序出单：第 %d/%d 单（第 %d 天）"),
				TutorialSeqCursor, DaySeq->FoodIDs.Num(), Today);
			break;
		}
	}

	// 点餐来源：备料窗口内优先发「限时野味订单」（不消耗配置订单序列游标，属窗口内额外机会单）；
	// 否则优先按关卡订单配置（Level_01_Order 等）的顺序依次取；
	// 关闭顺序出单或配置里没有订单时，才退回按菜品表 Probabilitys 的随机订单池
	// （引导序列当天即使序列发完，也直接走随机池，不再用配置顺序单）
	if (!bTutorialOrder)
	{
		bool bUseRandomPool = true;
		if (bEnableWildOrderInPrepWindow && bPrepWindowActive
			&& WildOrderDailyLimit > 0 && WildOrdersIssuedToday < GetEffectiveWildOrderDailyLimit()
			&& TryBuildWildOrder(OrderData, CachedSuppliedItemIDs, CachedAvailableMachineIDs))
		{
			bWildOrder = true;
			WildOrdersIssuedToday++;
			bUseRandomPool = false;
		}
		else if (TryBuildTastingOrder(OrderData))
		{
			bUseRandomPool = false;
		}
		else if (!DaySeq && bUseConfigOrderSequence && orderCfg && orderCfg->Orders.Num() > 0
			&& (!orderCfg->bEnableDailyMenu || Today <= orderCfg->FixedTutorialThroughDay))
		{
			bool bNoneServable = false;
			if (GetNextConfigOrder(OrderData, &bNoneServable))
			{
				bUseRandomPool = false;
			}
			else if (!bNoneServable)
			{
				// 配置订单已按顺序发完（bLoopConfigOrders=false）：不再随机塞单，保持关卡节奏可控
				UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 关卡订单已发完（不循环），客人 %s 点不到单"), *Guest->GetName());
				return nullptr;
			}
			// bNoneServable：配置单今天都发不了，退回已按当天过滤的随机池
		}

		if (bUseRandomPool && !TryBuildKitchenShiftOrder(OrderData))
		{
			const FOrderData* RandomData = GetRandomOrder();
			if (!RandomData)
			{
				return nullptr;
			}
			OrderData = *RandomData;
		}
	}

	// 客人点餐：生成订单并绑定该客人（订单生命周期 = 客人的等餐周期）
	UOrderHandle* orderHandle = NewObject<UOrderHandle>(this);
	orderHandle->orderId = OrderID;
	OrderID++;
	orderHandle->OrderData = OrderData;
	orderHandle->waitTime = 0.f;
	orderHandle->Guest = Guest;
	orderHandle->SetPrepWindowGraceSeconds(ActivePrepWindowGrace);
	if (bWildOrder)
	{
		orderHandle->SetWildOrder(WildOrderPriceMultiplier);
	}
	orderHandle->RefreshOrderStats();
	orderHandle->SetCoopWaitTimeScale(GetCoopWaitTimeScale());
	orderHandle->InitializePatience(orderCfg, Today);

	waitList.Add(orderHandle);
	ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::AcceptOrder, -1, Guest);
	OnStartOrder.Broadcast(orderHandle, orderHandle->OrderData);

	if (bWildOrder)
	{
		// HUD 接入点：蓝图监听 OnWildOrderOffered 做正式提示；这里给一条零配置屏幕提示
		OnWildOrderOffered.Broadcast(orderHandle);
		if (GEngine)
		{
			GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Yellow,
				FString::Printf(TEXT("限时野味订单：%s（需要野外食材 · 收益 x%.1f）"),
					*orderHandle->GetOrderDisplayName(), WildOrderPriceMultiplier));
		}
		UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 备料窗口野味订单 %d/%d：%s"),
			WildOrdersIssuedToday, GetEffectiveWildOrderDailyLimit(), *orderHandle->GetOrderDisplayName());
	}

	// 屏幕提示由客人侧（AGuestCharacter::PlaceOrder）统一打印，这里只留日志避免重复刷屏
	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 客人 %s 点餐：%s（等待 %.0fs）"),
		*Guest->GetName(), *orderHandle->GetOrderDisplayName(), orderHandle->GetOrderMaxWaitTime());

	return orderHandle;
}

bool AOrderSystem::CancelOrderForGuest(AGuestCharacter* Guest)
{
	if (!Guest)
	{
		return false;
	}

	for (int i = 0; i < waitList.Num(); i++)
	{
		UOrderHandle* handle = waitList[i];
		if (handle && handle->Guest == Guest)
		{
			waitList.RemoveAt(i);
			// huanglily：以前这里只改 waitList，订单 UI 的增量缓存收不到移除通知，
			// 客人被老鼠吓跑后订单条会一直挂着。用独立的静默取消事件通知 UI，不计失败不扣分。
			OnOrderCanceled.Broadcast(handle, handle->OrderData);
			return true;
		}
	}
	return false;
}

bool AOrderSystem::PushFoods(const TArray<int>& FoodIDs, bool bPremiumDish)
{
	if (!IsStarted)
	{
		GEngine->AddOnScreenDebugMessage(-1, 5.0f, FColor::Red	 , FString::Printf(TEXT("上菜失败，游戏已经结束")));
		return false;
	}
	const int Num = FoodIDs.Num();

	// 1. 收集所有完全匹配的候选订单（菜品集合与数量一致）
	TArray<UOrderHandle*> Candidates;
	for (UOrderHandle* handle : waitList)
	{
		if (!handle || handle->IsExpired())
		{
			continue;
		}
		const FOrderData& order = handle->OrderData;
		if (order.FoodIDs.Num() != Num)
		{
			continue;
		}
		// 统计 Foods 中每个 ID 的出现次数，与订单比对（避免菜品重复导致的误判）
		TMap<int, int> NeedCount;
		for (int id : order.FoodIDs)
		{
			NeedCount.FindOrAdd(id)++;
		}
		bool bMatch = true;
		for (int id : FoodIDs)
		{
			int* p = NeedCount.Find(id);
			if (!p || *p <= 0)
			{
				bMatch = false;
				break;
			}
			(*p)--;
		}
		if (bMatch)
		{
			Candidates.Add(handle);
		}
	}
	if (Candidates.Num() == 0)
	{
		return false;
	}

	// 2. 在候选中选剩余时间比例最少（GetPercent 最小，最紧急）的订单优先完成
	UOrderHandle* BestHandle = Candidates[0];
	float BestPercent = BestHandle->GetPercent();
	for (UOrderHandle* handle : Candidates)
	{
		const float Percent = handle->GetPercent();
		if (Percent < BestPercent || (Percent == BestPercent
			&& handle->GetOrderTimeout() - handle->waitTime < BestHandle->GetOrderTimeout() - BestHandle->waitTime))
		{
			BestPercent = Percent;
			BestHandle = handle;
		}
	}

	// 3. 完成该订单
	// 先取出绑定客人，避免移除句柄后访问
	AGuestCharacter* OrderedGuest = BestHandle->Guest;

	ABaseLevelBP::AddScore(this, BestHandle->GetOrderSettlementPrice());
	RecordOrderTiming(*BestHandle);
	RecordKitchenShiftOrder(*BestHandle, bPremiumDish);
	OnFinishOrder.Broadcast(BestHandle, BestHandle->OrderData);
	waitList.Remove(BestHandle);
	GEngine->AddOnScreenDebugMessage(-1, 2, FColor::Red, TEXT("完成订单(优先最短剩余时间)"));

	// 通知点餐客人开始进食（订单与客人绑定）
	LastServedGuest = OrderedGuest;
	if (OrderedGuest)
	{
		OrderedGuest->OnOrderServed();
	}
	RecordFirstDayOrderServed();
	return true;
}

bool AOrderSystem::PushFoodsForGuest(const TArray<int>& FoodIDs, AGuestCharacter* TargetGuest, bool bPremiumDish)
{
	if (!IsStarted)
	{
		GEngine->AddOnScreenDebugMessage(-1, 5.0f, FColor::Red, TEXT("上菜失败，游戏已经结束"));
		return false;
	}
	if (!TargetGuest)
	{
		return false;
	}

	const int Num = FoodIDs.Num();

	// 1. 在绑定到该客人的订单里，找出菜品集合完全匹配的候选
	TArray<UOrderHandle*> Candidates;
	for (UOrderHandle* handle : waitList)
	{
		if (!handle || handle->Guest != TargetGuest || handle->IsExpired())
		{
			continue;
		}
		const FOrderData& order = handle->OrderData;
		if (order.FoodIDs.Num() != Num)
		{
			continue;
		}
		// 统计 Foods 中每个 ID 的出现次数，与订单比对
		TMap<int, int> NeedCount;
		for (int id : order.FoodIDs)
		{
			NeedCount.FindOrAdd(id)++;
		}
		bool bMatch = true;
		for (int id : FoodIDs)
		{
			int* p = NeedCount.Find(id);
			if (!p || *p <= 0)
			{
				bMatch = false;
				break;
			}
			(*p)--;
		}
		if (bMatch)
		{
			Candidates.Add(handle);
		}
	}
	if (Candidates.Num() == 0)
	{
		return false;
	}

	// 2. 在该客人的候选订单中选剩余时间比例最少（最紧急）的优先完成
	UOrderHandle* BestHandle = Candidates[0];
	float BestPercent = BestHandle->GetPercent();
	for (UOrderHandle* handle : Candidates)
	{
		const float Percent = handle->GetPercent();
		if (Percent < BestPercent || (Percent == BestPercent
			&& handle->GetOrderTimeout() - handle->waitTime < BestHandle->GetOrderTimeout() - BestHandle->waitTime))
		{
			BestPercent = Percent;
			BestHandle = handle;
		}
	}

	// 3. 完成该订单
	AGuestCharacter* OrderedGuest = BestHandle->Guest;

	ABaseLevelBP::AddScore(this, BestHandle->GetOrderSettlementPrice());
	RecordOrderTiming(*BestHandle);
	RecordKitchenShiftOrder(*BestHandle, bPremiumDish);
	OnFinishOrder.Broadcast(BestHandle, BestHandle->OrderData);
	waitList.Remove(BestHandle);
	GEngine->AddOnScreenDebugMessage(-1, 2, FColor::Red, TEXT("完成订单(针对性上菜)"));

	// 通知点餐客人开始进食（订单与客人绑定）
	LastServedGuest = OrderedGuest;
	if (OrderedGuest)
	{
		OrderedGuest->OnOrderServed();
	}
	RecordFirstDayOrderServed();
	return true;
}

void AOrderSystem::RecordOrderTiming(const UOrderHandle& Order)
{
	if (Order.IsLate())
	{
		ResetOnTimeStreak();
		return;
	}
	OnTimeStreakChanged.Broadcast(++OnTimeStreak);
}

void AOrderSystem::ResetOnTimeStreak()
{
	if (OnTimeStreak != 0)
	{
		OnTimeStreak = 0;
		OnTimeStreakChanged.Broadcast(0);
	}
}

float UOrderHandle::GetPercent()
{
	// 按值保存后无需判空；等待时间为 0 时避免除零（返回 1 表示“刚下单”）
	const float MaxWait = GetOrderMaxWaitTime();
	if (MaxWait > 0.f)
	{
		return FMath::Clamp(1.f - waitTime / MaxWait, 0.f, 1.f);
	}
	return 1.f;
}

/** 句柄的 Outer 是 AOrderSystem（Actor），可由此拿到 World -> GameInstance -> FoodSystem */
static UFoodSystem* GetFoodSystemForHandle(const UOrderHandle* Handle)
{
	UWorld* World = Handle ? Handle->GetWorld() : nullptr;
	if (!World)
	{
		// 兜底：UObject::GetWorld 未解析出世界时，直接沿 Outer 找到订单系统所在世界
		const AOrderSystem* OS = Handle ? Cast<AOrderSystem>(Handle->GetOuter()) : nullptr;
		World = OS ? OS->GetWorld() : nullptr;
	}

	UBaseGameInstance* GI = World ? Cast<UBaseGameInstance>(World->GetGameInstance()) : nullptr;
	return GI ? GI->foodSystem : nullptr;
}

void UOrderHandle::EnsureStatsCached() const
{
	if (bStatsCached)
	{
		return;
	}

	CachedPrice = 0;
	CachedMaxWaitTime = 0.f;
	CachedDisplayName.Reset();
	CachedMachineImageIDs.Reset();

	if (UFoodSystem* FS = GetFoodSystemForHandle(this))
	{
		for (const int32 FoodID : OrderData.FoodIDs)
		{
			const FMenuData Menu = FS->GetMenuData(FoodID);
			if (Menu.FoodID < 0)
			{
				continue;
			}
			CachedPrice += Menu.Price;
			CachedMaxWaitTime = FMath::Max(CachedMaxWaitTime, Menu.MaxWaitTime);

			// 需要的机器（MachineID>0 才记，去重）
			if (Menu.MachineID > 0)
			{
				CachedMachineImageIDs.AddUnique(Menu.MachineID);
			}

			// 显示名：多道菜用 "+" 连接（如“番茄炒蛋+米饭”）
			if (!Menu.FoodName.IsEmpty())
			{
				if (!CachedDisplayName.IsEmpty())
				{
					CachedDisplayName += TEXT("+");
				}
				CachedDisplayName += Menu.FoodName;
			}
		}
	}

	bStatsCached = true;
}

int32 UOrderHandle::GetBaseOrderPrice() const
{
	EnsureStatsCached();
	return CachedPrice;
}

int32 UOrderHandle::GetOrderPrice() const
{
	EnsureStatsCached();
	return WildPriceMultiplier > 1.f ? FMath::RoundToInt(CachedPrice * WildPriceMultiplier) : CachedPrice;
}

void UOrderHandle::SetPrepWindowGraceSeconds(float Seconds)
{
	// 已授予本单的截止时间不回退；关窗只停止给新单授予宽限。
	PrepWindowGraceSeconds = FMath::Max(PrepWindowGraceSeconds, FMath::Max(0.f, Seconds));
}

void UOrderHandle::SetWildOrder(float InPriceMultiplier)
{
	WildPriceMultiplier = FMath::Max(1.f, InPriceMultiplier);
	bIsWildOrder = WildPriceMultiplier > 1.f;
}

void UOrderHandle::InitializePatience(const ULevelOrderCfg* Config, int32 BusinessDay)
{
	// 新手引导：配置的天数里客人耐心值视为无限（等待时间放大到实际不可能超时）
	const bool bInfinitePatience = Config && Config->InfinitePatienceDays.Contains(BusinessDay);
	if (bInfinitePatience)
	{
		constexpr float HugeWait = 1e9f;
		NormalWaitTime = HugeWait;
		MenuWaitTimes.Reset();
		for (const int32 FoodID : OrderData.FoodIDs)
		{
			MenuWaitTimes.Add(FoodID, HugeWait);
		}
		LateServeGraceSeconds = 0.f;
		LateServePriceMultiplier = 1.f;
		return;
	}

	const float Multiplier = Config ? FMath::Max(0.1f, Config->OrderWaitTimeMultiplier) : 1.f;
	LateServeGraceSeconds = Config ? FMath::Max(0.f, Config->LateServeGraceSeconds) : 0.f;
	LateServePriceMultiplier = Config ? FMath::Clamp(Config->LateServePriceMultiplier, 0.f, 1.f) : 1.f;
	EnsureStatsCached();
	NormalWaitTime = CachedMaxWaitTime * Multiplier * CoopWaitTimeScale;
	MenuWaitTimes.Reset();
	if (UFoodSystem* FS = GetFoodSystemForHandle(this))
	{
		for (const int32 FoodID : OrderData.FoodIDs)
		{
			MenuWaitTimes.Add(FoodID, FS->GetMenuData(FoodID).MaxWaitTime * Multiplier * CoopWaitTimeScale);
		}
	}
}

int32 UOrderHandle::GetOrderSettlementPrice() const
{
	const int32 Price = GetOrderPrice();
	return IsLate() ? FMath::RoundToInt(Price * LateServePriceMultiplier) : Price;
}

float UOrderHandle::GetOrderMaxWaitTime(int32 MenuID) const
{
	if (MenuID >= 0)
	{
		const float* Wait = MenuWaitTimes.Find(MenuID);
		return Wait ? *Wait : 0.f;
	}
	return NormalWaitTime;
}

float UOrderHandle::GetOrderTimeout() const
{
	// 备料窗口宽限叠加在原有的迟到宽限之上；窗口结束由订单系统清零，不改 InitializePatience 的结果
	const float TotalGrace = LateServeGraceSeconds + PrepWindowGraceSeconds;
	return NormalWaitTime > 0.f ? NormalWaitTime + TotalGrace : 0.f;
}

bool UOrderHandle::IsLate() const
{
	return NormalWaitTime > 0.f && waitTime >= NormalWaitTime;
}

bool UOrderHandle::IsExpired() const
{
	const float Timeout = GetOrderTimeout();
	return Timeout > 0.f && waitTime >= Timeout;
}

FString UOrderHandle::GetOrderDisplayName(int32 MenuID) const
{
	// 传了菜单 ID：只查这一道菜的菜名
	if (MenuID >= 0)
	{
		if (UFoodSystem* FS = GetFoodSystemForHandle(this))
		{
			const FMenuData Menu = FS->GetMenuData(MenuID);
			if (Menu.FoodID >= 0 && !Menu.FoodName.IsEmpty())
			{
				return Menu.FoodName;
			}
		}
		// 查不到菜名时退化成“菜品<ID>”，避免 UI 出现空白（与 UChairTipsWidget::GetFoodName 一致）
		return FString::Printf(TEXT("菜品%d"), MenuID);
	}

	// 未传：整单显示名（多道菜用 "+" 连接）
	EnsureStatsCached();
	return CachedDisplayName;
}

TArray<int32> UOrderHandle::GetMachineImageIDs() const
{
	EnsureStatsCached();
	return CachedMachineImageIDs;
}

TArray<UTexture2D*> UOrderHandle::GetOrderFoodIcons() const
{
	TArray<UTexture2D*> Icons;

	UFoodSystem* FS = GetFoodSystemForHandle(this);
	if (!FS)
	{
		return Icons;
	}

	// 菜品表 MenuItems 的 key = 食材 ItemID：到 DT_FoodID（FItemActorInfo::Icon）按 ItemID 取图
	TSet<int32> CollectedItems;
	for (const int32 FoodID : OrderData.FoodIDs)
	{
		const FMenuData Menu = FS->GetMenuData(FoodID);
		if (Menu.FoodID < 0)
		{
			continue;
		}

		for (const TPair<int32, int32>& Item : Menu.MenuItems)
		{
			// 同一食材在多道菜里重复出现时只出一张图
			if (CollectedItems.Contains(Item.Key))
			{
				continue;
			}

			if (UTexture2D* Icon = FS->GetItemFoodIcon(Item.Key))
			{
				CollectedItems.Add(Item.Key);
				Icons.Add(Icon);
			}
		}
	}

	return Icons;
}

void UOrderHandle::RefreshOrderStats()
{
	bStatsCached = false;
	EnsureStatsCached();
}

void UOrderHandle::Reset()
{
	waitTime = 0;
}

FOrderData UOrderHandle::GetOrderData() const
{
	return OrderData;
}

