// Sets default values
AOrderSystem::AOrderSystem()
{
 	// Set this actor to call Tick() every frame.  You can turn this off to improve performance if you don't need it.
	PrimaryActorTick.bCanEverTick = true;
}

// Called when the game starts or when spawned
void AOrderSystem::BeginPlay()
{
	Super::BeginPlay();

	// 研究炉解锁菜谱 / 关卡目标解锁食材后，订单池要立刻跟上：
	// 否则新菜得等下一关才点得到，或客人一直点“还没解锁/没食材”的菜
	if (UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr)
	{
		GI->OnRecipesUnlocked.AddDynamic(this, &AOrderSystem::HandleRecipesUnlocked);
		GI->OnIngredientsUnlocked.AddDynamic(this, &AOrderSystem::HandleIngredientsUnlocked);
	}
}

void AOrderSystem::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
	// 解除 GameInstance 广播绑定：GameInstance 跨关卡存活，绑定到本 Actor 会指向已销毁对象
	if (UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr)
	{
		GI->OnRecipesUnlocked.RemoveDynamic(this, &AOrderSystem::HandleRecipesUnlocked);
		GI->OnIngredientsUnlocked.RemoveDynamic(this, &AOrderSystem::HandleIngredientsUnlocked);
		if (GI->businessSimulation && GI->businessSimulation->TimeSystem)
			GI->businessSimulation->TimeSystem->SetGoalDrivenBusiness(false);
	}

	// 清空所有未完成订单：waitList 是 UPROPERTY，句柄会随本 Actor 一起被 GC 回收，无需 AddToRoot。
	waitList.Empty();
	// 解除所有蓝图委托绑定，避免退出时回调到已销毁的蓝图对象
	OnStartOrder.Clear();
	OnFinishOrder.Clear();
	OnFailOrder.Clear();
	OnOrderCanceled.Clear();
	Super::EndPlay(EndPlayReason);
}

// Called every frame
void AOrderSystem::Tick(float DeltaTime)
{
	RefreshKitchenShift();
	if (UBaseGameInstance* GI = Cast<UBaseGameInstance>(GetGameInstance()))
	{
		if (GI->businessSimulation && GI->businessSimulation->TimeSystem)
		{
			UTimeSystem* Time = GI->businessSimulation->TimeSystem;
			const int32 Target = GetFirstDayServiceTarget();
			Time->SetGoalDrivenBusiness(Target > 0);
			// 结算卡前退出后读档：赛季已结算，但经营日期尚未确认换日，直接续到第二天，避免重复收支。
			if (IsStarted && Target > 0 && GetFirstDayOrdersServed() >= Target
				&& !Time->IsEndOfDayReached() && GI->curSaveGameData && GI->curSaveGameData->SeasonDay > 1)
			{
				GI->businessSimulation->SkipNextDaySettlement();
				Time->AdvanceDays(1);
				Time->SetGoalDrivenBusiness(false);
				GI->businessSimulation->Save();
			}
			// 上菜调用栈结束后再日结，避免清场修改正在完成的订单或吞掉品质奖励。
			else if (IsStarted && Target > 0 && GetFirstDayOrdersServed() >= Target && Time->IsBusinessOpen())
				Time->FinishBusinessDayEarly();
		}
	}
	if (IsStarted)
	{
		// 天数变化后重建订单池：菜品可配置 UnlockDay，跨天后才允许出现的菜需要重新入池
		const int32 Today = GetCurrentBusinessDay();
		if (PoolBuiltDay != Today)
		{
			RebuildOrderPool();
		}

		CurTime += DeltaTime;

		// —— 订单超时检查（无论订单来自定时生成还是客人点餐）——
		// 倒序遍历，便于超时后直接从列表移除
		for (int i = waitList.Num() - 1; i >= 0; i--)
		{
			UOrderHandle* orderHandle = waitList[i];
			if (!orderHandle)
			{
				continue;
			}

			orderHandle->waitTime += DeltaTime;
			if (orderHandle->IsExpired())
			{
				// 野味订单有价格倍率，但超时惩罚仍按基础价，避免"只奖励不惩罚"被放大
				ABaseLevelBP::AddScore(this, -orderHandle->GetBaseOrderPrice());
				ResetOnTimeStreak();
				OnFailOrder.Broadcast(orderHandle, orderHandle->OrderData);
				GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, TEXT("订单超时"));

				// 记录绑定客人后移除订单，并通知其离场（订单生命周期与客人绑定）
				AGuestCharacter* OrderedGuest = orderHandle->Guest;
				waitList.RemoveAt(i);

				if (OrderedGuest)
				{
					OrderedGuest->OnOrderFailed();
				}
			}
		}

		// —— 定时自动生成订单（默认关闭）——
		// 关闭后订单只在客人坐下点餐时产生（见 RequestOrderForGuest）。
		if (bAutoGenerateByTime && orderCfg && orderCfg->AppearTimes.Num() > 0)
		{
			int num = orderCfg->AppearTimes.Num();
			if (CurOrderIndex >= num)
			{
				CurOrderIndex = 0;
				CurTime = 0;
				GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, TEXT("最后的订单了"));
				//最后订单		
			}
			else
			{
				auto nextOrder = orderCfg->AppearTimes[CurOrderIndex];
				if (CurTime >= nextOrder.AppearTime && CanAcceptNewOrder())
				{
					// 定时生成的订单同样从"按菜品表构建的订单池"里随机取（不再按 AppearOrderID 索引 Orders）
					if (FOrderData* data = GetRandomOrder())
					{
						UOrderHandle* orderHandle = NewObject<UOrderHandle>(this);
						orderHandle->orderId = OrderID;
						OrderID++;
						orderHandle->OrderData = *data;
						orderHandle->waitTime = 0;
						orderHandle->RefreshOrderStats();
						orderHandle->SetCoopWaitTimeScale(GetCoopWaitTimeScale());
						orderHandle->InitializePatience(orderCfg, GetCurrentBusinessDay());
						waitList.Add(orderHandle);
						OnStartOrder.Broadcast(orderHandle, orderHandle->OrderData);
						CurOrderIndex++;
					}
				}
			}
		}
	}
	Super::Tick(DeltaTime);

}
void AOrderSystem::InitCfg(ULevelOrderCfg* cfg)
{
	orderCfg = cfg;
	waitList.Empty(orderCfg ? orderCfg->Orders.Num() : 0);
	CurOrderIndex = 0;
	// 关卡（重新）开始：配置订单的顺序游标从第一单重新开始
	CurConfigOrderIndex = 0;
	OrderID = 0;
	LastDailyMenuDish = INDEX_NONE;
	// 新的一天：野味订单计数归零（下一次点餐会再按 UTimeSystem::Day 校准）
	WildOrderDay = INDEX_NONE;
	WildOrdersIssuedToday = 0;
	ActivePrepWindowGrace = 0.f;
	bPrepWindowActive = false;

	// 订单池改为按菜品表（MenuDataTable / FMenuData）构建
	RebuildOrderPool();
}

void AOrderSystem::RebuildOrderPool()
{
	ON_SCOPE_EXIT { UpdateKitchenShiftMenu(); };
	OrderPool.Reset();
	OrderWeights.Reset();
	const int32 Today = GetCurrentBusinessDay();
	if (PoolBuiltDay != Today) LastDailyMenuDish = INDEX_NONE;
	PoolBuiltDay = Today;

	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem : nullptr;
	if (!FS)
	{
		UE_LOG(LogTemp, Error, TEXT("[OrderSystem] 构建订单池失败：找不到 UFoodSystem（GameInstance->foodSystem 为空）"));
		if (GEngine)
		{
			GEngine->AddOnScreenDebugMessage(-1, 8.f, FColor::Red,
				TEXT("[订单] 构建订单池失败：GameInstance->foodSystem 为空（请检查 MenuDataTable 配置）"));
		}
		return;
	}

	// 价格 / 等待时间不再写进订单（FOrderData 只留"点了什么"），这里只做数据体检
	int32 BadPrice = 0;
	int32 BadWait = 0;

	// 本关能拿到的食材来源：没有来源的食材不进订单，杜绝“表里加了菜但没摆箱子”的无解订单
	CollectPreparedFoodIDs(CachedPreparedFoodIDs);
	CollectSuppliedItemIDs(CachedSuppliedItemIDs);
	// 本关实际存在的加工机器：菜谱指定的机器不在场，同样做不出来
	CollectAvailableMachineIDs(CachedAvailableMachineIDs);
	RefreshDailyMenu();
	int32 BlockedByLock = 0;
	int32 BlockedBySupply = 0;
	auto IsServableOrLog = [this, FS, &BlockedByLock, &BlockedBySupply](int32 FoodID) -> bool
	{
		FString Reason;
		if (IsMenuServable(FoodID, CachedSuppliedItemIDs, Reason)
			&& IsMenuMachinePresent(FoodID, CachedAvailableMachineIDs, Reason))
		{
			return true;
		}
		if (Reason.Contains(TEXT("未解锁")))
		{
			BlockedByLock++;
		}
		else
		{
			BlockedBySupply++;
		}
		UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 跳过菜品 %d（%s）：%s"), FoodID, *FS->GetMenuData(FoodID).FoodName, *Reason);
		return false;
	};

	// 订单里只存 FoodIDs（菜品表 FoodID），其余信息（价格/等待/菜名/机器）全部由菜品表派生
	auto BuildOrder = [FS, &BadPrice, &BadWait](const TArray<int32>& FoodIDs) -> FOrderData
	{
		FOrderData Data;
		Data.FoodIDs = FoodIDs;

		int32 TotalPrice = 0;
		float MaxWait = 0.f;
		for (const int32 FoodID : FoodIDs)
		{
			const FMenuData Menu = FS->GetMenuData(FoodID);
			if (Menu.FoodID < 0)
			{
				continue;
			}
			TotalPrice += Menu.Price;
			MaxWait = FMath::Max(MaxWait, Menu.MaxWaitTime);
		}

		if (TotalPrice <= 0)
		{
			BadPrice++;
		}
		if (MaxWait <= 0.f)
		{
			BadWait++;
		}
		return Data;
	};

	// 权重：自定义套餐取各菜品 Probabilitys 的平均值
	auto WeightOf = [FS](const TArray<int32>& FoodIDs) -> float
	{
		float Sum = 0.f;
		int32 Count = 0;
		for (const int32 FoodID : FoodIDs)
		{
			const FMenuData Menu = FS->GetMenuData(FoodID);
			if (Menu.FoodID < 0)
			{
				continue;
			}
			Sum += FMath::Max(Menu.Probabilitys, 0.f);
			Count++;
		}
		return Count > 0 ? Sum / static_cast<float>(Count) : 0.f;
	};

	// 1) 关卡里配置的自定义套餐（一单多道菜）：只取 FoodIDs，其余全部由菜品表派生
	if (orderCfg && !orderCfg->bEnableDailyMenu)
	{
		for (const FOrderData& Custom : orderCfg->Orders)
		{
			if (Custom.FoodIDs.Num() == 0)
			{
				continue;
			}
			// 含野外专属菜品的套餐不进常规池：只在备料窗口作为限时野味订单发放
			bool bHasWildMenu = false;
			for (const int32 FoodID : Custom.FoodIDs)
			{
				if (FS->GetMenuData(FoodID).bRequiresWildIngredient)
				{
					bHasWildMenu = true;
					break;
				}
			}
			if (bHasWildMenu)
			{
				continue;
			}

			// 套餐里任何一道菜没解锁 / 食材没来源，整单都不发，避免客人点出做不齐的单
			bool bServable = true;
			for (const int32 FoodID : Custom.FoodIDs)
			{
				if (!IsServableOrLog(FoodID))
				{
					bServable = false;
					break;
				}
			}
			if (!bServable)
			{
				continue;
			}
			OrderPool.Add(BuildOrder(Custom.FoodIDs));
			OrderWeights.Add(WeightOf(Custom.FoodIDs));
		}
	}

	// 2) 菜品表里每道 Probabilitys>0 的菜各成一单（野味菜品除外）
	for (const int32 FoodID : FS->GetFoodIDsByMachine(0))
	{
		const FMenuData Menu = FS->GetMenuData(FoodID);
		if (Menu.FoodID < 0 || Menu.Probabilitys <= 0.f || Menu.bRequiresWildIngredient)
		{
			continue;
		}
		if (orderCfg && orderCfg->bEnableDailyMenu && !DailyMenuIDs.Contains(FoodID))
		{
			continue;
		}
		if (!IsServableOrLog(FoodID))
		{
			continue;
		}

		TArray<int32> FoodIDs;
		FoodIDs.Add(FoodID);
		OrderPool.Add(BuildOrder(FoodIDs));
		OrderWeights.Add(FMath::Max(Menu.Probabilitys, 0.f));
	}

	// 刷新展示数据，但不改变已接订单的等待期限。
	for (UOrderHandle* Handle : waitList)
	{
		if (Handle)
		{
			Handle->RefreshOrderStats();
		}
	}

	if (OrderPool.Num() == 0)
	{
		UE_LOG(LogTemp, Error, TEXT("[OrderSystem] 订单池为空：菜品表里没有可出的菜（检查 Probabilitys>0、菜谱解锁、食材来源），也没有自定义套餐（ULevelOrderCfg::Orders）"));
		if (GEngine)
		{
			GEngine->AddOnScreenDebugMessage(-1, 8.f, FColor::Red,
				TEXT("[订单] 订单池为空！检查菜品 Probabilitys>0、菜谱是否解锁、本关是否摆了对应食材来源"));
		}
	}
	else
	{
		UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 订单池已按菜品表构建：%d 条（含自定义套餐 %d 条；因未解锁跳过 %d、因缺食材/机器跳过 %d）"),
			OrderPool.Num(), orderCfg ? orderCfg->Orders.Num() : 0, BlockedByLock, BlockedBySupply);
		if (BadPrice > 0 || BadWait > 0)
		{
			UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 订单池里有 %d 条价格<=0、%d 条等待时间<=0（请在 MenuDataTable 给菜品配 Price / MaxWaitTime）"),
				BadPrice, BadWait);
		}
	}
}
void AOrderSystem::HandleRecipesUnlocked(const TArray<int32>& UnlockedFoodIDs)
{
	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 菜谱解锁 %d 个，重建订单池"), UnlockedFoodIDs.Num());
	RebuildOrderPool();
	if (orderCfg && orderCfg->bEnableDailyMenu)
	{
		const TArray<int32> Available = GetAvailableDailyDishes();
		for (const int32 ID : UnlockedFoodIDs)
		{
			if (!Available.Contains(ID)) continue;
			PendingTastingIDs.AddUnique(ID);
			if (!DailyMenuIDs.Contains(ID))
			{
				if (DailyMenuIDs.Num() >= FMath::Max(1, orderCfg->DailyMenuCapacity))
					DailyMenuIDs.Pop();
				DailyMenuIDs.Add(ID);
			}
		}
		SaveDailyMenu();
		RebuildOrderPool();
	}
}

TArray<int32> AOrderSystem::GetAvailableDailyDishes() const
{
	TArray<int32> Result;
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem.Get() : nullptr;
	if (!FS) return Result;
	TSet<int32> MenuIngredientIDs = CachedSuppliedItemIDs;
	const int32 Day = GetCurrentBusinessDay();
	if (Day >= 2 && Day <= 3 && UGameplayStatics::GetCurrentLevelName(this) == TEXT("Kitchen_New"))
	{
		// An empty box describes today's stock, not whether this recipe belongs on the menu.
		// Keep the player's menu selections while the opening card tells them what to refill.
		for (TActorIterator<AFoodSpawner> It(GetWorld()); It; ++It)
			if (!It->IsDayLocked()) AddItemSupply(MenuIngredientIDs, It->SpawnItemActorClass);
	}
	for (const int32 ID : FS->GetFoodIDsByMachine(0))
	{
		const FMenuData Menu = FS->GetMenuData(ID);
		FString Reason;
		if (Menu.Price > 0 && Menu.Probabilitys > 0.f && !Menu.bRequiresWildIngredient
			&& IsMenuServable(ID, MenuIngredientIDs, Reason)
			&& IsMenuMachinePresent(ID, CachedAvailableMachineIDs, Reason))
			Result.Add(ID);
	}
	Result.Sort();
	return Result;
}

TArray<int32> AOrderSystem::GetTeachingOrderFoodIDs(int32 Day) const
{
	const FOrderData* Sequence = orderCfg ? orderCfg->DayFoodSequences.Find(Day) : nullptr;
	return Sequence ? Sequence->FoodIDs : TArray<int32>();
}

bool AOrderSystem::IsDailyMenuEditable() const
{
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	const UTimeSystem* TS = GI && GI->businessSimulation ? GI->businessSimulation->TimeSystem.Get() : nullptr;
	return orderCfg && orderCfg->bEnableDailyMenu && TS && !TS->IsBusinessOpen()
		&& GetCurrentBusinessDay() > orderCfg->FixedTutorialThroughDay;
}

void AOrderSystem::SaveDailyMenu() const
{
	if (UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr)
	{
		if (GI->curSaveGameData)
		{
			GI->curSaveGameData->DailyMenuFoodIDs = DailyMenuIDs;
			GI->SaveGameData();
		}
	}
}

void AOrderSystem::RefreshDailyMenu()
{
	if (!orderCfg || !orderCfg->bEnableDailyMenu) return;
	const TArray<int32> Available = GetAvailableDailyDishes();
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	if (DailyMenuIDs.IsEmpty() && GI && GI->curSaveGameData)
		DailyMenuIDs = GI->curSaveGameData->DailyMenuFoodIDs;
	DailyMenuIDs.RemoveAll([&](int32 ID) { return !Available.Contains(ID); });
	const int32 Capacity = FMath::Max(1, orderCfg->DailyMenuCapacity);
	if (DailyMenuIDs.Num() > Capacity) DailyMenuIDs.SetNum(Capacity);
	const bool bNeedsDefault = DailyMenuIDs.IsEmpty();
	for (int32 ID : Available)
	{
		if (DailyMenuIDs.Num() >= Capacity) break;
		if (bNeedsDefault || (bDailyMenuInitialized && !KnownAvailableDishes.Contains(ID)))
			DailyMenuIDs.AddUnique(ID);
	}
	KnownAvailableDishes = TSet<int32>(Available);
	bDailyMenuInitialized = true;
}

bool AOrderSystem::ToggleDailyMenuDish(int32 FoodID)
{
	if (!IsDailyMenuEditable() || !GetAvailableDailyDishes().Contains(FoodID)) return false;
	if (DailyMenuIDs.Contains(FoodID))
	{
		if (DailyMenuIDs.Num() <= 1) return false;
		DailyMenuIDs.Remove(FoodID);
	}
	else
	{
		if (DailyMenuIDs.Num() >= FMath::Max(1, orderCfg->DailyMenuCapacity)) return false;
		DailyMenuIDs.Add(FoodID);
	}
	SaveDailyMenu();
	RebuildOrderPool();
	return true;
}

bool AOrderSystem::TryBuildTastingOrder(FOrderData& OutOrder)
{
	if (!orderCfg || !orderCfg->bEnableDailyMenu
		|| GetCurrentBusinessDay() <= orderCfg->FixedTutorialThroughDay) return false;
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	if (!GI || !GI->curSaveGameData) return false;
	TArray<int32> Candidates = PendingTastingIDs;
	Candidates.Append(DailyMenuIDs);
	for (int32 ID : Candidates)
	{
		if (!DailyMenuIDs.Contains(ID) || GI->curSaveGameData->TastedFoodIDs.Contains(ID)) continue;
		if (ID == LastDailyMenuDish && OrderPool.Num() > 1) continue;
		FString Reason;
		if (!IsMenuServable(ID, CachedSuppliedItemIDs, Reason)
			|| !IsMenuMachinePresent(ID, CachedAvailableMachineIDs, Reason)) continue;
		OutOrder.FoodIDs = {ID};
		PendingTastingIDs.Remove(ID);
		GI->curSaveGameData->TastedFoodIDs.AddUnique(ID);
		GI->SaveGameData();
		return true;
	}
	return false;
}

void AOrderSystem::HandleIngredientsUnlocked(const TArray<int32>& UnlockedIDs)
{
	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 食材解锁 %d 个，重建订单池"), UnlockedIDs.Num());
	RebuildOrderPool();
}

void AOrderSystem::CollectSuppliedItemIDs(TSet<int32>& OutItemIDs) const
{
	OutItemIDs.Reset();
	UWorld* World = GetWorld();
	if (!World)
	{
		return;
	}

	UBaseGameInstance* GI = Cast<UBaseGameInstance>(World->GetGameInstance());
	// 仓库驱动模式下箱子能不能出料取决于当时的库存，不能用“此刻空箱”判定本关没有这种食材
	const bool bWarehouseDriven = GI && GI->bLinkSpawnerToWarehouse;

	for (TActorIterator<AFoodSpawner> It(World); It; ++It)
	{
		// 还没到开放天数的食材箱（例如第 1 天隐藏的番茄箱）不算来源，仓库模式也一样
		if (It->IsDayLocked())
		{
			continue;
		}
		if (bWarehouseDriven || It->CanSpawn())
		{
			AddItemSupply(OutItemIDs, It->SpawnItemActorClass);
		}
	}

	// 野外散布点：当季不长的采集物不算来源，否则会点出“要等到明年”的单
	for (TActorIterator<AItemScatterSpawner> It(World); It; ++It)
	{
		const ESeason Season = It->GetCurrentSeason();
		for (const FScatterSpawnEntry& Entry : It->Entries)
		{
			if (Entry.Seasons.Num() > 0 && !Entry.Seasons.Contains(Season))
			{
				continue;
			}
			AddItemSupply(OutItemIDs, Entry.ItemClass);
		}
	}

	// 可采植株：还没解锁的作物不算来源（对应 IngredientUnlockID 门闩）
	for (TActorIterator<APlant> It(World); It; ++It)
	{
		if (It->IngredientUnlockID >= 0 && GI && !GI->IsIngredientUnlocked(It->IngredientUnlockID))
		{
			continue;
		}
		if (const FPlantInfo* Info = It->PlantInfoRow.GetRow<FPlantInfo>(TEXT("OrderSystem::CollectSuppliedItemIDs")))
		{
			AddItemSupply(OutItemIDs, Info->FruitClass);
		}
	}

	// 猎物掉落（鸡腿 / 鹿肉等）
	for (TActorIterator<AAnimalCharacter> It(World); It; ++It)
	{
		UClass* DropClass = It->DropActorClass.Get();
		if (DropClass && DropClass->IsChildOf(AItemActor::StaticClass()))
		{
			AddItemSupply(OutItemIDs, DropClass);
		}
	}

	// 加工链：上一级有来源且菜谱已解锁时，加工产物也算来源（生蘑菇 → 切好蘑菇）。
	// 只回溯一层，够覆盖“切配后再下锅”这一层，也不至于把整张表递归扫一遍。
	if (GI && GI->foodSystem)
	{
		UFoodSystem* FS = GI->foodSystem;
		for (const int32 FoodID : FS->GetFoodIDsByMachine(0))
		{
			FString Reason;
			if (!IsMenuServable(FoodID, OutItemIDs, Reason))
			{
				continue;
			}
			const FMenuData Menu = FS->GetMenuData(FoodID);
			if (!Menu.CookedActorClass)
			{
				continue;
			}
			if (const AItemActor* OutputCDO = Cast<AItemActor>(Menu.CookedActorClass->GetDefaultObject()))
			{
				if (const int32 OutputID = OutputCDO->GetItemID(); OutputID >= 0)
				{
					OutItemIDs.Add(OutputID);
				}
			}
		}
	}
}

void AOrderSystem::CollectPreparedFoodPortions(TMap<int32, int32>& Available) const
{
	Available.Reset();
	// The last ingredient may already be in the pan when the guest orders.
	for (TActorIterator<ACookingMachine> It(GetWorld()); It; ++It)
	{
		const ACookingMachine* Machine = *It;
		const int32 FoodID = Machine->TargetMenuData.FoodID;
		if (Machine->IsFull && (Machine->IsCooking || Machine->IsFinish)
			&& !Machine->OnFire && !Machine->Repairing && FoodID >= 0)
		{
			++Available.FindOrAdd(FoodID);
		}
	}
	for (TActorIterator<AItemActor> It(GetWorld()); It; ++It)
	{
		const AItemActor* Dish = *It;
		if (!Dish->bPickable || Dish->bIsDirtyPlate || Dish->bIsEmptyPlate
			|| Dish->GetItemState() == EItemState::EIS_Cooking) continue;
		// A plated child is counted by its containing plate; served plates belong to a seat.
		const AActor* Parent = Dish->GetAttachParentActor();
		if (Parent && (Parent->IsA<AItemActor>() || Parent->IsA<AChairSeat>() || Parent->IsA<AGuestCharacter>())) continue;
		if (!Dish->FoodIdArray.IsEmpty())
		{
			for (int32 ID : Dish->FoodIdArray) if (ID >= 0) ++Available.FindOrAdd(ID);
		}
		else if (Dish->GetMenuFoodID() >= 0) ++Available.FindOrAdd(Dish->GetMenuFoodID());
	}
}

void AOrderSystem::CollectPreparedFoodIDs(TSet<int32>& OutFoodIDs) const
{
	OutFoodIDs.Reset();
	TMap<int32, int32> Available;
	CollectPreparedFoodPortions(Available);
	// Reserve existing orders first, so the same last dish cannot promise another order.
	for (const UOrderHandle* Handle : waitList)
		if (Handle)
			for (int32 ID : Handle->OrderData.FoodIDs) --Available.FindOrAdd(ID);
	for (const TPair<int32, int32>& Pair : Available)
		if (Pair.Value > 0) OutFoodIDs.Add(Pair.Key);
}

bool AOrderSystem::IsMenuServable(int32 FoodID, const TSet<int32>& SuppliedItemIDs, FString& OutReason,
	bool bCheckSupplies) const
{
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem : nullptr;
	if (!FS)
	{
		OutReason = TEXT("找不到 UFoodSystem");
		return false;
	}

	const FMenuData Menu = FS->GetMenuData(FoodID);
	if (Menu.FoodID < 0)
	{
		OutReason = TEXT("菜品行无效");
		return false;
	}
	if (!GI->IsRecipeUnlocked(FoodID))
	{
		OutReason = TEXT("菜谱未解锁（需研究炉研究）");
		return false;
	}
	// 菜品配置的最早营业日：例如番茄类菜设为第 2 天，新手第一天的订单里就不会出现
	if (Menu.UnlockDay > 0 && GetCurrentBusinessDay() < Menu.UnlockDay)
	{
		OutReason = FString::Printf(TEXT("未到可点天数（第 %d 天开放）"), Menu.UnlockDay);
		return false;
	}
	if (CachedPreparedFoodIDs.Contains(FoodID)) return true;
	if (Menu.MenuItems.Num() == 0)
	{
		OutReason = TEXT("菜品没配食材");
		return false;
	}
	for (const TPair<int32, int32>& Item : Menu.MenuItems)
	{
		if (bCheckSupplies && Item.Value > 0 && !SuppliedItemIDs.Contains(Item.Key))
		{
			OutReason = FString::Printf(TEXT("缺少食材 ItemID=%d（本关没有对应箱子/植株/采集点）"), Item.Key);
			return false;
		}
	}
	return true;
}

bool AOrderSystem::IsMenuMachinePresent(int32 FoodID, const TSet<int32>& AvailableMachineIDs, FString& OutReason) const
{
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem : nullptr;
	if (!FS)
	{
		OutReason = TEXT("找不到 UFoodSystem");
		return false;
	}

	// MachineID=0 表示通用，任何机器都能做
	const int32 MachineID = FS->GetMenuData(FoodID).MachineID;
	if (MachineID > 0 && !AvailableMachineIDs.Contains(MachineID))
	{
		OutReason = FString::Printf(TEXT("本关没有 MachineID=%d 的加工机器"), MachineID);
		return false;
	}
	return true;
}

void AOrderSystem::CollectAvailableMachineIDs(TSet<int32>& OutMachineIDs) const
{
	OutMachineIDs.Reset();
	UWorld* World = GetWorld();
	if (!World)
	{
		return;
	}
	for (TActorIterator<ACookingMachine> It(World); It; ++It)
	{
		// 商店未解锁的设备（如未购买的榨汁机）不算“本关存在的机器”，否则会出无解订单
		if (It->MachineID > 0 && It->IsShopUnlocked())
		{
			OutMachineIDs.Add(It->MachineID);
		}
	}
}

void AOrderSystem::StartSystem()
{
	IsStarted = true;
}
void AOrderSystem::StopSystem()
{
	IsStarted = false;
	ResetOnTimeStreak();
	// for (int i = 0; i < waitList.Num(); i++)
	// {
	// 	auto handle = waitList[i];
	// 	handle->RemoveFromRoot();
	// }
	//waitList.Empty();
}
void AOrderSystem::ClearAllOrders()
{
	ResetOnTimeStreak();
	// 静默清空：不广播 OnFailOrder，避免切换关卡时误扣分数/声誉。
	// 句柄为本 Actor 创建的 UObject，随 waitList 清空后被 GC 回收。
	waitList.Empty();
}

void AOrderSystem::FailAllPendingOrders()
{
	ResetOnTimeStreak();
	if (waitList.Num() == 0)
	{
		return;
	}

	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 打烊：%d 个未完成订单按超时失败结算"), waitList.Num());
	GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red,
		FString::Printf(TEXT("打烊：%d 个未完成订单计为失败"), waitList.Num()));

	// 与 Tick 中超时同款结算：按基础价扣分、广播失败、让绑定客人离场
	for (int32 i = waitList.Num() - 1; i >= 0; --i)
	{
		UOrderHandle* orderHandle = waitList[i];
		if (!orderHandle)
		{
			continue;
		}
		ABaseLevelBP::AddScore(this, -orderHandle->GetBaseOrderPrice());
		OnFailOrder.Broadcast(orderHandle, orderHandle->OrderData);
		if (AGuestCharacter* OrderedGuest = orderHandle->Guest)
		{
			OrderedGuest->OnOrderFailed();
		}
	}
	waitList.Empty();
}

FOrderData* AOrderSystem::GetRandomOrder()
{
	// Rebuild the pool on demand so callers can use this before the order system starts.
	if (OrderPool.Num() == 0)
	{
		RebuildOrderPool();
		if (OrderPool.Num() == 0)
		{
			return nullptr;
		}
	}

	// Avoid repeating the previous single-dish order whenever another dish is available.
	TArray<int32> CandidateIndices;
	CandidateIndices.Reserve(OrderPool.Num());
	for (int32 Index = 0; Index < OrderPool.Num(); ++Index)
	{
		const FOrderData& Candidate = OrderPool[Index];
		const bool bRepeatsLastDish = LastDailyMenuDish != INDEX_NONE
			&& Candidate.FoodIDs.Num() == 1
			&& Candidate.FoodIDs[0] == LastDailyMenuDish;
		if (!bRepeatsLastDish)
		{
			CandidateIndices.Add(Index);
		}
	}
	if (CandidateIndices.IsEmpty())
	{
		for (int32 Index = 0; Index < OrderPool.Num(); ++Index)
		{
			CandidateIndices.Add(Index);
		}
	}

	float TotalWeight = 0.f;
	for (const int32 Index : CandidateIndices)
	{
		TotalWeight += FMath::Max(OrderWeights.IsValidIndex(Index) ? OrderWeights[Index] : 0.f, 0.f);
	}

	int32 SelectedIndex = CandidateIndices.Last();
	if (TotalWeight <= 0.f)
	{
		SelectedIndex = CandidateIndices[FMath::RandRange(0, CandidateIndices.Num() - 1)];
	}
	else
	{
		float R = FMath::FRandRange(0.f, TotalWeight);
		for (const int32 Index : CandidateIndices)
		{
			R -= FMath::Max(OrderWeights.IsValidIndex(Index) ? OrderWeights[Index] : 0.f, 0.f);
			if (R <= 0.f)
			{
				SelectedIndex = Index;
				break;
			}
		}
	}

	const FOrderData& SelectedOrder = OrderPool[SelectedIndex];
	LastDailyMenuDish = SelectedOrder.FoodIDs.Num() == 1 ? SelectedOrder.FoodIDs[0] : INDEX_NONE;
	return &OrderPool[SelectedIndex];
}

bool AOrderSystem::GetNextConfigOrder(FOrderData& OutOrder, bool* bOutNoneServable)
{
	if (bOutNoneServable)
	{
		*bOutNoneServable = false;
	}
	if (!orderCfg || orderCfg->Orders.Num() == 0)
	{
		return false;
	}

	const int32 NumOrders = orderCfg->Orders.Num();
	int32 SkippedNotServable = 0;

	// 按 Orders 数组顺序依次发单：一轮最多尝试 NumOrders 次，避免全是空配置时死循环
	for (int32 Tried = 0; Tried < NumOrders; ++Tried)
	{
		if (CurConfigOrderIndex >= NumOrders)
		{
			if (!bLoopConfigOrders)
			{
				// 配置里的订单已发完且不循环：不再出单（客人会因点不到单而离场）
				return false;
			}
			CurConfigOrderIndex = 0;
		}

		const FOrderData& Config = orderCfg->Orders[CurConfigOrderIndex];
		const int32 ServedIndex = CurConfigOrderIndex;
		++CurConfigOrderIndex;

		// 没填菜品的配置项跳过，继续取下一项
		if (Config.FoodIDs.Num() == 0)
		{
			continue;
		}

		// 今天还发不了的配置单（例如第 1 天轮到第 2 天才开放的番茄汤）直接跳过，取下一项
		FString Reason;
		if (!IsOrderServableToday(Config, Reason))
		{
			++SkippedNotServable;
			UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 跳过关卡配置第 %d/%d 单：%s"), ServedIndex + 1, NumOrders, *Reason);
			continue;
		}

		OutOrder = Config;
		UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 按关卡配置出单：第 %d/%d 单"), ServedIndex + 1, NumOrders);
		return true;
	}

	if (SkippedNotServable > 0)
	{
		// 一整轮的配置单今天都发不了：交给调用方退回随机订单池（池子已按当天条件过滤）
		if (bOutNoneServable)
		{
			*bOutNoneServable = true;
		}
		UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 关卡配置订单今天都发不了（%d 单被过滤），改用随机订单池"), SkippedNotServable);
		return false;
	}

	UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 关卡订单配置（ULevelOrderCfg::Orders）里没有填菜品的订单，请检查 LevelOrderConfigs 指向的资产"));
	return false;
}

bool AOrderSystem::IsOrderServableToday(const FOrderData& Order, FString& OutReason, bool bCheckSupplies) const
{
	if (Order.FoodIDs.Num() == 0)
	{
		OutReason = TEXT("订单没有菜品");
		return false;
	}
	for (const int32 FoodID : Order.FoodIDs)
	{
		if (!IsMenuServable(FoodID, CachedSuppliedItemIDs, OutReason, bCheckSupplies)
			|| !IsMenuMachinePresent(FoodID, CachedAvailableMachineIDs, OutReason))
		{
			OutReason = FString::Printf(TEXT("菜品 %d %s"), FoodID, *OutReason);
			return false;
		}
	}
	return true;
}

// ==================== 备料窗口 / 限时野味订单（第 16 节 P0） ====================

void AOrderSystem::SetPrepWindowGrace(float Seconds, bool bWindowActive)
{
	ActivePrepWindowGrace = FMath::Max(0.f, Seconds);
	bPrepWindowActive = bWindowActive;

	for (UOrderHandle* Handle : waitList)
	{
		if (Handle)
		{
			Handle->SetPrepWindowGraceSeconds(bWindowActive ? ActivePrepWindowGrace : 0.f);
		}
	}

	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 备料窗口 %s：在场 %d 单宽限 %.1fs"),
		bWindowActive ? TEXT("开启") : TEXT("关闭"), waitList.Num(),
		bWindowActive ? ActivePrepWindowGrace : 0.f);
}

int32 AOrderSystem::GetCurrentBusinessDay() const
{
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UTimeSystem* TS = GI && GI->businessSimulation ? GI->businessSimulation->TimeSystem.Get() : nullptr;
	return TS ? TS->GetBusinessDayNumber() : 0;
}

int32 AOrderSystem::GetEffectiveWildOrderDailyLimit() const
{
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	const int32 Players = GI ? FMath::Max(GI->GetCoopActorCount(), 1) : 1;
	return WildOrderDailyLimit + CoopExtraWildOrdersPerPlayer * (Players - 1);
}

float AOrderSystem::GetCoopWaitTimeScale() const
{
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	const int32 Players = GI ? FMath::Max(GI->GetCoopActorCount(), 1) : 1;
	// 每多 1 人等待 ×(1 - Reduction)；下限 0.5 防止多玩家时订单苛刻到无解
	return FMath::Max(1.f - CoopWaitTimeReductionPerExtraPlayer * (Players - 1), 0.5f);
}

bool AOrderSystem::TryBuildWildOrder(FOrderData& OutOrder, const TSet<int32>& SuppliedItemIDs, const TSet<int32>& AvailableMachineIDs) const
{
	UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	UFoodSystem* FS = GI ? GI->foodSystem : nullptr;
	if (!FS)
	{
		return false;
	}

	TArray<int32> Candidates;
	for (const int32 FoodID : FS->GetFoodIDsByMachine(0))
	{
		const FMenuData Menu = FS->GetMenuData(FoodID);
		if (Menu.FoodID < 0 || !Menu.bRequiresWildIngredient)
		{
			continue;
		}
		// 野味菜同样要“已解锁 + 食材当季有来源 + 本关有对应机器”，否则限时单也是无解订单
		FString Reason;
		if (IsMenuServable(FoodID, SuppliedItemIDs, Reason)
			&& IsMenuMachinePresent(FoodID, AvailableMachineIDs, Reason))
		{
			Candidates.Add(FoodID);
		}
		else
		{
			UE_LOG(LogTemp, Verbose, TEXT("[OrderSystem] 野味订单跳过菜品 %d：%s"), FoodID, *Reason);
		}
	}
	if (Candidates.Num() == 0)
	{
		// 表里没配野味菜品：静默跳过，订单来源完全退回旧逻辑
		return false;
	}

	OutOrder = FOrderData();
	OutOrder.FoodIDs.Add(Candidates[FMath::RandRange(0, Candidates.Num() - 1)]);
	return true;
}

bool AOrderSystem::CanAcceptNewOrder() const
{
	const int32 MaxOrders = orderCfg ? FMath::Max(1, orderCfg->MaxWaitOrderNum) : 4;
	const int32 Target = GetFirstDayServiceTarget();
	return IsStarted && waitList.Num() < MaxOrders
		&& (Target <= 0 || GetFirstDayOrdersServed() + waitList.Num() < Target);
}

int32 AOrderSystem::GetFirstDayServiceTarget() const
{
	return orderCfg && GetCurrentBusinessDay() == 1 ? FMath::Max(0, orderCfg->FirstDayServiceTarget) : 0;
}

int32 AOrderSystem::GetFirstDayOrdersServed() const
{
	const UBaseGameInstance* GI = Cast<UBaseGameInstance>(GetGameInstance());
	return GI && GI->curSaveGameData
		? FMath::Max(0, GI->curSaveGameData->FirstDayOrdersServed)
		: FirstDayOrdersServed;
}

int32 AOrderSystem::GetRemainingFirstDayEggOrders() const
{
	const int32 Remaining = GetFirstDayServiceTarget() - GetFirstDayOrdersServed();
	if (!IsStarted || Remaining <= 0 || UGameplayStatics::GetCurrentLevelName(this) != TEXT("Kitchen_New"))
	{
		return 0;
	}

	const FOrderData* Sequence = orderCfg->DayFoodSequences.Find(1);
	return Sequence && Sequence->FoodIDs.Num() == 1 && Sequence->FoodIDs[0] == 1001 ? Remaining : 0;
}

void AOrderSystem::RecordFirstDayOrderServed()
{
	if (GetFirstDayServiceTarget() <= 0) return;
	FirstDayOrdersServed = GetFirstDayOrdersServed() + 1;
	if (UBaseGameInstance* GI = Cast<UBaseGameInstance>(GetGameInstance()))
	{
		if (GI->curSaveGameData)
		{
			GI->curSaveGameData->FirstDayOrdersServed = FirstDayOrdersServed;
			GI->SaveGameData();
		}
	}
	ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::ServeGuests, -1);
}

UOrderHandle* AOrderSystem::RequestOrderForGuest(AGuestCharacter* Guest)
{
	if (!IsStarted || !Guest)
	{
		return nullptr;
	}

	for (UOrderHandle* Handle : waitList)
	{
		if (Handle && Handle->Guest == Guest)
		{
			return Handle;
		}
	}

	if (!CanAcceptNewOrder())
	{
		return nullptr;
	}

	RefreshKitchenShift();

	// 跨日重置野味订单计数（UTimeSystem::Day；拿不到时钟时固定为 0，行为退化为只发一次）
	const int32 Today = GetCurrentBusinessDay();
	if (Today != WildOrderDay)
	{
		WildOrderDay = Today;
		WildOrdersIssuedToday = 0;
	}

	FOrderData OrderData;
	bool bWildOrder = false;

	// Preparation can refill an empty box after the daily pool was built.
	// Compare live sources before validating the next teaching/configured order;
	// otherwise yesterday's empty egg box can block day two even after restocking.
	TSet<int32> CurrentSuppliedItemIDs;
	TSet<int32> CurrentAvailableMachineIDs;
	TSet<int32> CurrentPreparedFoodIDs;
	CollectSuppliedItemIDs(CurrentSuppliedItemIDs);
	CollectAvailableMachineIDs(CurrentAvailableMachineIDs);
	CollectPreparedFoodIDs(CurrentPreparedFoodIDs);
	if (PoolBuiltDay != Today
		|| !CachedSuppliedItemIDs.Includes(CurrentSuppliedItemIDs)
		|| !CurrentSuppliedItemIDs.Includes(CachedSuppliedItemIDs)
		|| !CachedAvailableMachineIDs.Includes(CurrentAvailableMachineIDs)
		|| !CurrentAvailableMachineIDs.Includes(CachedAvailableMachineIDs)
		|| !CachedPreparedFoodIDs.Includes(CurrentPreparedFoodIDs)
		|| !CurrentPreparedFoodIDs.Includes(CachedPreparedFoodIDs))
	{
		RebuildOrderPool();
	}

	// 新手引导按天覆盖的前 N 单顺序（ULevelOrderCfg::DayFoodSequences）：
	// 优先于常规出单逻辑，依次发放；序列发完后当天剩余订单走随机池（该天不再用配置顺序单）
	bool bTutorialOrder = false;
	const FOrderData* DaySeq = orderCfg ? orderCfg->DayFoodSequences.Find(Today) : nullptr;
	if (DaySeq)
	{
		// The first-day lesson replenishes lost ingredients until all three plates are served.
		const bool bFirstDayEggLesson = GetRemainingFirstDayEggOrders() > 0;
		if (Today != TutorialSeqDay)
		{
			TutorialSeqDay = Today;
			TutorialSeqCursor = 0;
			if (Today == 2 || Today == 3)
				if (const UBaseGameInstance* GI = Cast<UBaseGameInstance>(GetGameInstance()))
					if (GI->curSaveGameData)
						if (const FTutorialDaySave* Saved = GI->curSaveGameData->TutorialDays.Find(Today))
							TutorialSeqCursor = FMath::Clamp(Saved->Served, 0, DaySeq->FoodIDs.Num());
		}
		// 目标制试营业持续使用教学菜，直到完成目标；客人离场后的补位也能正常点单。
		if (GetFirstDayServiceTarget() > 0 && TutorialSeqCursor >= DaySeq->FoodIDs.Num())
		{
			TutorialSeqCursor = 0;
		}
		// 序列里今天还发不了的菜（未到 UnlockDay / 缺食材）跳过，避免引导单绕过当天过滤
		while (TutorialSeqCursor < DaySeq->FoodIDs.Num())
		{
			FOrderData Candidate;
			Candidate.FoodIDs = { DaySeq->FoodIDs[TutorialSeqCursor] };

			FString Reason;
			// In regular service this sequence suggests opening dishes from the player's menu.
			const bool bMenuOpener = orderCfg->bEnableDailyMenu && Today > orderCfg->FixedTutorialThroughDay;
			if (bMenuOpener && !DailyMenuIDs.Contains(Candidate.FoodIDs[0]))
			{
				++TutorialSeqCursor;
				continue;
			}
			if (!IsOrderServableToday(Candidate, Reason, !bFirstDayEggLesson))
			{
				// Keep the promised teaching dish at the front until it is available.
				if (!bMenuOpener && (bFirstDayEggLesson || Today == 2 || Today == 3))
				{
					UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 第 %d 天教学单 %d 暂不可接：%s"),
						Today, TutorialSeqCursor + 1, *Reason);
					return nullptr;
				}
				++TutorialSeqCursor;
				UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 新手引导序列跳过第 %d 单：%s"), TutorialSeqCursor, *Reason);
				continue;
			}

			OrderData = MoveTemp(Candidate);
			++TutorialSeqCursor;
			bTutorialOrder = true;
			UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 新手引导顺序出单：第 %d/%d 单（第 %d 天）"),
				TutorialSeqCursor, DaySeq->FoodIDs.Num(), Today);
			break;
		}
	}

	// 点餐来源：备料窗口内优先发「限时野味订单」（不消耗配置订单序列游标，属窗口内额外机会单）；
	// 否则优先按关卡订单配置（Level_01_Order 等）的顺序依次取；
	// 关闭顺序出单或配置里没有订单时，才退回按菜品表 Probabilitys 的随机订单池
	// （引导序列当天即使序列发完，也直接走随机池，不再用配置顺序单）
	if (!bTutorialOrder)
	{
		bool bUseRandomPool = true;
		if (bEnableWildOrderInPrepWindow && bPrepWindowActive
			&& WildOrderDailyLimit > 0 && WildOrdersIssuedToday < GetEffectiveWildOrderDailyLimit()
			&& TryBuildWildOrder(OrderData, CachedSuppliedItemIDs, CachedAvailableMachineIDs))
		{
			bWildOrder = true;
			WildOrdersIssuedToday++;
			bUseRandomPool = false;
		}
		else if (TryBuildTastingOrder(OrderData))
		{
			bUseRandomPool = false;
		}
		else if (!DaySeq && bUseConfigOrderSequence && orderCfg && orderCfg->Orders.Num() > 0
			&& (!orderCfg->bEnableDailyMenu || Today <= orderCfg->FixedTutorialThroughDay))
		{
			bool bNoneServable = false;
			if (GetNextConfigOrder(OrderData, &bNoneServable))
			{
				bUseRandomPool = false;
			}
			else if (!bNoneServable)
			{
				// 配置订单已按顺序发完（bLoopConfigOrders=false）：不再随机塞单，保持关卡节奏可控
				UE_LOG(LogTemp, Warning, TEXT("[OrderSystem] 关卡订单已发完（不循环），客人 %s 点不到单"), *Guest->GetName());
				return nullptr;
			}
			// bNoneServable：配置单今天都发不了，退回已按当天过滤的随机池
		}

		if (bUseRandomPool && !TryBuildKitchenShiftOrder(OrderData))
		{
			const FOrderData* RandomData = GetRandomOrder();
			if (!RandomData)
			{
				return nullptr;
			}
			OrderData = *RandomData;
		}
	}

	// 客人点餐：生成订单并绑定该客人（订单生命周期 = 客人的等餐周期）
	UOrderHandle* orderHandle = NewObject<UOrderHandle>(this);
	orderHandle->orderId = OrderID;
	OrderID++;
	orderHandle->OrderData = OrderData;
	orderHandle->waitTime = 0.f;
	orderHandle->Guest = Guest;
	orderHandle->SetPrepWindowGraceSeconds(ActivePrepWindowGrace);
	if (bWildOrder)
	{
		orderHandle->SetWildOrder(WildOrderPriceMultiplier);
	}
	orderHandle->RefreshOrderStats();
	orderHandle->SetCoopWaitTimeScale(GetCoopWaitTimeScale());
	orderHandle->InitializePatience(orderCfg, Today);

	LastDailyMenuDish = OrderData.FoodIDs.Num() == 1 ? OrderData.FoodIDs[0] : INDEX_NONE;
	waitList.Add(orderHandle);
	ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::AcceptOrder, -1, Guest);
	OnStartOrder.Broadcast(orderHandle, orderHandle->OrderData);

	if (bWildOrder)
	{
		// HUD 接入点：蓝图监听 OnWildOrderOffered 做正式提示；这里给一条零配置屏幕提示
		OnWildOrderOffered.Broadcast(orderHandle);
		if (GEngine)
		{
			GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Yellow,
				FString::Printf(TEXT("限时野味订单：%s（需要野外食材 · 收益 x%.1f）"),
					*orderHandle->GetOrderDisplayName(), WildOrderPriceMultiplier));
		}
		UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 备料窗口野味订单 %d/%d：%s"),
			WildOrdersIssuedToday, GetEffectiveWildOrderDailyLimit(), *orderHandle->GetOrderDisplayName());
	}

	// 屏幕提示由客人侧（AGuestCharacter::PlaceOrder）统一打印，这里只留日志避免重复刷屏
	UE_LOG(LogTemp, Log, TEXT("[OrderSystem] 客人 %s 点餐：%s（等待 %.0fs）"),
		*Guest->GetName(), *orderHandle->GetOrderDisplayName(), orderHandle->GetOrderMaxWaitTime());

	return orderHandle;
}

bool AOrderSystem::CancelOrderForGuest(AGuestCharacter* Guest)
{
	if (!Guest)
	{
		return false;
	}

	for (int i = 0; i < waitList.Num(); i++)
	{
		UOrderHandle* handle = waitList[i];
		if (handle && handle->Guest == Guest)
		{
			waitList.RemoveAt(i);
			// huanglily：以前这里只改 waitList，订单 UI 的增量缓存收不到移除通知，
			// 客人被老鼠吓跑后订单条会一直挂着。用独立的静默取消事件通知 UI，不计失败不扣分。
			OnOrderCanceled.Broadcast(handle, handle->OrderData);
			return true;
		}
	}
	return false;
}

bool AOrderSystem::PushFoods(const TArray<int>& FoodIDs, bool bPremiumDish)
{
	if (!IsStarted)
	{
		GEngine->AddOnScreenDebugMessage(-1, 5.0f, FColor::Red	 , FString::Printf(TEXT("上菜失败，游戏已经结束")));
		return false;
	}
	const int Num = FoodIDs.Num();

	// 1. 收集所有完全匹配的候选订单（菜品集合与数量一致）
	TArray<UOrderHandle*> Candidates;
	for (UOrderHandle* handle : waitList)
	{
		if (!handle || handle->IsExpired())
		{
			continue;
		}
		const FOrderData& order = handle->OrderData;
		if (order.FoodIDs.Num() != Num)
		{
			continue;
		}
		// 统计 Foods 中每个 ID 的出现次数，与订单比对（避免菜品重复导致的误判）
		TMap<int, int> NeedCount;
		for (int id : order.FoodIDs)
		{
			NeedCount.FindOrAdd(id)++;
		}
		bool bMatch = true;
		for (int id : FoodIDs)
		{
			int* p = NeedCount.Find(id);
			if (!p || *p <= 0)
			{
				bMatch = false;
				break;
			}
			(*p)--;
		}
		if (bMatch)
		{
			Candidates.Add(handle);
		}
	}
	if (Candidates.Num() == 0)
	{
		return false;
	}

	// 2. 在候选中选剩余时间比例最少（GetPercent 最小，最紧急）的订单优先完成
	UOrderHandle* BestHandle = Candidates[0];
	float BestPercent = BestHandle->GetPercent();
	for (UOrderHandle* handle : Candidates)
	{
		const float Percent = handle->GetPercent();
		if (Percent < BestPercent || (Percent == BestPercent
			&& handle->GetOrderTimeout() - handle->waitTime < BestHandle->GetOrderTimeout() - BestHandle->waitTime))
		{
			BestPercent = Percent;
			BestHandle = handle;
		}
	}

	// 3. 完成该订单
	// 先取出绑定客人，避免移除句柄后访问
	AGuestCharacter* OrderedGuest = BestHandle->Guest;

	ABaseLevelBP::AddScore(this, BestHandle->GetOrderSettlementPrice());
	RecordOrderTiming(*BestHandle);
	RecordKitchenShiftOrder(*BestHandle, bPremiumDish);
	OnFinishOrder.Broadcast(BestHandle, BestHandle->OrderData);
	waitList.Remove(BestHandle);
	GEngine->AddOnScreenDebugMessage(-1, 2, FColor::Red, TEXT("完成订单(优先最短剩余时间)"));

	// 通知点餐客人开始进食（订单与客人绑定）
	LastServedGuest = OrderedGuest;
	if (OrderedGuest)
	{
		OrderedGuest->OnOrderServed();
	}
	RecordFirstDayOrderServed();
	return true;
}

bool AOrderSystem::PushFoodsForGuest(const TArray<int>& FoodIDs, AGuestCharacter* TargetGuest, bool bPremiumDish)
{
	if (!IsStarted)
	{
		GEngine->AddOnScreenDebugMessage(-1, 5.0f, FColor::Red, TEXT("上菜失败，游戏已经结束"));
		return false;
	}
	if (!TargetGuest)
	{
		return false;
	}

	const int Num = FoodIDs.Num();

	// 1. 在绑定到该客人的订单里，找出菜品集合完全匹配的候选
	TArray<UOrderHandle*> Candidates;
	for (UOrderHandle* handle : waitList)
	{
		if (!handle || handle->Guest != TargetGuest || handle->IsExpired())
		{
			continue;
		}
		const FOrderData& order = handle->OrderData;
		if (order.FoodIDs.Num() != Num)
		{
			continue;
		}
		// 统计 Foods 中每个 ID 的出现次数，与订单比对
		TMap<int, int> NeedCount;
		for (int id : order.FoodIDs)
		{
			NeedCount.FindOrAdd(id)++;
		}
		bool bMatch = true;
		for (int id : FoodIDs)
		{
			int* p = NeedCount.Find(id);
			if (!p || *p <= 0)
			{
				bMatch = false;
				break;
			}
			(*p)--;
		}
		if (bMatch)
		{
			Candidates.Add(handle);
		}
	}
	if (Candidates.Num() == 0)
	{
		return false;
	}

	// 2. 在该客人的候选订单中选剩余时间比例最少（最紧急）的优先完成
	UOrderHandle* BestHandle = Candidates[0];
	float BestPercent = BestHandle->GetPercent();
	for (UOrderHandle* handle : Candidates)
	{
		const float Percent = handle->GetPercent();
		if (Percent < BestPercent || (Percent == BestPercent
			&& handle->GetOrderTimeout() - handle->waitTime < BestHandle->GetOrderTimeout() - BestHandle->waitTime))
		{
			BestPercent = Percent;
			BestHandle = handle;
		}
	}

	// 3. 完成该订单
	AGuestCharacter* OrderedGuest = BestHandle->Guest;

	ABaseLevelBP::AddScore(this, BestHandle->GetOrderSettlementPrice());
	RecordOrderTiming(*BestHandle);
	RecordKitchenShiftOrder(*BestHandle, bPremiumDish);
	OnFinishOrder.Broadcast(BestHandle, BestHandle->OrderData);
	waitList.Remove(BestHandle);
	GEngine->AddOnScreenDebugMessage(-1, 2, FColor::Red, TEXT("完成订单(针对性上菜)"));

	// 通知点餐客人开始进食（订单与客人绑定）
	LastServedGuest = OrderedGuest;
	if (OrderedGuest)
	{
		OrderedGuest->OnOrderServed();
	}
	RecordFirstDayOrderServed();
	return true;
}

void AOrderSystem::RecordOrderTiming(const UOrderHandle& Order)
{
	if (Order.IsLate())
	{
		ResetOnTimeStreak();
		return;
	}
	OnTimeStreakChanged.Broadcast(++OnTimeStreak);
}

void AOrderSystem::ResetOnTimeStreak()
{
	if (OnTimeStreak != 0)
	{
		OnTimeStreak = 0;
		OnTimeStreakChanged.Broadcast(0);
	}
}

float UOrderHandle::GetPercent()
{
	// 按值保存后无需判空；等待时间为 0 时避免除零（返回 1 表示“刚下单”）
	const float MaxWait = GetOrderMaxWaitTime();
	if (MaxWait > 0.f)
	{
		return FMath::Clamp(1.f - waitTime / MaxWait, 0.f, 1.f);
	}
	return 1.f;
}

/** 句柄的 Outer 是 AOrderSystem（Actor），可由此拿到 World -> GameInstance -> FoodSystem */
static UFoodSystem* GetFoodSystemForHandle(const UOrderHandle* Handle)
{
	UWorld* World = Handle ? Handle->GetWorld() : nullptr;
	if (!World)
	{
		// 兜底：UObject::GetWorld 未解析出世界时，直接沿 Outer 找到订单系统所在世界
		const AOrderSystem* OS = Handle ? Cast<AOrderSystem>(Handle->GetOuter()) : nullptr;
		World = OS ? OS->GetWorld() : nullptr;
	}

	UBaseGameInstance* GI = World ? Cast<UBaseGameInstance>(World->GetGameInstance()) : nullptr;
	return GI ? GI->foodSystem : nullptr;
}

void UOrderHandle::EnsureStatsCached() const
{
	if (bStatsCached)
	{
		return;
	}

	CachedPrice = 0;
	CachedMaxWaitTime = 0.f;
	CachedDisplayName.Reset();
	CachedMachineImageIDs.Reset();

	if (UFoodSystem* FS = GetFoodSystemForHandle(this))
	{
		for (const int32 FoodID : OrderData.FoodIDs)
		{
			const FMenuData Menu = FS->GetMenuData(FoodID);
			if (Menu.FoodID < 0)
			{
				continue;
			}
			CachedPrice += Menu.Price;
			CachedMaxWaitTime = FMath::Max(CachedMaxWaitTime, Menu.MaxWaitTime);

			// 需要的机器（MachineID>0 才记，去重）
			if (Menu.MachineID > 0)
			{
				CachedMachineImageIDs.AddUnique(Menu.MachineID);
			}

			// 显示名：多道菜用 "+" 连接（如“番茄炒蛋+米饭”）
			if (!Menu.FoodName.IsEmpty())
			{
				if (!CachedDisplayName.IsEmpty())
				{
					CachedDisplayName += TEXT("+");
				}
				CachedDisplayName += Menu.FoodName;
			}
		}
	}

	bStatsCached = true;
}

int32 UOrderHandle::GetBaseOrderPrice() const
{
	EnsureStatsCached();
	return CachedPrice;
}

int32 UOrderHandle::GetOrderPrice() const
{
	EnsureStatsCached();
	return WildPriceMultiplier > 1.f ? FMath::RoundToInt(CachedPrice * WildPriceMultiplier) : CachedPrice;
}

void UOrderHandle::SetPrepWindowGraceSeconds(float Seconds)
{
	// 已授予本单的截止时间不回退；关窗只停止给新单授予宽限。
	PrepWindowGraceSeconds = FMath::Max(PrepWindowGraceSeconds, FMath::Max(0.f, Seconds));
}

void UOrderHandle::SetWildOrder(float InPriceMultiplier)
{
	WildPriceMultiplier = FMath::Max(1.f, InPriceMultiplier);
	bIsWildOrder = WildPriceMultiplier > 1.f;
}

void UOrderHandle::InitializePatience(const ULevelOrderCfg* Config, int32 BusinessDay)
{
	// 新手引导：配置的天数里客人耐心值视为无限（等待时间放大到实际不可能超时）
	bUnlimitedPatience = Config && Config->InfinitePatienceDays.Contains(BusinessDay);
	if (bUnlimitedPatience)
	{
		constexpr float HugeWait = 1e9f;
		NormalWaitTime = HugeWait;
		MenuWaitTimes.Reset();
		for (const int32 FoodID : OrderData.FoodIDs)
		{
			MenuWaitTimes.Add(FoodID, HugeWait);
		}
		LateServeGraceSeconds = 0.f;
		LateServePriceMultiplier = 1.f;
		return;
	}

	const float Multiplier = Config ? FMath::Max(0.1f, Config->OrderWaitTimeMultiplier) : 1.f;
	LateServeGraceSeconds = Config ? FMath::Max(0.f, Config->LateServeGraceSeconds) : 0.f;
	LateServePriceMultiplier = Config ? FMath::Clamp(Config->LateServePriceMultiplier, 0.f, 1.f) : 1.f;
	EnsureStatsCached();
	NormalWaitTime = CachedMaxWaitTime * Multiplier * CoopWaitTimeScale;
	MenuWaitTimes.Reset();
	if (UFoodSystem* FS = GetFoodSystemForHandle(this))
	{
		for (const int32 FoodID : OrderData.FoodIDs)
		{
			MenuWaitTimes.Add(FoodID, FS->GetMenuData(FoodID).MaxWaitTime * Multiplier * CoopWaitTimeScale);
		}
	}
}

int32 UOrderHandle::GetOrderSettlementPrice() const
{
	const int32 Price = GetOrderPrice();
	return IsLate() ? FMath::RoundToInt(Price * LateServePriceMultiplier) : Price;
}

float UOrderHandle::GetOrderMaxWaitTime(int32 MenuID) const
{
	if (MenuID >= 0)
	{
		const float* Wait = MenuWaitTimes.Find(MenuID);
		return Wait ? *Wait : 0.f;
	}
	return NormalWaitTime;
}

float UOrderHandle::GetOrderTimeout() const
{
	// 备料窗口宽限叠加在原有的迟到宽限之上；窗口结束由订单系统清零，不改 InitializePatience 的结果
	const float TotalGrace = LateServeGraceSeconds + PrepWindowGraceSeconds;
	return NormalWaitTime > 0.f ? NormalWaitTime + TotalGrace : 0.f;
}

bool UOrderHandle::LeavesBefore(const UOrderHandle* Other) const
{
	if (!Other) return true;
	const float Mine = RemainingUntilDeparture();
	const float Theirs = Other->RemainingUntilDeparture();
	return Mine == Theirs ? orderId < Other->orderId : Mine < Theirs;
}

bool UOrderHandle::IsLate() const
{
	return NormalWaitTime > 0.f && waitTime >= NormalWaitTime;
}

bool UOrderHandle::IsExpired() const
{
	const float Timeout = GetOrderTimeout();
	return Timeout > 0.f && waitTime >= Timeout;
}

FString UOrderHandle::GetOrderDisplayName(int32 MenuID) const
{
	// 传了菜单 ID：只查这一道菜的菜名
	if (MenuID >= 0)
	{
		if (UFoodSystem* FS = GetFoodSystemForHandle(this))
		{
			const FMenuData Menu = FS->GetMenuData(MenuID);
			if (Menu.FoodID >= 0 && !Menu.FoodName.IsEmpty())
			{
				return Menu.FoodName;
			}
		}
		// 查不到菜名时退化成“菜品<ID>”，避免 UI 出现空白（与 UChairTipsWidget::GetFoodName 一致）
		return FString::Printf(TEXT("菜品%d"), MenuID);
	}

	// 未传：整单显示名（多道菜用 "+" 连接）
	EnsureStatsCached();
	return CachedDisplayName;
}

TArray<int32> UOrderHandle::GetMachineImageIDs() const
{
	EnsureStatsCached();
	return CachedMachineImageIDs;
}

TArray<UTexture2D*> UOrderHandle::GetOrderFoodIcons() const
{
	TArray<UTexture2D*> Icons;

	UFoodSystem* FS = GetFoodSystemForHandle(this);
	if (!FS)
	{
		return Icons;
	}

	// 菜品表 MenuItems 的 key = 食材 ItemID：到 DT_FoodID（FItemActorInfo::Icon）按 ItemID 取图
	TSet<int32> CollectedItems;
	for (const int32 FoodID : OrderData.FoodIDs)
	{
		const FMenuData Menu = FS->GetMenuData(FoodID);
		if (Menu.FoodID < 0)
		{
			continue;
		}

		for (const TPair<int32, int32>& Item : Menu.MenuItems)
		{
			// 同一食材在多道菜里重复出现时只出一张图
			if (CollectedItems.Contains(Item.Key))
			{
				continue;
			}

			if (UTexture2D* Icon = FS->GetItemFoodIcon(Item.Key))
			{
				CollectedItems.Add(Item.Key);
				Icons.Add(Icon);
			}
		}
	}

	return Icons;
}

void UOrderHandle::RefreshOrderStats()
{
	bStatsCached = false;
	EnsureStatsCached();
}

void UOrderHandle::Reset()
{
	waitTime = 0;
}

FOrderData UOrderHandle::GetOrderData() const
{
	return OrderData;
}

