	int CurOrderIndex = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Gameplay")
	float CurTime = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Gameplay")
	bool IsStarted = false;

