float ACookingMachine::GetCookSpeedMultiplier() const
{
	float Bonus = 0.f;
	if (const UWorld* W = GetWorld())
	{
		if (const UBaseGameInstance* GI = Cast<UBaseGameInstance>(W->GetGameInstance()))
		{
			if (GI->economySystem)
			{
				Bonus = GI->economySystem->GetOwnedItemCount(EconomyShopItemIDs::AdvancedStove) * CookSpeedBonusPerStove;
				const int32 PanLevel = FMath::Clamp(
					GI->economySystem->GetOwnedItemCount(EconomyShopItemIDs::PanUpgrade), 0, MaxPanUpgradeLevel);
				Bonus += PanLevel * CookSpeedBonusPerPanLevel;
			}
		}
	}
	return FMath::Clamp(1.f - Bonus, MinCookSpeedMultiplier, 1.f);
}

bool ACookingMachine::IsShopUnlocked() const
{
	if (RequiredShopItemID <= 0)
	{
		return true;
	}
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	if (!GI || !GI->economySystem)
	{
		// 经济系统还没就绪时不拦人，避免关卡加载早期把机器锁死
		return true;
	}
	return GI->economySystem->GetOwnedItemCount(RequiredShopItemID) > 0;
}

void ACookingMachine::RefreshShopLock()
{
	if (RequiredShopItemID <= 0)
	{
		return;
	}
	const bool bUnlocked = IsShopUnlocked();
	if (bHideUntilUnlocked)
	{
		SetActorHiddenInGame(!bUnlocked);
		SetActorEnableCollision(bUnlocked);
	}
}

float ACookingMachine::GetRequiredCookTime() const
{
	return TargetMenuData.CookingTime * GetCookSpeedMultiplier();
}

bool ACookingMachine::UsesAttention() const
{
	const UBaseGameInstance* GI = GetWorld() ? Cast<UBaseGameInstance>(GetWorld()->GetGameInstance()) : nullptr;
	const UTimeSystem* TS = GI && GI->businessSimulation ? GI->businessSimulation->TimeSystem.Get() : nullptr;
	return TargetMenuData.bRequiresAttention && TS && TS->Day >= TargetMenuData.AttentionUnlockDay;
}

bool ACookingMachine::IsAttentionAvailable() const
{
	if (!UsesAttention() || !IsCooking || !IsFull || IsFinish || OnFire || bAttentionPerformed) return false;
	const float Start = GetRequiredCookTime() * FMath::Clamp(TargetMenuData.AttentionProgress, 0.1f, 0.8f);
	const float Elapsed = CurCookingTime + OverCookTime;
	return Elapsed >= Start && Elapsed <= Start + FMath::Max(1.f, TargetMenuData.AttentionWindowSeconds);
}

bool ACookingMachine::PerformAttention()
{
	if (!IsAttentionAvailable()) return false;
	bAttentionPerformed = true;
	UpdateProgressWidget();
	return true;
}

/** 取 Actor 的世界包围盒高度（Extent 为半高，乘 2 得到实际高度） */
static float GetActorHeight(AActor* InActor)
{
	FVector Origin, Extent;
	InActor->GetActorBounds(false, Origin, Extent);
	return Extent.Z * 2.0f;
}

void ACookingMachine::SpawnCookedActor()
{
	// 开关未开启则不生成（走原始逻辑：保持完成状态等待玩家取餐，久了会煮糊）
	if (!bSpawnOnCookingFinish) return;

	// —— 洗碗机闭环：只有存在"空闲碟子"时才自动生成成品 ——
	// 没有空闲碟子 → 本次不出成品，直接 return 走回原始逻辑：
	// 机器保持"完成/加热"状态并继续累计煮过头时间，最终煮糊/着火（OnFire）；
	// 玩家把脏碟交还洗碗机后，下一次烹饪才能正常出菜。
	const bool bUseServingPlate = bConsumePlateOnFinish
		|| UGameplayStatics::GetCurrentLevelName(this) == TEXT("Kitchen_New");
	APlateSystem* PlateSys = bUseServingPlate ? FindPlateSystem() : nullptr;
	if (bUseServingPlate)
	{
		if (!PlateSys)
		{
			// 场景/关卡里根本没有盘子系统：视为"没有碟子限制"，正常出成品（不消耗碟子），
			// 否则会因为缺少配置而永远无法出菜。只在每锅第一次打印警告便于排查。
			if (!bNoPlateNotified)
			{
				bNoPlateNotified = true;
				UE_LOG(LogTemp, Warning,
					TEXT("[CookingMachine] 找不到盘子系统(APlateSystem) → 本次按[无碟子限制]出成品，不消耗碟子"));
			}
		}
		else if (PlateSys->GetAvailablePlates() <= 0)
		{
			bWaitingForPlate = true;
			if (!bNoPlateNotified)
			{
				bNoPlateNotified = true;
				UE_LOG(LogTemp, Warning,
					TEXT("[CookingMachine] 没有空闲碟子（可用 %d/%d），本次不出成品 → 走回原始逻辑（继续加热会煮糊）"),
					PlateSys->GetAvailablePlates(), PlateSys->TotalCount);
				if (GEngine)
				{
					GEngine->AddOnScreenDebugMessage(-1, 4.f, FColor::Red,
						TEXT("[烹饪] 没有干净碟子了！菜会煮糊，请把桌上的碟子送进洗碗机"));
				}
				OnNoPlateAvailable();
			}
			return;
		}
	}

	// 清理已被销毁/拾取走的成品记录
	for (int32 i = CookedActorStack.Num() - 1; i >= 0; --i)
	{
		if (!CookedActorStack[i].Get())
		{
			CookedActorStack.RemoveAt(i);
		}
	}

	// 成品类以菜单数据（FMenuData，DT_Foods）为准：
	// 如番茄+鸡蛋 → 匹配到"番茄炒鸡蛋"菜品，取其 CookedActorClass 生成 1 个成品
	// 菜品行未配置成品类时，用机器上的默认类兜底
	TSubclassOf<AActor> ClassToSpawn = TargetMenuData.CookedActorClass ? TargetMenuData.CookedActorClass : CookedActorClass;

	// 没有可生成的成品类，走原始逻辑（保持完成状态，等待玩家取餐）
	if (!ClassToSpawn) return;

	// 累计当前已叠放成品的总高度
	float StackHeight = 0.f;
	for (const TObjectPtr<AActor>& Stacked : CookedActorStack)
	{
		StackHeight += GetActorHeight(Stacked);
	}

	// 在指定位置向上偏移叠高（未摆放 SpawnPoint 时使用机器自身位置）
	const FVector BaseLocation = SpawnPoint ? SpawnPoint->GetComponentLocation() : GetActorLocation();
	const FRotator SpawnRotation = SpawnPoint ? SpawnPoint->GetComponentRotation() : GetActorRotation();

	FActorSpawnParameters SpawnParams;
	SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;
	SpawnParams.Owner = this;

	// 达到叠高上限：不再走自动生成成品逻辑，直接走原始逻辑
	// （机器保持"完成"状态，等待玩家通过取餐 GetMenuFood 拿菜）
	if (MaxStackCount > 0 && CookedActorStack.Num() >= MaxStackCount)
	{
		UE_LOG(LogTemp, Log, TEXT("[CookingMachine] 成品已叠满 %d 层，本次不生成，等待玩家取餐"), CookedActorStack.Num());
		return;
	}

	// 能走到这里说明确实有空闲碟子（前面已校验）：生成成品消耗 1 个
	const FVector SpawnLocation = BaseLocation + FVector(0.f, 0.f, StackHeight + StackSpacing * CookedActorStack.Num());
	AActor* CookedActor = GetWorld()->SpawnActor<AActor>(ClassToSpawn, SpawnLocation, SpawnRotation, SpawnParams);
	if (!CookedActor) return; // 生成失败，走原始逻辑

	CookedActorStack.Add(CookedActor); // 记入堆栈，下一个成品会叠在它上面
	UE_LOG(LogTemp, Log, TEXT("[CookingMachine] 烹饪完成，已生成成品: %s，当前叠放层数: %d"), *CookedActor->GetName(), CookedActorStack.Num());

	// 把成品对应的菜单菜品 ID 写到物品上，供上菜台校验“是否在菜单中”
	if (AItemActor* Item = Cast<AItemActor>(CookedActor))
	{
		if (PlateSys)
		{
			if (!Item->ReserveServingPlate(*PlateSys))
			{
				CookedActorStack.Remove(CookedActor);
				CookedActor->Destroy();
				bWaitingForPlate = true;
				return;
			}
		}
		Item->SetMenuFoodID(TargetMenuData.FoodID);

		// 成品品质 = 所有入锅食材中的最差品质（任一食材为次品则成品为次品；全为佳品才为佳品）
		EIngredientQuality DishQuality = EIngredientQuality::Premium;
		for (AItemActor* FoodActor : FoodActors)
		{
			if (FoodActor)
			{
				DishQuality = MinQuality(DishQuality, FoodActor->GetIngredientQuality());
			}
		}
		if (UsesAttention() && DishQuality != EIngredientQuality::Inferior)
			DishQuality = bAttentionPerformed ? EIngredientQuality::Premium : EIngredientQuality::Normal;
		Item->SetIngredientQuality(DishQuality);
		Item->ShowPremiumDishFeedback();

		// 启用成品腐烂：未被玩家拾取的成品会自动销毁（放下后重新计时）
		if (bProductsDecay)
		{
			Item->EnableDecay(ProductDecayTime);
		}
	}

	// 已生成成品：删除锅里的食材，并将锅的状态恢复成初始状态
	for (AItemActor* FoodActor : FoodActors)
	{
		if (FoodActor)
		{
			FoodActor->Destroy();
		}
	}
	FoodActors.Empty();
	ResetFoodData();
}

bool ACookingMachine::AddFoodMateral(int32 FoodMaterialID)
{
	bool canAdd = CanAddFoodMateral(FoodMaterialID);
	if (canAdd)
	{
		FMenuData tmpMenu;
		CheckMenu(FoodMaterialID, tmpMenu);
		if (tmpMenu.FoodID != TargetMenuData.FoodID) //转换目标菜单
		{
			TargetMenuData = tmpMenu;
			TargetMateiralCount = TargetMenuData.GetNumOfItems();
		}
		if (!FoodMaterial.Contains(FoodMaterialID))
			FoodMaterial.Add(FoodMaterialID,1);
		else
			FoodMaterial[FoodMaterialID] += 1;

		CurFoodCount = 0;
		for (auto fmat : FoodMaterial)
		{
			CurFoodCount += fmat.Value;
		}
		GreenCookTime = (CurFoodCount * GetRequiredCookTime() / TargetMateiralCount) ; //更新煮糊时间（含灶台加速）
		OverCookTime = 0;
		if (CurFoodCount == TargetMateiralCount)
		{
			IsFull = true;
		}
		OnAddFoodMateiral();//添加食材回调
		ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::AddToCooker, FoodMaterialID, this);
		if (!IsCooking  && tmpMenu.CookingTime>0.0f)
		{
			IsCooking = true;
			CurCookingTime = 0;
			OnStartCookingEvent();//开始烹饪
		}
		//这里新添加的食材可能会让烹饪时间变为0，直接完成烹饪，用于测试直接上屎菜
		if (tmpMenu.CookingTime==0.0f)
		{
			IsCooking = false;
			IsFinish = true;
			OnCookingFinishEvent();//完成烹饪
			SpawnCookedActor();//尝试自动生成成品（叠满或开关关闭时走原始逻辑：保持完成状态，等待玩家取餐）
		}
	}
	return canAdd;
}

void ACookingMachine::UpdateKnifeAnim()
{
	// 约定：骨骼刀 Tag 为 CookingKnife，待机静态刀为 CookingKnifeIdle，
	// 切菜动画配在骨骼刀组件自带的 AnimationData 上；这里只按 IsCooking 切换状态。
	static const FName KnifeTag(TEXT("CookingKnife"));
	static const FName IdleKnifeTag(TEXT("CookingKnifeIdle"));

	USkeletalMeshComponent* Knife = FindComponentByTag<USkeletalMeshComponent>(KnifeTag);
	if (!Knife || !Knife->AnimationData.AnimToPlay)
	{
		return;
	}

	const bool bWantPlay = IsCooking;
	if (Knife->IsVisible() == bWantPlay)
	{
		return;
	}

	if (UStaticMeshComponent* IdleKnife = FindComponentByTag<UStaticMeshComponent>(IdleKnifeTag))
	{
		IdleKnife->SetVisibility(!bWantPlay, true);
	}
	Knife->SetVisibility(bWantPlay, true);

	if (bWantPlay)
	{
		Knife->PlayAnimation(Knife->AnimationData.AnimToPlay, true);
	}
	else
	{
		Knife->Stop();
	}
}

// Called every frame
void ACookingMachine::Tick(float DeltaTime)
{
	// ============ 交互范围调试可视化（控制台 Shoot.DebugInteract 1） ============
	// 白=有玩家在盒内，灰=无人靠近。用来核对灶台的实际判定范围是否覆盖台面。
	if (InteractionDebug::IsEnabled() && BoxCollision)
	{
		const FColor C = LocalPlayer ? InteractionDebug::ColorInRange() : InteractionDebug::ColorIdle();
		DrawDebugBox(GetWorld(), BoxCollision->GetComponentLocation(),
			BoxCollision->GetScaledBoxExtent(), BoxCollision->GetComponentQuat(),
			C, false, 0.f, 0, 1.5f);
	}

	if (bWaitingForPlate)
	{
		const APlateSystem* Plates = FindPlateSystem();
		if (Plates && Plates->GetAvailablePlates() > 0)
		{
			bWaitingForPlate = false;
			SpawnCookedActor();
		}
	}
	else if (OnFire && Repairing)//维修中
	{
		CurRepairTime += DeltaTime;
		if (CurRepairTime >= TargetRepairTime)//完成维修
		{
			ResetFoodData();
			OnRepairFinish();
		}
	}
	else
	{
		if (IsCooking)
		{
			float NewCookingTime = CurCookingTime + DeltaTime;
			if (NewCookingTime > GetRequiredCookTime() )
			{
				OverCookTime += DeltaTime;
			}
			else
			{
				CurCookingTime = NewCookingTime;
			}
			if (OverCookTime >= MaxOverCookTime && TargetMenuData.CanOverCook && !OnFire) //超时
			{
				OnFire = true;
				IsCooking = false;
				IsFinish = false;
				CurRepairTime = 0;
				CurCookingTime = 0;
				OverCookTime = 0;
				OnOverCookEvent();
			}
			if ((CurCookingTime + OverCookTime) >= GetRequiredCookTime() && !IsFinish && IsFull) //熟了（含灶台加速）
			{
				IsFinish = true;
				ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::CookDish, TargetMenuData.FoodID, this);
				if (!TargetMenuData.CanOverCook)
				{
					IsCooking =  false;
				}
				OnCookingFinishEvent();
				SpawnCookedActor();//尝试自动生成成品（叠满或开关关闭时走原始逻辑：保持完成状态，等待玩家取餐）
			}
		}
	}
	UpdateKnifeAnim();
	UpdateProgressWidget();
	Super::Tick(DeltaTime);

}

void ACookingMachine::OnBoxOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
{
	//FString ActorNamel = OtherActor->GetName();
	//GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, FString::Printf(TEXT("Actor名称: %s"), *ActorNamel) );
	IPickupInterface* PickupInterface = Cast<IPickupInterface>(OtherActor);
	if (PickupInterface)
	{
		// 注册进角色的灶台候选集：由角色按距离选最近的一台，取代“后进入者胜”
		PickupInterface->AddOverlappingCookMachine(this);

		//当tips没有被其他玩家占用的时候。
		//E 提示默认统一由角色显示（每个本地玩家一份），这里的 TipsWidget 只做位置锚点，不再自己显示。
		if(LocalPlayer == nullptr && TipsWidget && InteractionPromptTuning::UseDeviceOwnPromptTips())
		{
			TipsWidget->SetVisibility(true);
			if (APawn* AP = Cast<APawn>(OtherActor))
			{
				if (APlayerController* APC = Cast<APlayerController>(AP->GetController()))
				{
					// 从玩家控制器中拿到本地玩家对象
					if (ULocalPlayer* Player = APC->GetLocalPlayer())
					{
						// 为这个组件设置OwnerPlayer，这样引擎就知道它属于谁了
						TipsWidget->SetOwnerPlayer(Player);
						LocalPlayer = Player;
					}
				}
			}
		}
	}

}

void ACookingMachine::OnBoxEndOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex)
{
	IPickupInterface* PickupInterface = Cast<IPickupInterface>(OtherActor);
	if (PickupInterface)
	{
		// 只注销自己：角色会从剩余候选里重选最近的灶台，
		// 不会像以前那样把另一台（仍在范围内）的目标一起清掉
		PickupInterface->RemoveOverlappingCookMachine(this);
		if(LocalPlayer)
		{
			if (APawn* AP = Cast<APawn>(OtherActor))
			{
				if (APlayerController* APC = Cast<APlayerController>(AP->GetController()))
				{
					// 从玩家控制器中拿到本地玩家对象
					if (ULocalPlayer* Player = APC->GetLocalPlayer())
					{
						// 为这个组件设置OwnerPlayer，这样引擎就知道它属于谁了
						if(LocalPlayer == Player) 
						{
							TipsWidget->SetVisibility(false);
							LocalPlayer = nullptr;
						}
					}
				}
			}
		}

	}

}

