	TestEqual(TEXT("First actual report creates one record"), Season->DailyFinancialHistory.Num(), 1);
	if (Season->DailyFinancialHistory.Num() == 1)
	{
		const FDailyFinancialRecord& Record = Season->DailyFinancialHistory[0];
