	/** 内置兜底档位（数据表缺失 / 缺行时仍能用） */
	struct FBuiltinTier
	{
		int32 Stars;
		int32 MinScore;
		const TCHAR* Name;
		const TCHAR* Phrase;
		const TCHAR* Accent;
	};

	const FBuiltinTier BuiltinTiers[] = {
		{5, 90, TEXT("完美"), TEXT("大丰收！"),      TEXT("F0B93F")},
		{4, 75, TEXT("出色"), TEXT("干得漂亮！"),    TEXT("527D32")},
		{3, 60, TEXT("合格"), TEXT("稳步前进"),      TEXT("28657F")},
