	/** 回弹缓动：0 → 1 的过程中会先冲过 1 再落回 */
	float EaseOutBack(float T)
	{
		constexpr float C1 = 1.70158f;
		constexpr float C3 = C1 + 1.f;
		const float U = T - 1.f;
		return 1.f + C3 * U * U * U + C1 * U * U;
	}

	float EaseOutCubic(float T)
	{
		const float U = 1.f - T;
		return 1.f - U * U * U;
	}

