	const FBuiltinTier BuiltinTiers[] = {
		{5, 90, TEXT("完美"), TEXT("大丰收！"),      TEXT("F0B93F")},
		{4, 75, TEXT("出色"), TEXT("干得漂亮！"),    TEXT("527D32")},
