void USeasonDailyCardWidget::BindNextDayButton()
{
	if (!NextDayButton)
	{
		return;
	}
	NextDayButton->OnClicked.RemoveDynamic(this, &USeasonDailyCardWidget::HandleNextDayClicked);
	NextDayButton->OnClicked.AddDynamic(this, &USeasonDailyCardWidget::HandleNextDayClicked);
}

void USeasonDailyCardWidget::BindDesignerWidgets()
{
	auto FindWidget = [this](const TCHAR* Name) { return WidgetTree->FindWidget(Name); };
	CardBorder = Cast<UBorder>(FindWidget(TEXT("Card")));
	BannerBorder = Cast<UBorder>(FindWidget(TEXT("Banner")));
	DayText = Cast<UTextBlock>(FindWidget(TEXT("Day")));
	ScoreText = Cast<UTextBlock>(FindWidget(TEXT("ScoreText")));
	ScoreBadgeBox = Cast<USizeBox>(FindWidget(TEXT("ScoreBadge")));
	PhraseText = Cast<UTextBlock>(FindWidget(TEXT("Phrase")));
	GapText = Cast<UTextBlock>(FindWidget(TEXT("Gap")));
	RevenueText = Cast<UTextBlock>(FindWidget(TEXT("MetricValue0")));
	ProfitText = Cast<UTextBlock>(FindWidget(TEXT("MetricValue2")));
	NextDayButton = Cast<UButton>(FindWidget(TEXT("NextDayButton")));
	NextDayButtonText = Cast<UTextBlock>(FindWidget(TEXT("NextDayLabel")));

	StarIcons.Reset();
	for (int32 Index = 0; Index < 5; ++Index)
	{
		StarIcons.Add(Cast<UImage>(FindWidget(*FString::Printf(TEXT("Star%d"), Index))));
	}
	ReasonTexts.Reset();
	ReasonRows.Reset();
	ReasonPassChips.Reset();
	ReasonFailIcons.Reset();
	for (int32 Index = 0; Index < 3; ++Index)
	{
		ReasonTexts.Add(Cast<UTextBlock>(FindWidget(*FString::Printf(TEXT("Reason%d"), Index))));
		ReasonRows.Add(Cast<UBorder>(FindWidget(*FString::Printf(TEXT("ReasonRow%d"), Index))));
		ReasonPassChips.Add(Cast<UBorder>(FindWidget(*FString::Printf(TEXT("ReasonPass%d"), Index))));
		ReasonFailIcons.Add(Cast<UImage>(FindWidget(*FString::Printf(TEXT("ReasonFail%d"), Index))));
	}
	BindNextDayButton();
}

void USeasonDailyCardWidget::Apply(const USeasonSystem* Season)
{
	if (!Season || !CardBorder)
	{
		return;
	}

	const int32 StarCount = ResolveStarCount(Season);
	FString TierName, Phrase, Gap;
	FLinearColor Accent;
	ResolveTier(StarCount, Season->LastGradeScore, TierName, Phrase, Gap, Accent);

	const FDailyFinancialRecord* Record = Season->DailyFinancialHistory.IsEmpty() ? nullptr : &Season->DailyFinancialHistory.Last();
	const int32 ReportDay = Record ? Record->Day : Season->SeasonDay;
	const int32 Revenue = Record ? Record->Revenue : 0;
	const int32 Profit = Record ? Record->Revenue - Record->OperatingExpense : Season->LastDailyNet;
	const FLinearColor ProfitInk = DailyCardColor(Profit >= 0 ? TEXT("527D32") : TEXT("A54351"));

	if (DayText)
	{
		DayText->SetText(FText::FromString(FString::Printf(TEXT("第 %d / %d 天    ·    第 %d 幕"),
			ReportDay, Season->Config.SeasonDays,
			(ReportDay - 1) / FMath::Max(1, Season->Config.DaysPerAct) + 1)));
	}
	if (PhraseText)
	{
		PhraseText->SetText(FText::FromString(TierName.IsEmpty() ? Phrase : TierName + TEXT(" · ") + Phrase));
		PhraseText->SetColorAndOpacity(FSlateColor(Accent));
	}
	if (GapText)
	{
		GapText->SetText(FText::FromString(Gap));
	}
	if (RevenueText)
	{
		RevenueText->SetText(Record ? FText::AsNumber(Revenue) : FText::FromString(TEXT("暂无记录")));
		RevenueText->SetColorAndOpacity(FSlateColor(DailyCardColor(TEXT("527D32"))));
	}
	if (ProfitText)
	{
		ProfitText->SetText(FText::FromString(Record
			? (Profit > 0 ? FString(TEXT("+")) + FText::AsNumber(Profit).ToString() : FText::AsNumber(Profit).ToString())
			: (Profit > 0 ? FString(TEXT("+")) + FText::AsNumber(Profit).ToString() : FText::AsNumber(Profit).ToString())));
		ProfitText->SetColorAndOpacity(FSlateColor(ProfitInk));
	}
	if (ScoreText)
	{
		ScoreText->SetText(FText::FromString(FString::FromInt(FMath::Clamp(Season->LastGradeScore, 0, 100))));
		ScoreText->SetColorAndOpacity(FSlateColor(Accent));
	}
	if (UBorder* Ring = Cast<UBorder>(WidgetTree->FindWidget(TEXT("ScoreRing"))))
	{
		Ring->SetBrush(FSlateRoundedBoxBrush(FLinearColor::Transparent, 72.f, Accent, 4.f));
	}

	// 理由与星星的最终值先算好，演出时逐条亮出；数字保持静态（测试与阅读都稳定）
	RevealSeason = const_cast<USeasonSystem*>(Season);
	RevealStarCount = StarCount;

	if (bInteractive && !bRevealFinished)
	{
		StartReveal(Season);
	}
	else
	{
		ApplyFinalVisual(Season);
	}
}

void USeasonDailyCardWidget::SetStarLit(int32 Index, bool bLit)
{
	if (!StarIcons.IsValidIndex(Index) || !StarIcons[Index])
	{
		return;
	}
	FSlateBrush Brush;
	Brush.SetResourceObject(bLit ? GoldStarTexture : GreyStarTexture);
	Brush.DrawAs = ESlateBrushDrawType::Image;
	Brush.ImageSize = FVector2D(StarArtSize, StarArtSize);
	StarIcons[Index]->SetBrush(Brush);
}

void USeasonDailyCardWidget::ApplyStarPose(int32 Index, float Scale, float AngleDegrees)
{
	if (!StarIcons.IsValidIndex(Index) || !StarIcons[Index])
	{
		return;
	}
	StarIcons[Index]->SetRenderScale(FVector2D(Scale));
	StarIcons[Index]->SetRenderTransformAngle(AngleDegrees);
}

void USeasonDailyCardWidget::ApplyReasonRow(int32 Index, bool bPassed, const FText& Text)
{
	if (UTextBlock* Reason = ReasonTexts.IsValidIndex(Index) ? ReasonTexts[Index].Get() : nullptr)
	{
		Reason->SetText(Text);
		Reason->SetColorAndOpacity(FSlateColor(DailyCardColor(bPassed ? TEXT("6B4A28") : TEXT("8B5E4C"))));
	}
	if (UBorder* PassChip = ReasonPassChips.IsValidIndex(Index) ? ReasonPassChips[Index].Get() : nullptr)
	{
		PassChip->SetVisibility(bPassed ? ESlateVisibility::HitTestInvisible : ESlateVisibility::Collapsed);
	}
	if (UImage* FailIcon = ReasonFailIcons.IsValidIndex(Index) ? ReasonFailIcons[Index].Get() : nullptr)
	{
		FailIcon->SetVisibility(bPassed ? ESlateVisibility::Collapsed : ESlateVisibility::HitTestInvisible);
	}
}

void USeasonDailyCardWidget::ApplyFinalVisual(const USeasonSystem* Season)
{
	if (!Season)
	{
		return;
	}
	FString TierName, Phrase, Gap;
	FLinearColor Accent;
	ResolveTier(RevealStarCount, Season->LastGradeScore, TierName, Phrase, Gap, Accent);

	for (int32 Index = 0; Index < StarIcons.Num(); ++Index)
	{
		SetStarLit(Index, Index < RevealStarCount);
		ApplyStarPose(Index, 1.f, 0.f);
		if (StarIcons[Index])
		{
			StarIcons[Index]->SetRenderOpacity(1.f);
		}
	}
	if (BannerBorder)
	{
		BannerBorder->SetRenderScale(FVector2D(1.f));
		BannerBorder->SetRenderOpacity(1.f);
	}
	if (PhraseText)
	{
		PhraseText->SetText(FText::FromString(TierName.IsEmpty() ? Phrase : TierName + TEXT(" · ") + Phrase));
		PhraseText->SetColorAndOpacity(FSlateColor(Accent));
		PhraseText->SetRenderScale(FVector2D(1.f));
		PhraseText->SetRenderTranslation(FVector2D::ZeroVector);
	}
	if (GapText)
	{
		GapText->SetText(FText::FromString(Gap));
		GapText->SetRenderTranslation(FVector2D::ZeroVector);
	}

	const FDailyFinancialRecord* Record = Season->DailyFinancialHistory.IsEmpty() ? nullptr : &Season->DailyFinancialHistory.Last();
	const int32 Revenue = Record ? Record->Revenue : 0;
	const int32 Profit = Record ? Record->Revenue - Record->OperatingExpense : Season->LastDailyNet;
	const TArray<FReasonLine> Lines = ResolveReasons(Season, Revenue, Profit);
	for (int32 Index = 0; Index < ReasonTexts.Num(); ++Index)
	{
		UBorder* Row = ReasonRows.IsValidIndex(Index) ? ReasonRows[Index].Get() : nullptr;
		if (Row)
		{
			Row->SetRenderOpacity(1.f);
			Row->SetRenderTranslation(FVector2D::ZeroVector);
			Row->SetVisibility(Index < Lines.Num() ? ESlateVisibility::HitTestInvisible : ESlateVisibility::Collapsed);
		}
		if (UTextBlock* Reason = ReasonTexts[Index].Get())
		{
			if (Index < Lines.Num())
			{
				ApplyReasonRow(Index, Lines[Index].bPassed,
					FText::FromString(StripReasonGlyph(Lines[Index].Text)));
				Reason->SetVisibility(ESlateVisibility::HitTestInvisible);
				Reason->SetRenderOpacity(1.f);
				Reason->SetRenderTranslation(FVector2D::ZeroVector);
			}
			else
			{
				ApplyReasonRow(Index, true, FText::GetEmpty());
				Reason->SetVisibility(ESlateVisibility::Collapsed);
			}
		}
	}
	if (PhraseText)
	{
		PhraseText->SetRenderOpacity(1.f);
	}
	if (GapText)
	{
		GapText->SetRenderOpacity(1.f);
	}
}

void USeasonDailyCardWidget::PlayRevealCue(USoundBase* Sound, float Volume, float Pitch) const
{
	if (Sound)
	{
		UGameplayStatics::PlaySound2D(this, Sound, Volume, Pitch);
	}
}

void USeasonDailyCardWidget::StartReveal(const USeasonSystem* Season)
{
	if (!Season)
	{
		return;
	}
	bRevealActive = true;
	RevealTime = 0.f;
	RevealStarsShown = 0;
	RevealReasonsShown = 0;

	for (int32 Index = 0; Index < StarIcons.Num(); ++Index)
	{
		SetStarLit(Index, false);
		ApplyStarPose(Index, 0.2f, -24.f);
		if (StarIcons[Index])
		{
			StarIcons[Index]->SetRenderOpacity(0.f);
		}
	}
	if (BannerBorder)
	{
		BannerBorder->SetRenderScale(FVector2D(0.86f));
		BannerBorder->SetRenderOpacity(0.f);
	}
	if (PhraseText)
	{
		PhraseText->SetText(FText::FromString(TEXT("结算中…")));
		PhraseText->SetRenderOpacity(0.f);
		PhraseText->SetRenderTranslation(FVector2D(0.f, 10.f));
	}
	if (GapText)
	{
		GapText->SetText(FText::GetEmpty());
		GapText->SetRenderOpacity(0.f);
		GapText->SetRenderTranslation(FVector2D(0.f, 10.f));
	}
	const FDailyFinancialRecord* RevealRecord = Season->DailyFinancialHistory.IsEmpty() ? nullptr : &Season->DailyFinancialHistory.Last();
	const int32 RevealRevenue = RevealRecord ? RevealRecord->Revenue : 0;
	const int32 RevealProfit = RevealRecord ? RevealRecord->Revenue - RevealRecord->OperatingExpense : Season->LastDailyNet;
	const int32 RevealLineCount = ResolveReasons(Season, RevealRevenue, RevealProfit).Num();
	for (int32 Index = 0; Index < ReasonTexts.Num(); ++Index)
	{
		if (UTextBlock* Reason = ReasonTexts[Index].Get())
		{
			Reason->SetText(FText::GetEmpty());
			Reason->SetRenderOpacity(1.f);
			Reason->SetRenderTranslation(FVector2D::ZeroVector);
			Reason->SetVisibility(Index < RevealLineCount ? ESlateVisibility::HitTestInvisible : ESlateVisibility::Collapsed);
		}
		if (UBorder* Row = ReasonRows.IsValidIndex(Index) ? ReasonRows[Index].Get() : nullptr)
		{
			Row->SetRenderOpacity(0.f);
			Row->SetRenderTranslation(FVector2D(-26.f, 0.f));
			Row->SetVisibility(Index < RevealLineCount ? ESlateVisibility::HitTestInvisible : ESlateVisibility::Collapsed);
		}
	}
}

void USeasonDailyCardWidget::UpdateReveal(float DeltaTime)
{
	if (!bRevealActive)
	{
		return;
	}
	RevealTime += DeltaTime;

	// Banner 弹入
	if (BannerBorder)
	{
		const float T = FMath::Clamp((RevealTime - RevealBannerAt) / RevealBannerDur, 0.f, 1.f);
		BannerBorder->SetRenderScale(FVector2D(FMath::Lerp(0.86f, 1.f, EaseOutBack(T))));
		BannerBorder->SetRenderOpacity(FMath::Clamp(T * 2.4f, 0.f, 1.f));
	}

	const USeasonSystem* Season = RevealSeason.Get();
	if (!Season)
	{
		FinishReveal();
		return;
	}

	// 五星依次弹出；点亮的星再补一次弹跳
	for (int32 Index = 0; Index < StarIcons.Num() && StarIcons[Index]; ++Index)
	{
		const float IntroStart = RevealStarIntroStart + Index * RevealStarIntroStep;
		const float IntroT = FMath::Clamp((RevealTime - IntroStart) / RevealStarIntroDur, 0.f, 1.f);
		if (IntroT <= 0.f)
		{
			continue;
		}
		float Scale = FMath::Lerp(0.2f, 1.f, EaseOutBack(IntroT));
		float Angle = -24.f * (1.f - EaseOutCubic(IntroT));
		if (Index < RevealStarsShown)
		{
			const float LightStart = RevealStarLightStart + Index * RevealStarLightStep;
			const float BounceT = FMath::Clamp((RevealTime - LightStart) / RevealStarBounceDur, 0.f, 1.f);
			const float Kick = FMath::Sin(PI * BounceT) * FMath::Pow(1.f - BounceT, 0.4f);
			Scale *= 1.f + 0.5f * Kick;
			Angle += 10.f * Kick;
		}
		ApplyStarPose(Index, Scale, Angle);
		StarIcons[Index]->SetRenderOpacity(FMath::Clamp(IntroT * 2.6f, 0.f, 1.f));
	}

	// 达标星依次点亮
	for (int32 Index = RevealStarsShown; Index < RevealStarCount && Index < StarIcons.Num(); ++Index)
	{
		const float LightStart = RevealStarLightStart + Index * RevealStarLightStep;
		if (RevealTime < LightStart)
		{
			break;
		}
		SetStarLit(Index, true);
		PlayRevealCue(RowTickSound, 0.42f, 0.94f + 0.07f * Index);
		++RevealStarsShown;
	}

	// 定性文案 + 差距提示
	if (RevealTime >= RevealPhraseAt)
	{
		FString TierName, Phrase, Gap;
		FLinearColor Accent;
		ResolveTier(RevealStarCount, Season->LastGradeScore, TierName, Phrase, Gap, Accent);
		if (PhraseText && PhraseText->GetText().ToString() == TEXT("结算中…"))
		{
			PhraseText->SetText(FText::FromString(TierName.IsEmpty() ? Phrase : TierName + TEXT(" · ") + Phrase));
			PhraseText->SetColorAndOpacity(FSlateColor(Accent));
			PlayRevealCue(RowTickSound, 0.6f, 1.2f);
		}
		if (PhraseText)
		{
			const float T = FMath::Clamp((RevealTime - RevealPhraseAt) / 0.35f, 0.f, 1.f);
			PhraseText->SetRenderOpacity(T);
			PhraseText->SetRenderTranslation(FVector2D(0.f, 10.f * (1.f - EaseOutCubic(T))));
		}
		if (GapText)
		{
			GapText->SetText(FText::FromString(Gap));
			const float T = FMath::Clamp((RevealTime - RevealPhraseAt - 0.12f) / 0.35f, 0.f, 1.f);
			GapText->SetRenderOpacity(T);
			GapText->SetRenderTranslation(FVector2D(0.f, 10.f * (1.f - EaseOutCubic(T))));
		}
	}

	// 理由整行滑入
	const FDailyFinancialRecord* Record = Season->DailyFinancialHistory.IsEmpty() ? nullptr : &Season->DailyFinancialHistory.Last();
	const int32 Revenue = Record ? Record->Revenue : 0;
	const int32 Profit = Record ? Record->Revenue - Record->OperatingExpense : Season->LastDailyNet;
	const TArray<FReasonLine> Lines = ResolveReasons(Season, Revenue, Profit);
	for (int32 Index = 0; Index < ReasonTexts.Num(); ++Index)
	{
		if (Index >= Lines.Num())
		{
			break;
		}
		const float Start = RevealReasonStart + Index * RevealReasonStep;
		if (RevealTime < Start)
		{
			continue;
		}
		if (Index >= RevealReasonsShown)
		{
			if (UTextBlock* Reason = ReasonTexts[Index].Get())
			{
				ApplyReasonRow(Index, Lines[Index].bPassed, FText::FromString(StripReasonGlyph(Lines[Index].Text)));
				Reason->SetVisibility(ESlateVisibility::HitTestInvisible);
			}
			RevealReasonsShown = Index + 1;
			PlayRevealCue(RowTickSound, 0.3f, 1.05f + 0.05f * Index);
		}
		const float T = FMath::Clamp((RevealTime - Start) / 0.3f, 0.f, 1.f);
		if (UBorder* Row = ReasonRows.IsValidIndex(Index) ? ReasonRows[Index].Get() : nullptr)
		{
			Row->SetRenderOpacity(T);
			Row->SetRenderTranslation(FVector2D(-26.f * (1.f - EaseOutCubic(T)), 0.f));
		}
	}

	// 高星在最后点亮的星星落下后给一声庆祝
	if (RevealStarCount >= 4 && RevealStarsShown == RevealStarCount)
	{
		const float CelebrateAt = RevealStarLightStart + (RevealStarCount - 1) * RevealStarLightStep + 0.2f;
		if (RevealTime - DeltaTime < CelebrateAt && RevealTime >= CelebrateAt)
		{
			PlayRevealCue(WinSound, 0.45f);
		}
	}

	if (RevealTime >= RevealDoneAt)
	{
		FinishReveal();
	}
}

void USeasonDailyCardWidget::FinishReveal()
{
	if (!bRevealActive)
	{
		return;
	}
	bRevealActive = false;
	bRevealFinished = true;
	if (const USeasonSystem* Season = RevealSeason.Get())
	{
		ApplyFinalVisual(Season);
	}
}

void USeasonDailyCardWidget::NativeTick(const FGeometry& MyGeometry, float InDeltaTime)
{
	Super::NativeTick(MyGeometry, InDeltaTime);
	if (!bShowing || !CardBorder)
	{
		return;
	}
	if (!LastLayoutSize.Equals(MyGeometry.GetLocalSize(), 1.f))
	{
		ApplyLayout(bInteractive);
	}
	Elapsed += InDeltaTime;
	UpdateReveal(InDeltaTime);

	if (bInteractive)
	{
		HudSuppressAccum += InDeltaTime;
		if (HudSuppressAccum >= HudSuppressInterval)
		{
			HudSuppressAccum = 0.f;
			SuppressOtherHud(GetWorld());
		}
	}

	float Alpha = 1.f;
	if (Elapsed < CardFadeInSeconds)
	{
		Alpha = Elapsed / CardFadeInSeconds;
	}
	else if (!bInteractive && Elapsed > CardHoldSeconds)
	{
		Alpha = 1.f - (Elapsed - CardHoldSeconds) / CardFadeOutSeconds;
	}
	Alpha = FMath::Clamp(Alpha, 0.f, 1.f);
	CardBorder->SetRenderOpacity(Alpha);
	CardBorder->SetRenderTranslation(GetSlideOffset(Alpha));

	if (!bInteractive && Elapsed >= CardHoldSeconds + CardFadeOutSeconds)
	{
		bShowing = false;
		CardBorder->SetVisibility(ESlateVisibility::Collapsed);
	}
}

void USeasonDailyCardWidget::NativeDestruct()
{
	const bool bWasAwaiting = IsAwaitingNextDay();
	if (bInteractive)
	{
		SetUIInputEnabled(false);
	}
	bShowing = false;
	bInteractive = false;
	bRevealActive = false;
	if (APlayerController* PC = OwnerController.Get())
	{
		ActiveCards.Remove(TWeakObjectPtr<APlayerController>(PC));
	}
	if (bWasAwaiting && !AnyInteractiveCardShowing())
	{
		RestoreOtherHud();
	}
	Super::NativeDestruct();
}

