	float NightIntensity = 0.05f;

	/** 正午太阳颜色（偏白） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Time|Sun")
	FLinearColor NoonColor = FLinearColor(1.f, 0.98f, 0.92f);
	/** 日出 / 日落颜色（偏暖橙） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Time|Sun")
	FLinearColor SunsetColor = FLinearColor(1.f, 0.55f, 0.2f);
	/** 夜晚颜色（偏冷蓝） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Time|Sun")
