void AShootCharacter::DoMove(float Right, float Forward)
{
	if (GetController() != nullptr)
	{
		// 移动输入断开过至少一帧才允许取消，避免按住方向键时按 E 被立即打断
		const uint64 Frame = GFrameCounter;
		if (Frame > LastMoveInputFrame + 1)
		{
			bInteractCancelArmed = true;
		}
		LastMoveInputFrame = Frame;

		if (IsMoveLockedByInteraction())
		{
			return;
		}
		if (IsCancelableInteractionPlaying())
		{
			if (!bInteractCancelArmed || FVector2D(Right, Forward).Size() < InteractCancelInputThreshold)
			{
				return;
			}
			CancelInteractionByMovement();
		}

		const FRotator Rotation = GetController()->GetControlRotation();
		const FRotator YawRotation(0, Rotation.Yaw, 0);

		const FVector ForwardDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);

		const FVector RightDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);

		AddMovementInput(ForwardDirection, Forward);
		AddMovementInput(RightDirection, Right);
	}
}

void AShootCharacter::DoLook(float Yaw, float Pitch)
{
	if (GetController() != nullptr)
	{
		// 仅保留左右旋转，禁止上下俯仰；俯视模式固定俯仰角，鼠标纵向不再改变视角
		AddControllerYawInput(Yaw);
		// 俯视 / 进入过渡期间禁用俯仰；已不在区域内（含退出过渡）立刻响应，
		// 否则退出时俯仰会被丢掉两三秒，手感发木
		if (bRotationPicth && !bUseTopDownCamera)
		{
			AddControllerPitchInput(Pitch);
		}

	}
}

void AShootCharacter::UpdateCameraAreaState()
{
	if (!bAutoSwitchCameraByAreaVolume || GetWorld() == nullptr)
	{
		return;
	}

	const FVector Location = GetActorLocation();
	// 已在区域内时查询半径向外扩张，形成回差，避免站在边界上视角反复切换
	const float ExtraRadius = bInsideCameraArea ? CameraAreaHysteresis : 0.0f;

	bool bInside = false;
	for (TActorIterator<ACameraAreaVolume> It(GetWorld()); It; ++It)
	{
		const ACameraAreaVolume* Area = *It;
		if (Area != nullptr && Area->bCameraAreaActive && Area->IsLocationInside(Location, ExtraRadius))
		{
			bInside = true;
			break;
		}
	}

	bInsideCameraArea = bInside;
	bUseTopDownCamera = bInside;
}

void AShootCharacter::UpdateCameraView()
{
	if (CameraBoom == nullptr)
	{
		return;
	}

	const bool bWasTopDown = bUseTopDownCamera;
	UpdateCameraAreaState();

	if (!bUseTopDownCamera && (bWasTopDown || !bCameraViewInitialized))
	{
		if (AController* CameraController = GetController())
		{
			FRotator EntryRotation = CameraController->GetControlRotation();
			EntryRotation.Pitch = ThirdPersonEntryPitch;
			CameraController->SetControlRotation(EntryRotation);
		}
	}

	const float DeltaTime = GetWorld() ? GetWorld()->GetDeltaSeconds() : 0.016f;
	const float TargetAlpha = bUseTopDownCamera ? 1.0f : 0.0f;

	if (!bCameraViewInitialized)
	{
		CameraViewAlpha = TargetAlpha;
		bCameraViewInitialized = true;
	}
	else if (CameraModeBlendSpeed > 0.0f)
	{
		// 退出比进入快：第三人称的纵向视角要尽快回到鼠标方向
		const float BlendSpeed = TargetAlpha < CameraViewAlpha
			? FMath::Max(CameraModeExitBlendSpeed, 0.1f)
			: CameraModeBlendSpeed;
		CameraViewAlpha = FMath::FInterpTo(CameraViewAlpha, TargetAlpha, DeltaTime, BlendSpeed);
		if (FMath::IsNearlyEqual(CameraViewAlpha, TargetAlpha, 0.001f))
		{
			CameraViewAlpha = TargetAlpha;
		}
	}
	else
	{
		CameraViewAlpha = TargetAlpha;
	}
	CameraBoom->ProbeChannel = ECC_GameTraceChannel4;
	CameraBoom->bDoCollisionTest = true;

	// 两种视角统一由世界旋转驱动：切换 bUsePawnControlRotation / 绝对旋转的瞬间会硬跳
	CameraBoom->bUsePawnControlRotation = false;
	if (!CameraBoom->IsUsingAbsoluteRotation())
	{
		CameraBoom->SetUsingAbsoluteRotation(true);
	}

	const FRotator ControlRotation = GetControlRotation();
	const FRotator ThirdPersonRotation(ControlRotation.Pitch, ControlRotation.Yaw, 0.0f);

	FRotator TopDownRotation(TopDownPitch, 0.0f, 0.0f);
	if (bTopDownYawFollowsControl)
	{
		TopDownRotation.Yaw = ControlRotation.Yaw;
	}

	// 两个目标朝向之间按混合权重球面插值，过渡时俯仰、朝向连续变化
	const FRotator DesiredRotation = FQuat::Slerp(
		ThirdPersonRotation.Quaternion(),
		TopDownRotation.Quaternion(),
		CameraViewAlpha).Rotator();
	CameraBoom->SetWorldRotation(DesiredRotation);

	// 臂长随同一权重过渡，保证距离和俯仰同步到位
	const float TargetArm = FMath::Lerp(ThirdPersonArmLength, TopDownArmLength, CameraViewAlpha);
	CameraBoom->TargetArmLength = ArmLengthInterpSpeed > 0.0f
		? FMath::FInterpTo(CameraBoom->TargetArmLength, TargetArm, DeltaTime, ArmLengthInterpSpeed)
		: TargetArm;
}

void AShootCharacter::DoJumpStart()
{
	const UWorld* World = GetWorld();
	if (!World)
	{
		Jump();
		return;
	}

	if (CanJump())
	{
		Jump();
		JumpBufferExpireTime = 0.0;
		return;
	}

	// huanglily：空中按下时先记缓冲，落地那一帧自动补跳，减少“明明按了却没跳”的挫败感
	if (JumpBufferTime > 0.f)
	{
		JumpBufferExpireTime = World->GetTimeSeconds() + JumpBufferTime;
	}
}

bool AShootCharacter::CanJumpInternal_Implementation() const
{
	return Super::CanJumpInternal_Implementation() || CanCoyoteJump();
}

void AShootCharacter::OnJumped_Implementation()
{
	Super::OnJumped_Implementation();

	bUsedAirJump = true;
}

bool AShootCharacter::CanCoyoteJump() const
{
	const UWorld* World = GetWorld();
	const UCharacterMovementComponent* Move = GetCharacterMovement();
	if (!World || !Move || CoyoteTime <= 0.f || bUsedAirJump || Move->IsMovingOnGround())
	{
		return false;
	}
	return static_cast<float>(World->GetTimeSeconds() - LastGroundedTime) <= CoyoteTime;
}

void AShootCharacter::UpdateJumpAssist()
{
	const UWorld* World = GetWorld();
	const UCharacterMovementComponent* Move = GetCharacterMovement();
	if (!World || !Move)
	{
		return;
	}

	const double Now = World->GetTimeSeconds();
	if (Move->IsMovingOnGround())
	{
		LastGroundedTime = Now;
		bUsedAirJump = false;

		if (JumpBufferExpireTime > 0.0 && Now <= JumpBufferExpireTime && CanJump())
		{
			Jump();
			JumpBufferExpireTime = 0.0;
		}
		return;
	}

	if (JumpBufferExpireTime <= 0.0)
	{
		return;
	}
	if (Now > JumpBufferExpireTime)
	{
		JumpBufferExpireTime = 0.0;
		return;
	}
	if (CanJump())
	{
		Jump();
		JumpBufferExpireTime = 0.0;
	}
}

void AShootCharacter::DoJumpEnd()
{
	StopJumping();
}



