TArray<int32> AShootCharacter::GetHeldServingFoodIDs() const
{
	return IsValid(PickingItem) && !PickingItem->bIsDirtyPlate && !PickingItem->bIsEmptyPlate
		? AChairSeat::GetDishFoodIDs(PickingItem) : TArray<int32>();
}

AChairSeat* AShootCharacter::GetPromptedServingSeat()
{
	AChairSeat* Seat = Cast<AChairSeat>(InteractionPromptTarget);
	return Seat && !IsInteractionAnimPlaying() && Seat->MatchesServingDish(this, GetHeldServingFoodIDs()) ? Seat : nullptr;
}

void AShootCharacter::RefreshBestChairSeat()
{
	// 客人身上的交互已并入餐桌，玩家现在唯一的下单 / 上菜入口就是椅子。
	// 一张桌子通常有两把椅子（各自一个 AChairSeat 实例），站在桌边时两把都在范围里：
	// 若只按距离选，可能选中旁边那把空椅子，按 E 只得到"暂时没有客人入座"。
	// 因此优先在"此刻真能交互"的椅子里选（能点单 / 能上菜 / 能收空碟），都没有才退回最近的一把。
	for (int32 i = OverlappingChairSeats.Num() - 1; i >= 0; --i)
	{
		if (!IsValid(OverlappingChairSeats[i]))
		{
			OverlappingChairSeats.RemoveAtSwap(i);
		}
	}

	const TArray<int32> DishIDs = GetHeldServingFoodIDs();
	AChairSeat* Urgent = nullptr;
	AChairSeat* Aimed = nullptr;
	float BestAim = -1.f;
	float SecondAim = -1.f;
	AChairSeat* BestActive = nullptr;
	float BestActiveScore = FLT_MAX;
	AChairSeat* BestAny = nullptr;
	float BestAnyScore = FLT_MAX;

	for (AChairSeat* Seat : OverlappingChairSeats)
	{
		if (!Seat || !HasInteractionLineOfSight(Seat))
		{
			continue;
		}

		if (Seat->MatchesServingDish(this, DishIDs))
		{
			if (!Urgent || Seat->BoundOrder->LeavesBefore(Urgent->BoundOrder))
			{
				Urgent = Seat;
			}
			const FVector Offset = Seat->GetSitTransform().GetLocation() - GetActorLocation();
			if (Offset.SizeSquared2D() <= FMath::Square(190.f))
			{
				const float Aim = FVector::DotProduct(GetActorForwardVector().GetSafeNormal2D(), Offset.GetSafeNormal2D());
				if (Aim > BestAim)
				{
					SecondAim = BestAim;
					BestAim = Aim;
					Aimed = Seat;
				}
				else
				{
					SecondAim = FMath::Max(SecondAim, Aim);
				}
			}
		}
		const float Score = GetFacingWeightedDistance(Seat);
		if (Score < BestAnyScore)
		{
			BestAnyScore = Score;
			BestAny = Seat;
		}

		// 此刻按 E 真能办成事（点单 / 上菜 / 收空碟）的椅子优先：
		// 同桌一把在用餐、一把在等点单时，不会因为用餐那把更近就把点单入口挡掉
		const bool bActionable = Seat->CanPlayerTakeOrder(this)
			|| Seat->CanPlayerCollectPlate(this)
			|| (PickingItem && !PickingItem->bIsDirtyPlate && Seat->CanPlayerServeDish(this));
		if (bActionable && Score < BestActiveScore)
		{
			BestActiveScore = Score;
			BestActive = Seat;
		}
	}

	OverlappingChairSeat = BestActive ? BestActive : BestAny;
	if (Urgent)
	{
		const bool bClearAim = BestAim >= 0.90f && BestAim - SecondAim >= 0.12f;
		OverlappingChairSeat = bClearAim ? Aimed : Urgent;
	}
}

