void AShootCharacter::RushStart(const FInputActionValue& Value)
{
	if (bIsSprinting)
	{
		return;
	}
	// 死亡 / 修理 / 攻击中不允许冲刺（这些状态下移动本身受限，强行提速会打架）
	if (CharacterState == ECharacterState::ECS_Dead
		|| CharacterState == ECharacterState::ECS_Repairing
		|| CharacterActionState == ECharacterActionState::EAS_Attacking)
	{
		return;
	}

	bIsSprinting = true;

	UCharacterMovementComponent* Move = GetCharacterMovement();
	Move->MaxWalkSpeed = SprintSpeed;
	Move->MaxAcceleration = SprintAcceleration;
	Move->RotationRate = FRotator(0.f, SprintRotationRate, 0.f);

	// 起步脉冲默认关闭：速度阶跃（600→900 一帧完成）会让弹簧臂相机先被甩开再追上，
	// 视觉上就是镜头猛地往前一突。现在靠 SprintAcceleration 在 ~0.06s 内平滑到速。
	if (bSprintInstantBurst && Move->IsMovingOnGround())
	{
		const FVector Dir = FVector(Move->Velocity.X, Move->Velocity.Y, 0.f).GetSafeNormal();
		if (!Dir.IsNearlyZero())
		{
			Move->Velocity = Dir * SprintSpeed;
		}
	}

	TargetFOV = SprintFOV; // FOV 与相机跟随在 Tick 中平滑逼近
}

void AShootCharacter::RushEnd(const FInputActionValue& Value)
{
	if (!bIsSprinting)
	{
		return;
	}
	bIsSprinting = false;

	UCharacterMovementComponent* Move = GetCharacterMovement();
	Move->MaxWalkSpeed = WalkSpeed;
	Move->MaxAcceleration = WalkAcceleration;
	Move->RotationRate = FRotator(0.f, WalkRotationRate, 0.f);

	TargetFOV = NormalFOV; // 松开后靠 BrakingDeceleration 自然回落，不硬切速度
}

void AShootCharacter::Pick(const FInputActionValue& Value)
{
	// 记录"E 正被按住"：长按由 TickRangePick 转为范围拾取（短按仍然只做一次普通交互）。
	// 缓冲补执行的那次不算按住，否则松手事件已经过去，会永远停留在"按住"状态。
	if (!bConsumingBufferedPick)
	{
		bPickHeld = true;
		PickHeldTime = 0.f;
		RangePickCooldown = 0.f;
	}

	// ============================================================================
	// 交互分发：从"19 层写死的 if-else 优先级链"改为"分层 + 同层按距离决胜"。
	//
	// 旧逻辑的痛点：优先级是硬编码的，只要站在大门/招揽台/餐桌的判定球内，
	// 按 E 永远只做那件事，脚边的食物根本捡不起来；锅煮好时同理（取菜永远压过拾取）。
	//
	// 新逻辑：把所有"此刻可执行"的交互都收集成候选，分四层：
	//   Tier 0  必须响应      —— 手上脏碟（只能交还洗碗机，禁止放下）、已打开的对话
	//   Tier 1  交付手持物品   —— 上菜台 / 端给客人 / 投入研究炉
	//   Tier 2  环境交互       —— 门 / 招揽 / 餐桌 / 仓库 / 植物 / 出锅 / 修理 / 生成箱 / 拾取
	//                            同层内按"角色到目标包围盒最近点"的距离决胜，谁近谁生效
	//   Tier 3  兜底          —— 放下手上的东西
	// 排序后依次尝试，第一个"消费了这次按键"的动作生效；返回 false 表示这次没做成，
	// 让下一个候选接手（例如研究炉拒绝了无效食材，就继续尝试拾取脚下的东西）。
	// ============================================================================
	// ---- 交互动画播放中：记一次缓冲，动画结束后补执行 ----
	// 旧行为：动画期间按 E 完全被吞（Pick 只在 Started 触发，动画中的按键没人处理）；
	// 若直接放行，又会在动画中途触发"放下→再拾取"，表现为抖动。
	// 缓冲把这次按键延后到动画结束，既不吃键也不打断当前动作。
	if (IsInteractionAnimPlaying())
	{
		BufferPickInput();
		return;
	}

	// 突发事件：靠近老鼠等害虫时按 E 抓取（优先级高，避免被植物/拾取分支截走）
	if (OverlappingPest && IsValid(OverlappingPest))
	{
		if (OverlappingPest->TryCatch(this))
		{
			OverlappingPest = nullptr;
			RefreshAllInteractionTargets();
			UpdateInteractionPrompt();
			return;
		}
	}

	TArray<FInteractOption, TInlineAllocator<12>> Options;
	BuildInteractionOptions(Options);

	// 分层排序：Tier 小的先；同层按距离近的先；完全同分时保持加入顺序（StableSort）
	Options.StableSort(InteractionOptionLess);

	for (const FInteractOption& Option : Options)
	{
		if (Option.Run())
		{
			RefreshAllInteractionTargets();
			UpdateInteractionPrompt();
			if (InteractionDebug::IsEnabled() && GEngine)
			{
				GEngine->AddOnScreenDebugMessage(-1, 1.5f, FColor::Cyan,
					FString::Printf(TEXT("[交互] %s  (Tier %d / %.0fcm / 朝向分 %.0f)"),
						*Option.Name, Option.Tier, Option.Dist, Option.Score));
			}
			return;
		}
	}
}

// ============================================================================
// 交互朝向：谁近不算数，还要看脸朝哪
// ============================================================================
FVector AShootCharacter::GetInteractionFacing() const
{
	// 角色是 bOrientRotationToMovement：脸永远朝着移动方向，停下来也保持最后朝向。
	// 这正是玩家心里的"正前方"。控制器/相机朝向只在极端情况下兜底。
	FVector Facing = GetActorForwardVector();
	Facing.Z = 0.f;
	if (!Facing.Normalize())
	{
		if (const AController* C = GetController())
		{
			Facing = C->GetControlRotation().Vector();
			Facing.Z = 0.f;
			Facing.Normalize();
		}
	}
	return Facing.IsNearlyZero() ? FVector::ForwardVector : Facing;
}

float AShootCharacter::GetInteractionDistanceTo(const AActor* Target) const
{
	if (!Target)
	{
		return FLT_MAX;
	}
	const FVector MyLoc = GetActorLocation();
	const FBox B = Target->GetComponentsBoundingBox(true);
	return B.IsValid
		? FVector::Dist(MyLoc, B.GetClosestPointTo(MyLoc))
		: FVector::Dist(MyLoc, Target->GetActorLocation());
}

float AShootCharacter::GetFacingWeightedDistance(const AActor* Target) const
{
	const float Dist = GetInteractionDistanceTo(Target);
	if (!Target || Dist >= FLT_MAX)
	{
		return FLT_MAX;
	}

	const float Weight = InteractionFacing::GetPenaltyScale();
	if (Weight <= 0.f || Dist <= KINDA_SMALL_NUMBER)
	{
		return Dist;
	}

	const FVector MyLoc = GetActorLocation();
	const FBox B = Target->GetComponentsBoundingBox(true);
	const FVector Closest = B.IsValid ? B.GetClosestPointTo(MyLoc) : Target->GetActorLocation();

	FVector ToTarget = Closest - MyLoc;
	ToTarget.Z = 0.f;
	const float Horiz = ToTarget.Size();
	if (Horiz < 30.f)
	{
		// 头顶/脚下：水平方向退化成噪声，硬算角度会随机偏向，直接不做惩罚
		return Dist;
	}

	const float Cos = FVector::DotProduct(ToTarget / Horiz, GetInteractionFacing());
	// 偏离度：正前方 cos=1 → 0；正侧面 cos=0 → 0.5；正后方 cos=-1 → 1
	const float OffFront = FMath::Clamp((1.f - Cos) * 0.5f, 0.f, 1.f);
	return Dist * (1.f + Weight * OffFront);
}

void AShootCharacter::BuildInteractionOptions(TArray<FInteractOption, TInlineAllocator<12>>& OutOptions)
{
	constexpr int32 TierForce = 0;
	constexpr int32 TierHandover = 1;
	constexpr int32 TierWorld = 2;
	constexpr int32 TierAmbient = 3;
	constexpr int32 TierFallback = 4;

	// 到目标的交互距离：用包围盒最近点（大件设备不会因为 pivot 远而被算得比小物件远）
	auto DistTo = [this](const AActor* Target) -> float
	{
		return GetInteractionDistanceTo(Target);
	};

	// Dist 只用于显示；真正排序用 Score —— 背后的目标会被按偏离度放大，
	// 于是"背后 40cm 的蔬菜"不会再抢走"正前方 90cm 的蔬菜"。权重来自 Shoot.InteractFacing。
	auto AddOption = [this, &OutOptions](int32 Tier, float Dist, const TCHAR* Name, AActor* Target, TFunction<bool()>&& Run)
	{
		FInteractOption Option;
		Option.Tier = Tier;
		Option.Dist = Dist;
		// 没有具体目标（Tier 0 / 放下）时 Dist 是 0，恒排在同层最前，不需要惩罚
		Option.Score = (Target && Dist > 0.f) ? GetFacingWeightedDistance(Target) : Dist;
		Option.Name = Name;
		Option.Target = Target;
		Option.Run = MoveTemp(Run);
		OutOptions.Add(MoveTemp(Option));
	};

	if (APlateCollectionTray* Tray = Cast<APlateCollectionTray>(PickingItem))
	{
		const int32 Count = Tray->GetPlateCount();
		if (OverlappingDishwasher && Count > 0)
		{
			ADishwasher* Washer = OverlappingDishwasher;
			const FString Action = FString::Printf(TEXT("清洗 %d 只盘子"), Count);
			AddOption(TierHandover, DistTo(Washer), *Action, Washer, [Tray, Washer]()
			{
				return Tray->WashPlates(*Washer) > 0;
			});
		}
		else if (OverlappingDishwasher && Tray->GetOwner() == OverlappingDishwasher)
		{
			ADishwasher* Washer = OverlappingDishwasher;
			AddOption(TierWorld, DistTo(Washer), TEXT("放回收碟托盘"), Washer, [this, Washer]()
			{
				return Washer->ReturnCollectionTray(*this);
			});
		}

		const FString Action = Tray->HasRoom()
			? FString::Printf(TEXT("收碟到托盘  %d/%d"), Count, Tray->Capacity)
			: FString::Printf(TEXT("托盘已满  %d/%d · 去洗碗机"), Count, Tray->Capacity);
		if (AItemActor* Plate = OverlappingEmptyPlate)
		{
			AddOption(TierWorld, DistTo(Plate), *Action, Plate, [this, Tray, Plate]()
			{
				if (!Tray->HasRoom())
				{
					return true;
				}
				if (Plate->PickUpByPlayer(this))
				{
					RemoveOverlappingEmptyPlate(Plate);
					return true;
				}
				return false;
			});
		}
		else if (AChairSeat* Seat = OverlappingChairSeat; Seat && IsValid(Seat->DirtyPlate))
		{
			AddOption(TierWorld, DistTo(Seat), *Action, Seat, [this, Tray, Seat]()
			{
				return !Tray->HasRoom() || Seat->TryCollectPlateByPlayer(this);
			});
		}
		return;
	}

	if (!PickingItem && OverlappingDishwasher && OverlappingDishwasher->HasDockedTray())
	{
		ADishwasher* Washer = OverlappingDishwasher;
		AddOption(TierWorld, DistTo(Washer), TEXT("拿收碟托盘"), Washer, [this, Washer]()
		{
			return Washer->TakeCollectionTray(*this);
		});
	}

	// ---------------- Tier 0：必须响应 ----------------
	// 手上拿着脏碟：唯一出路是走到洗碗机按 E 交还（可用碟子数 +1）。
	// 禁止放下/丢弃/拿去做菜，否则碟子会丢失导致可用碟子数永远无法恢复，
	// 所以这一层无论距离多远都优先，且一定消费按键。
	if (PickingItem && PickingItem->bIsDirtyPlate)
	{
		AddOption(TierForce, 0.f, TEXT("交还脏碟"), OverlappingDishwasher, [this]()
		{
			if (OverlappingDishwasher && OverlappingDishwasher->SubmitPlate(PickingItem))
			{
				ClearHeldItemState();
				ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::ReturnPlate, INDEX_NONE, OverlappingDishwasher);
				return true;
			}
			if (GEngine)
			{
				GEngine->AddOnScreenDebugMessage(-1, 2.f, FColor::Yellow, TEXT("[脏碟] 请走到洗碗机旁按 E 交还清洗"));
			}
			return true;
		});
	}

	// 对话已打开：再按 E 关闭（未打开则在 Tier 2 参与距离竞争）
	if (OverlappingDialogue && OverlappingDialogue->IsDialogueOpen())
	{
		AddOption(TierForce, 0.f, TEXT("关闭对话"), OverlappingDialogue->GetOwner(), [this]()
		{
			OverlappingDialogue->CloseDialogue();
			return true;
		});
	}

	// ---------------- Tier 1：交付手持物品 ----------------
	// 手上拿着东西时，"把手上的东西交出去"比脚边任何东西都更符合意图。
	if (PickingItem && !PickingItem->bIsDirtyPlate)
	{
		if (OverlappingResearchStove)
		{
			AddOption(TierHandover, DistTo(OverlappingResearchStove), TEXT("投入研究炉"), OverlappingResearchStove, [this]()
			{
				if (OverlappingResearchStove->AddFood(PickingItem))
				{
					ClearHeldItemState();
					return true;
				}
				return false; // 研究中/无效食材：不消费按键，交给下一个候选
			});
		}

		// 上菜改到餐桌上完成：端着菜站在餐桌旁 → 直接给这桌客人上菜。
		// 留在 Tier 1 是为了保住原来的手感：端着菜时"上菜"永远压过脚边的植物/垃圾。
		if (OverlappingChairSeat && OverlappingChairSeat->CanPlayerServeDish(this))
		{
			AChairSeat* Seat = OverlappingChairSeat;
			AddOption(TierHandover, DistTo(Seat), TEXT("上菜"), Seat, [this, Seat]()
			{
				return Seat->TryInteractByPlayer(this);
			});
		}

		if (OverlappingCounter && OverlappingCounter->bStageFinishedDish)
		{
			AServingCounter* Counter = OverlappingCounter;
			if (Counter->CanStageDish(PickingItem))
			{
				const bool bOccupied = IsValid(Counter->StagedDish);
				AddOption(TierHandover, DistTo(Counter),
					bOccupied ? TEXT("出餐台已满") : TEXT("把菜放到出餐台"), Counter, [this, Counter, bOccupied]()
				{
					return bOccupied || Counter->TryStageDish(*this);
				});
			}
		}
		else if (OverlappingCounter)
		{
			AddOption(TierHandover, DistTo(OverlappingCounter), TEXT("提交上菜台"), OverlappingCounter, [this]()
			{
				if (OverlappingCounter->SubmitDish(PickingItem))
				{
					ClearHeldItemState();
				}
				// 与原逻辑一致：站在上菜台范围内按 E 就当作"上菜尝试"，不再落到放下
				return true;
			});
		}
	}

	// 手上拿着外出背包：与仓库交互 = 背包入库 + 背包脱手放在仓库旁边
	if (OverlappingWarehouse && Cast<AOutdoorBasket>(PickingItem))
	{
		AddOption(TierHandover, DistTo(OverlappingWarehouse), TEXT("存入仓库（背包）"), OverlappingWarehouse, [this]()
		{
			return DepositBasketToWarehouse(OverlappingWarehouse);
		});
	}

	// ---------------- Tier 2：环境交互（同层按距离决胜） ----------------
	if (!PickingItem && CookingMachine && CookingMachine->IsAttentionAvailable())
	{
		ACookingMachine* Pan = CookingMachine;
		AddOption(TierWorld, DistTo(Pan), TEXT("翻面！空手按 E"), Pan,
			[Pan]() { return Pan->PerformAttention(); });
	}

	if (!PickingItem && OverlappingCounter && OverlappingCounter->bStageFinishedDish
		&& IsValid(OverlappingCounter->StagedDish))
	{
		AServingCounter* Counter = OverlappingCounter;
		AddOption(TierWorld, DistTo(Counter), TEXT("从出餐台取菜"), Counter, [this, Counter]()
		{
			return Counter->TryTakeStagedDish(*this);
		});
	}

	// 植物：浇水 / 驱虫 / 收获
	if (IsValid(OverlappingPlant) && (OverlappingPlant->CanHarvest()
		|| (!OverlappingPlant->UsesWildHarvest() && (OverlappingPlant->HasPest() || OverlappingPlant->NeedsWater()))))
	{
		// 背着篮子且该果实不能入篮（如生菜）：提示文字提前说明只能手持采摘
		const bool bHarvestNeedsFreeHand = GetEquippedBasket() != nullptr
			&& OverlappingPlant->UsesWildHarvest() && OverlappingPlant->CanHarvest()
			&& !OverlappingPlant->CanHarvestFruitStoreInBasket();
		AddOption(TierWorld, DistTo(OverlappingPlant),
			bHarvestNeedsFreeHand ? TEXT("只能手持 · 用投掷键放下篮子") : TEXT("植物"), OverlappingPlant, [this]()
		{
			InteractWithPlant();
			return true;
		});
	}

	// 就餐区散落物：按 E 清理垃圾 / 积水（同层与其他环境交互按距离决胜）
	if (IsValid(OverlappingMess))
	{
		AddOption(TierWorld, DistTo(OverlappingMess), *OverlappingMess->GetCleanActionText().ToString(), OverlappingMess, [this]()
		{
			if (IsValid(OverlappingMess))
			{
				OverlappingMess->TryClean(this);
			}
			return true;
		});
	}

	// 通用对话（未打开时）
	if (OverlappingDialogue && !OverlappingDialogue->IsDialogueOpen())
	{
		AddOption(TierWorld, DistTo(OverlappingDialogue->GetOwner()), TEXT("开始对话"), OverlappingDialogue->GetOwner(), [this]()
		{
			OverlappingDialogue->StartDialogue(this);
			return true;
		});
	}

	// 大门：开门营业
	if (OverlappingGate)
	{
		AddOption(TierWorld, DistTo(OverlappingGate), TEXT("开门营业"), OverlappingGate, [this]()
		{
			OverlappingGate->OpenBusiness();
			return true;
		});
	}

	// 招揽台：招揽顾客
	if (OverlappingAttractCounter)
	{
		AddOption(TierWorld, DistTo(OverlappingAttractCounter), TEXT("招揽顾客"), OverlappingAttractCounter, [this]()
		{
			OverlappingAttractCounter->AttractCustomers();
			return true;
		});
	}

	// 餐桌：点单 / 收空碟（上菜见 Tier 1 的"上菜"候选；客人身上的交互已全部并入餐桌）
	// 只有此刻按 E 真能办成事才加入候选：空桌、客人入座中、已上菜用餐中、空手等上菜时
	// 按 E 都没有实际结果，不显示 E 交互提示与高亮
	const bool bSeatCanTakeOrder = OverlappingChairSeat && OverlappingChairSeat->CanPlayerTakeOrder(this);
	const bool bSeatCanCollectPlate = OverlappingChairSeat && OverlappingChairSeat->CanPlayerCollectPlate(this);
	if (bSeatCanTakeOrder || bSeatCanCollectPlate)
	{
		// 提示文字按此刻能做的事实时变化：空手站过去看到的就是"点单"，而不是笼统的"餐桌"
		const TCHAR* SeatAction = bSeatCanTakeOrder ? TEXT("点单") : TEXT("收走空碟");

		AddOption(TierWorld, DistTo(OverlappingChairSeat), SeatAction, OverlappingChairSeat, [this]()
		{
			return OverlappingChairSeat->TryInteractByPlayer(this);
		});
	}
	else if (!PickingItem && OverlappingChairSeat && OverlappingChairSeat->CanPlayerServeDish(this))
	{
		AChairSeat* Seat = OverlappingChairSeat;
		AddOption(TierAmbient, DistTo(Seat), TEXT("查看订单"), Seat, [this, Seat]()
		{
			return Seat->TryInteractByPlayer(this);
		});
	}

	// 收走空碟 → 变成手上脏碟
	if (OverlappingEmptyPlate && !PickingItem)
	{
		AItemActor* Plate = OverlappingEmptyPlate;
		AddOption(TierWorld, DistTo(Plate), TEXT("收走空碟"), Plate, [this, Plate]()
		{
			if (Plate->PickUpByPlayer(this))
			{
				// 收走后从候选集注销（物体会转为手持脏碟），立即重选下一个空碟
				RemoveOverlappingEmptyPlate(Plate);
				return true;
			}
			return false;
		});
	}

	// 研究炉（空手）：配方凑齐 → 手动开始研究；炉内有残留食材 → 清空；空炉 → 查看菜谱。
	// 三种状态互斥：同层同目标的选项排序不稳定，同时挂多个会导致按 E 行为随机
	if (OverlappingResearchStove && !PickingItem)
	{
		AResearchStove* Stove = OverlappingResearchStove;
		if (!Stove->bResearching && Stove->FindMatchingRecipeIndex() != INDEX_NONE)
		{
			AddOption(TierWorld, DistTo(Stove), TEXT("开始研究"), Stove, [Stove]()
			{
				return Stove->TryStartMatchingResearch();
			});
		}
		else if (!Stove->bResearching && Stove->StoredItemIDs.Num() > 0)
		{
			AddOption(TierWorld, DistTo(Stove), TEXT("清空研究炉"), Stove, [Stove]()
			{
				Stove->ClearFoods();
				if (GEngine)
				{
					GEngine->AddOnScreenDebugMessage(-1, 2.f, FColor::Yellow, TEXT("[研究炉] 已清空炉内食材"));
				}
				return true;
			});
		}
		else
		{
			AddOption(TierWorld, DistTo(Stove), TEXT("查看菜谱"), Stove, [this]()
			{
				if (APlayerController* PC = Cast<APlayerController>(GetController()))
				{
					URecipeBookWidget::ToggleForPlayer(PC);
					return true;
				}
				return false;
			});
		}
	}

	// 灶台/锅：煮好了 → 出锅（切菜生成物需要先放下手上的东西）
	if (MachineCookFinished() && CookingMachine)
	{
		const float MDist = DistTo(CookingMachine);
		if (IsSpawnOther())
		{
			if (GetEquippedBasket())
			{
				AddOption(TierWorld, MDist, TEXT("用投掷键放下采集篮"), CookingMachine, []() { return true; });
			}
			else if (NeedDropDown())
			{
				AddOption(TierWorld, MDist, TEXT("放下手持物"), CookingMachine, [this]()
				{
					DoDropDown();
					return true;
				});
			}
			else
			{
				AddOption(TierWorld, MDist, TEXT("取出切好的菜"), CookingMachine, [this]()
				{
					DoSpwanOther();
					return true;
				});
			}
		}
		else
		{
			AddOption(TierWorld, MDist, TEXT("取出成品"), CookingMachine, [this]()
			{
				DoPushDishTest();
				return true;
			});
		}
	}

	// 灶台着火：修理
	if (NeedRepairMachine())
	{
		AddOption(TierWorld, DistTo(CookingMachine), TEXT("修理灶台"), CookingMachine, [this]()
		{
			DoRepair();
			return true;
		});
	}

	// 手上拿着食材：扔进锅
	if (CanThrowToMachine())
	{
		AddOption(TierWorld, DistTo(CookingMachine), TEXT("扔进锅"), CookingMachine, [this]()
		{
			DoThrow();
			return true;
		});
	}

	// 仓库：把背包物品存入（手上物品不受影响；背包为空时无副作用）
	if (OverlappingWarehouse)
	{
		AddOption(TierWorld, DistTo(OverlappingWarehouse), TEXT("存入仓库"), OverlappingWarehouse, [this]()
		{
			OverlappingWarehouse->DepositFromInventory(this);
			return true;
		});
	}

	// 生成箱：取料（手上有东西时按 E 应该是"放下"，不参与取料）
	AFoodSpawner* FoodSpawner = Cast<AFoodSpawner>(OverlappingItem);
	if (!PickingItem && IsSpawner() && FoodSpawner && FoodSpawner->SpawnItemActorClass && FoodSpawner->CanSpawn())
	{
		AddOption(TierWorld, DistTo(OverlappingItem), TEXT("取料"), OverlappingItem, [this]()
		{
			DoSpwan();
			return true;
		});
	}

	// 地面/桌面物品：拾取（手上有东西时同理不参与，让位给 Tier 3 的放下）
	// 刚放下的物品有锁定时间，防连按 E "拾取↔放下"抖动
	if (!PickingItem && CanPick() && !IsDropLockActive(OverlappingItem))
	{
		AddOption(TierWorld, DistTo(OverlappingItem), TEXT("拾取"), OverlappingItem, [this]()
		{
			DoPick();
			return true;
		});
	}

	// 手上拿着外出背包：脚边散落的食材（如鸡窝旁的鸡蛋）按 E 直接装进篮子，篮子不脱手。
	// 原先拿着篮子时只有"放下"可选，按 E 会把篮子扔掉，捡不起野外的散落食材
	if (AOutdoorBasket* Basket = GetEquippedBasket())
	{
		AItemActor* Loose = OverlappingItem;
		const bool bLooseIngredient = IsValid(Loose) && Loose != Basket && CanPick()
			&& !Cast<AOutdoorBasket>(Loose) && !Cast<ADish>(Loose)
			&& Loose->bPickable && !Loose->bIsEmptyPlate && !Loose->bIsDirtyPlate
			&& Loose->GetMenuFoodID() < 0 // 做好的成品菜不进篮子
			&& Loose->GetItemState() != EItemState::EIS_Equipped
			&& Loose->GetItemState() != EItemState::EIS_Cooking
			&& !IsDropLockActive(Loose);
		if (bLooseIngredient)
		{
			const bool bStorable = Loose->bCanStoreInBasket;
			AddOption(TierWorld, DistTo(Loose), bStorable ? TEXT("装进篮子") : TEXT("只能手持 · 用投掷键放下篮子"), Loose, [this, Loose]()
			{
				if (!IsValid(Loose))
				{
					return false;
				}
				if (!Loose->bCanStoreInBasket)
				{
					// 不能入篮的食材：只提示，按键已消费，避免误把篮子扔在地上
					if (GEngine)
					{
						GEngine->AddOnScreenDebugMessage(-1, 2.5f, FColor::Yellow,
							FString::Printf(TEXT("[背包] %s 只能手持携带，请先放下篮子再捡"), *Loose->GetItemDisplayName()));
					}
					return true;
				}

				const FString ItemName = Loose->GetItemDisplayName();
				UTexture2D* ItemIcon = Loose->GetItemIcon(); // 物体会在入篮时销毁，图标先缓存
				// 篮子满时 StoreHarvestInBasket 内部会给提示；同样消费按键，不把篮子放下
				if (StoreHarvestInBasket(Loose, 1)) // 成功后世界上的物体已被销毁，之后不能再访问 Loose
				{
					ShowHarvestHint(ItemName, ItemIcon);
					RefreshBestOverlappingItem(); // 已销毁的引用会在重选时清理，并切到下一个目标
					PlayGatheringMontage();
					if (GEngine)
					{
						GEngine->AddOnScreenDebugMessage(-1, 1.5f, FColor::Green,
							FString::Printf(TEXT("[背包] %s 已装进篮子"), *ItemName));
					}
				}
				return true;
			});
		}
	}

	for (TActorIterator<AFireflyAreaVolume> It(GetWorld()); It; ++It)
	{
		AFireflyAreaVolume* Area = *It;
		if (Area->CanInteract(this))
		{
			const float Distance = Area->GetNearestFireflyDistance(GetActorLocation());
			AddOption(TierAmbient, Distance, TEXT("惊扰萤火虫"), Area, [this, Area]()
			{
				return Area->Interact(this);
			});
			OutOptions.Last().Score = Distance;
		}
	}

	// ---------------- Tier 4：兜底 —— 放下手上的东西 ----------------
	// 缓冲消费时不执行：玩家在动画期间按的那一下本意是"继续交互"，
	// 补执行时若变成"把刚捡的东西放下"，手感会更差。
	if (NeedDropDown() && !GetEquippedBasket() && !bConsumingBufferedPick)
	{
		AddOption(TierFallback, FLT_MAX, TEXT("放下"), nullptr, [this]()
		{
			DoDropDown();
			return true;
		});
	}
}

void AShootCharacter::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
	if (AItemActor* Item = HighlightedInteractionItem.Get())
	{
		Item->SetInteractionHighlightForPlayer(this, false);
	}
	HighlightedInteractionItem.Reset();
	Super::EndPlay(EndPlayReason);
}

void AShootCharacter::UpdateItemInteractionHighlight()
{
	AItemActor* NewItem = IsLocallyControlled() && CharacterState != ECharacterState::ECS_Dead
		&& !IsInteractionAnimPlaying() ? Cast<AItemActor>(InteractionPromptTarget) : nullptr;
	// huanglily：描边只给食物 / 菜盘 / 取料箱；桌台与武器仍只用 E 提示，避免整块台面发亮。
	if (NewItem && (NewItem->IsA<ADesk>() || NewItem->IsA<AWeapon>()))
	{
		NewItem = nullptr;
	}
	if (HighlightedInteractionItem.Get() != NewItem)
	{
		if (AItemActor* OldItem = HighlightedInteractionItem.Get())
		{
			OldItem->SetInteractionHighlightForPlayer(this, false);
		}
		HighlightedInteractionItem = NewItem;
	}
	if (IsValid(NewItem))
	{
		NewItem->SetInteractionHighlightForPlayer(this, true);
	}
}

void AShootCharacter::RefreshInteractionPromptTarget()
{
	InteractionPromptTarget = nullptr;
	if (bEnableInteractionPrompt && IsLocallyControlled() && CharacterState != ECharacterState::ECS_Dead)
	{
		if (IsValid(OverlappingPest))
		{
			InteractionPromptTarget = OverlappingPest;
		}
		else
		{
			TArray<FInteractOption, TInlineAllocator<12>> Options;
			BuildInteractionOptions(Options);
			Options.StableSort(InteractionOptionLess);
			if (!Options.IsEmpty())
			{
				InteractionPromptTarget = Options[0].Target;
			}
		}
	}
	UpdateItemInteractionHighlight();
}

UWidgetComponent* AShootCharacter::FindInteractionPromptAnchor(const AActor* Target) const
{
	if (!IsValid(Target) || !UnifiedPromptWidgetClass)
	{
		return nullptr;
	}

	// 烹饪设备、大门这类蓝图里有美术摆好的 WBP_Prompt TipsWidget（控件类与统一提示同源）。
	// 现在 E 提示统一由角色显示（每个本地玩家一份，适配分屏），设备上的这个控件只作为
	// 位置锚点：沿用它的世界坐标/轴心，提示位置就和美术在蓝图里看到的一致。
	// 只认 WBP_Prompt 子类，避免把餐桌菜单等其它 Tips 控件误当成提示锚点。
	TInlineComponentArray<UWidgetComponent*> Widgets(Target);
	for (UWidgetComponent* Widget : Widgets)
	{
		if (!Widget)
		{
			continue;
		}

		const UClass* WidgetClass = Widget->GetWidgetClass();
		if (WidgetClass && WidgetClass->IsChildOf(UnifiedPromptWidgetClass))
		{
			return Widget;
		}
	}
	return nullptr;
}

void AShootCharacter::UpdateInteractionPrompt()
{
	AActor* Target = InteractionPromptTarget;
	const bool bShow = bEnableInteractionPrompt && IsLocallyControlled() && IsValid(Target)
		&& CharacterState != ECharacterState::ECS_Dead && !IsInteractionAnimPlaying();
	InteractionPrompt->SetVisibility(bShow);
	if (!bShow)
	{
		return;
	}

	if (const APlant* Plant = Cast<APlant>(Target))
	{
		if (!Plant->CanHarvest() && !Plant->HasPest() && !Plant->NeedsWater())
		{
			InteractionPrompt->SetVisibility(false);
			return;
		}
	}

	if (APlayerController* PC = Cast<APlayerController>(GetController()))
	{
		InteractionPrompt->SetOwnerPlayer(PC->GetLocalPlayer());
	}

	// 目标自带 WBP_Prompt（大门/灶台等）：统一提示直接落在它的锚点上，保留美术在蓝图里
	// 摆好的位置与轴心。设备上的提示控件本身不再显示，角色提示是每个本地玩家各一份。
	if (UWidgetComponent* AnchorWidget = FindInteractionPromptAnchor(Target))
	{
		// 调试开关：Shoot.DeviceOwnPromptTips 1 时回到旧行为，由设备自己显示提示，
		// 角色提示让位，否则两边会互相压制。
		if (InteractionPromptTuning::UseDeviceOwnPromptTips())
		{
			InteractionPrompt->SetVisibility(false);
			return;
		}

		InteractionPrompt->SetPivot(AnchorWidget->GetPivot());
		InteractionPrompt->SetWorldLocation(AnchorWidget->GetComponentLocation());
		// 兜底：若有蓝图逻辑仍把设备自带提示打开了，统一提示出现时强制隐藏，避免叠两层
		if (AnchorWidget->IsVisible())
		{
			AnchorWidget->SetVisibility(false);
		}
		return;
	}

	// 没有提示锚点（食材/植株等）：恢复“底部贴包围盒顶部”的默认摆放
	InteractionPrompt->SetPivot(FVector2D(0.5f, 1.f));

	FVector Location = Target->GetActorLocation();
	if (const AFireflyAreaVolume* Area = Cast<AFireflyAreaVolume>(Target))
	{
		if (!Area->CanInteract(this))
		{
			InteractionPrompt->SetVisibility(false);
			return;
		}
		Location = Area->GetNearestFireflyLocation(GetActorLocation());
		Location.Z = FMath::Max(Location.Z, GetActorLocation().Z + 90.f);
	}
	else
	{
		FBox Bounds(ForceInit);
		TInlineComponentArray<UMeshComponent*> Meshes(Target);
		for (const UMeshComponent* TargetMesh : Meshes)
		{
			if (!TargetMesh->IsA<UWidgetComponent>() && TargetMesh->IsVisible() && !TargetMesh->bHiddenInGame)
			{
				Bounds += TargetMesh->Bounds.GetBox();
			}
		}
		if (Bounds.IsValid)
		{
			Location = Bounds.GetCenter();
			Location.Z = Bounds.Max.Z;
		}
	}
	Location.Z += InteractionPromptHeight;
	InteractionPrompt->SetWorldLocation(Location);
}

// ============================================================================
// 交互动画期间的输入缓冲
// ============================================================================
bool AShootCharacter::IsInteractionAnimPlaying()
{
	if (!GetMesh())
	{
		return false;
	}
	UAnimInstance* AnimInstance = GetMesh()->GetAnimInstance();
	if (!AnimInstance)
	{
		return false;
	}

	// 采集/浇水不改 CharacterActionState（角色一直处于 EAS_Unoccupied 或 EAS_Picking），
	// 所以"动画是否在播"只能看蒙太奇本身
	return (PickMontage && AnimInstance->Montage_IsPlaying(PickMontage))
		|| (PutDownMontage && AnimInstance->Montage_IsPlaying(PutDownMontage))
		|| (GatheringMontage && AnimInstance->Montage_IsPlaying(GatheringMontage))
		|| (WateringMontage && AnimInstance->Montage_IsPlaying(WateringMontage));
}

void AShootCharacter::BufferPickInput()
{
	bHasBufferedPick = true;
	if (GetWorld())
	{
		BufferedPickTime = GetWorld()->GetTimeSeconds();
	}
}

void AShootCharacter::TickBufferedPick(float DeltaTime)
{
	if (!bHasBufferedPick)
	{
		return;
	}

	const float Now = GetWorld() ? GetWorld()->GetTimeSeconds() : 0.f;
	if (IsInteractionAnimPlaying())
	{
		// 动画过长或被误配成循环：超过窗口就丢弃，不补执行一个"过期的按键"
		if (Now - BufferedPickTime > PickBufferWindow)
		{
			bHasBufferedPick = false;
		}
		return;
	}

	bHasBufferedPick = false;
	bConsumingBufferedPick = true;
	Pick(FInputActionValue());
	bConsumingBufferedPick = false;
}

void AShootCharacter::PickReleased(const FInputActionValue& Value)
{
	bPickHeld = false;
	PickHeldTime = 0.f;
	RangePickCooldown = 0.f;
}

// ============================================================================
// 按住 E 范围拾取（野外收割）：长按超过 RangePickHoldTime 后，
// 每隔 RangePickInterval 把半径内最近的散落物品直接收进背包（不占手）
// ============================================================================
void AShootCharacter::TickRangePick(float DeltaTime)
{
	// 手上拿着脏碟时不收割：脏碟状态不允许做别的动作（原逻辑就这么约束的）
	if (!bRangePickEnabled || !bPickHeld || IsInteractionAnimPlaying()
		|| (PickingItem && PickingItem->bIsDirtyPlate))
	{
		PickHeldTime = 0.f;
		return;
	}

	PickHeldTime += DeltaTime;
	if (PickHeldTime < RangePickHoldTime)
	{
		return; // 还没到长按判定：短按仍然只做一次普通交互
	}

	RangePickCooldown -= DeltaTime;
	if (RangePickCooldown > 0.f)
	{
		return;
	}

	// 贴着设备时不吸：否则站在灶台/上菜台旁长按 E 会把待加工食材吸进背包
	if (HasBlockingInteractionTarget())
	{
		return;
	}

	if (AItemActor* Item = FindNearestRangePickItem())
	{
		RangePickCooldown = RangePickInterval;
		const FString ItemName = Item->GetItemDisplayName();
		UTexture2D* ItemIcon = Item->GetItemIcon(); // 入篮/入包可能销毁物体，图标先缓存
		// 手上拿着外出背包：能入篮的食材优先装进篮子（"带篮子捡鸡蛋"等任务按篮内数量计），
		// 不能入篮 / 篮子已满时才退回原逻辑收进背包
		if (GetEquippedBasket() && Item->bCanStoreInBasket && StoreHarvestInBasket(Item, 1)) // 成功后 Item 已销毁
		{
			ShowHarvestHint(ItemName, ItemIcon);
			RemoveOverlappingItem(Item);
			RefreshBestOverlappingItem();
			if (GEngine)
			{
				GEngine->AddOnScreenDebugMessage(-1, 1.f, FColor::Green,
					FString::Printf(TEXT("[范围拾取] %s 已装进篮子"), *ItemName));
			}
		}
		else if (AddItemToInventory(Item)) // 内部销毁世界物体，之后不能再访问 Item
		{
			ShowHarvestHint(ItemName, ItemIcon);
			RemoveOverlappingItem(Item);
			if (GEngine)
			{
				GEngine->AddOnScreenDebugMessage(-1, 1.f, FColor::Green,
					FString::Printf(TEXT("[范围拾取] %s 已入背包"), *ItemName));
			}
		}
	}
}

AItemActor* AShootCharacter::FindNearestRangePickItem() const
{
	if (!GetWorld())
	{
		return nullptr;
	}

	AItemActor* Best = nullptr;
	float BestDistSq = FMath::Square(RangePickRadius);
	const FVector MyLoc = GetActorLocation();

	for (TActorIterator<AItemActor> It(GetWorld()); It; ++It)
	{
		AItemActor* Item = *It;
		if (!Item || !IsValid(Item) || Item == PickingItem)
		{
			continue;
		}
		// 空碟/脏碟走各自的交互流程，不能当散落物吸走；外出背包是容器，只能按 E 拿到手上
		if (!Item->bPickable || Item->bIsEmptyPlate || Item->bIsDirtyPlate || Cast<AFoodSpawner>(Item) || Cast<AOutdoorBasket>(Item))
		{
			continue;
		}

		const EItemState State = Item->GetItemState();
		if (State == EItemState::EIS_Equipped || State == EItemState::EIS_Cooking)
		{
			continue;
		}

		const float DistSq = FVector::DistSquared(MyLoc, Item->GetActorLocation());
		if (DistSq > BestDistSq)
		{
			continue;
		}
		// 隔着墙/台面的不吸
		if (!HasInteractionLineOfSight(Item))
		{
			continue;
		}

		BestDistSq = DistSq;
		Best = Item;
	}

	return Best;
}

bool AShootCharacter::HasBlockingInteractionTarget() const
{
	// 只列"设备/服务类"：这些位置长按 E 的意图一定是操作设备，不是收割地面散落物
	return CookingMachine != nullptr
		|| OverlappingCounter != nullptr
		|| OverlappingAttractCounter != nullptr
		|| OverlappingGate != nullptr
		|| OverlappingChairSeat != nullptr
		|| OverlappingDishwasher != nullptr
		|| OverlappingResearchStove != nullptr
		|| OverlappingWarehouse != nullptr;
}

