			}
			SetOverlappingItem(nullptr);
			return;
		}
	}

 	IsPicking = true;
	//GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, TEXT("DoPick"));
 	if(OverlappingItem->GetItemState() != EItemState::EIS_Cooking && OverlappingItem->GetItemState() != EItemState::EIS_Equipped) //手上没有食物
	{
		// if (OverlappingItem->ItemType == EItemType::EIT_Spawn && OverlappingItem->SpawnItemActorClass)//如果是需要生成食物的类型，如番茄树，要从番茄树生成一个番茄到手上
		// {
		// 	//这一个放在他的蓝图里处理
		// 	OverlappingItem->OnSpawnActorEvent();
		// 	PlayPickMontage( FName("Pick0")); //pick1 是摘，摘完后应该切到抬
		// 	//原本在c++处理
		// 	//UWorld* World = GetWorld();
		// 	//AItemActor* Spawned = World->SpawnActor<AItemActor>(OverlappingItem->SpawnItemActorClass, GetActorLocation(), GetActorRotation());
		// 	//SetOverlappingItem(Spawned);
		// 	//SetPickingItemStatus();
		// }
		// else
		{
			//如果不是番茄树的情况
			// 拾取会把物品挂到手上，无需再弹“打开背包”的采摘提示
			SetPickingItemStatus();//这一个放在他的蓝图里处理
			if (Cast<AOutdoorBasket>(OverlappingItem))
			{
				// 外出背包是“挂”在手上的，拾取时播放采集动画（AM_Gathering）而不是普通拾取动作
				PlayGatheringMontage();
			}
			else
			{
				PlayPickMontage( FName("Pick0"));
			}
		}
	}

 	IsPicking = false;
 	//拿到手上后，把Hovering item设置为空，并从候选集移除（物品已 Equipped 挂到手上）
	RemoveOverlappingItem(OverlappingItem);
 	//SetWeaponCollisionEnabled(ECollisionEnabled::NoCollision);

}

 void AShootCharacter::DoSpwan()
 {
 	if (OverlappingItem == nullptr)
 	{
 		return;
 	}
 	//IsPicking = true;
 	//GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, TEXT("DoPick"));
 	if(OverlappingItem->GetItemState() != EItemState::EIS_Cooking && OverlappingItem->GetItemState() != EItemState::EIS_Equipped) //手上没有食物
 	{
 		if (AFoodSpawner* FoodSpawner = Cast<AFoodSpawner>(OverlappingItem))//如果是需要生成食物的类型，如番茄树，要从箱子生成一个番茄到手上
		{
			//箱内还有食材才生成；为空(RemainingCount==0)则不再生成
			if (FoodSpawner->CanSpawn() && FoodSpawner->SpawnItemActorClass)
			{
				//原本在c++处理
				UWorld* World = GetWorld();
				AItemActor* Spawned = World->SpawnActor<AItemActor>(FoodSpawner->SpawnItemActorClass, GetActorLocation(), GetActorRotation());
				if (!IsValid(Spawned)) return;
				SetOverlappingItem(Spawned);
				// 取料直接拿到手上，不再弹“打开背包”的采摘提示
				SetPickingItemStatus();
				FoodSpawner->OnSpawnActorEvent();//广播给蓝图（特效/音效等）
				FoodSpawner->ConsumeOne();//消耗一个数量（空了就不会再生成）
			}
		}
 	}

 	//IsPicking = false;
 	//生成物已拿在手上：从候选集重选目标（食物箱仍在脚下时保持为当前目标，HUD 数量同步刷新）
 	RefreshBestOverlappingItem();
 	//SetWeaponCollisionEnabled(ECollisionEnabled::NoCollision);
 }

 void AShootCharacter::DoSpwanOther()
 {
 	CookingMachine->GetMenuFood();
 	for (int32 i = 0; i < CookingMachine->FoodActors.Num(); i++)
 	{
		AItemActor* CurrentActor = CookingMachine->FoodActors[i];
		if (AFoodSpawnOther* SpawnOther = Cast<AFoodSpawnOther>(CurrentActor))//如果是需要生成食物的类型，如牛排，要从牛排变成切好的牛排
		{
			if (SpawnOther->SpawnItemActorClass)
			{
				UWorld* World = GetWorld();
				AItemActor* Spawned = World->SpawnActor<AItemActor>(SpawnOther->SpawnItemActorClass, GetActorLocation(), GetActorRotation());
				SetOverlappingItem(Spawned);
				SetPickingItemStatus();
			}
		}
		CurrentActor->Destroy();
	}
 	CookingMachine->FoodActors.Empty();
 	GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, TEXT("切好菜"));
 	RefreshBestOverlappingItem();
 }

 void AShootCharacter::DoDropDown() // 如果已经手上有食物了，要先将食物扔下
 {
	if (!IsValid(PickingItem)) return;
 	PickingItem->DeAttachMeshToSocket();
 	//PickingItem->SetItemState(EItemState::EIS_Idle);//临时简单处理，为了可以放下食物可以马上拾取

 	OnReleasePickEvent();
 	PickingItem->SetItemState(EItemState::EIS_Hovering);//临时简单处理，为了可以放下食物可以马上拾取
 	// huanglily：篮子网格没有物理碰撞，OnReleasePickEvent 开的物理会让它穿地无限下坠，放下时改为贴地摆放
 	if (AOutdoorBasket* DroppedBasket = Cast<AOutdoorBasket>(PickingItem))
 	{
 		DroppedBasket->SettleOnGround(this);
 	}
 	//放下的物品重新进入候选集（其交互球仍与角色重叠，不会再触发 BeginOverlap，需手动注册）
 	LastDroppedItem = PickingItem; // 记录重拾锁定（DropRePickLockTime 秒内不可再拾）
 	LastDropTime = GetWorld() ? GetWorld()->GetTimeSeconds() : 0.f;
 	AddOverlappingItem(PickingItem);
 	SetPickingItem(nullptr);
 	CharacterActionState = ECharacterActionState::EAS_Unoccupied;
 	CharacterState = ECharacterState::ECS_Idle;

 	//设置ik
 	
 	FBIK_Alpha = 0;
 	HandIK_LPoint = nullptr;
 	HandIK_RPoint = nullptr;
 }

 void AShootCharacter::OnPushFoodComplete()
{
	if (CharacterState != ECharacterState::ECS_Holding || !IsValid(PickingItem) || !PickingItem->IsLooseIngredient()) return;
	FString Hint;
	ACookingMachine* Pot = nullptr;
	if (!ResolvePotToss(Pot, Hint))
	{
		ShowSimpleToast(TEXT("投料"), Hint, FLinearColor(0.82f, 0.48f, 0.13f));
		return;
	}
	PickingItem->StartPotToss(Pot, TossHeight);
	ClearHeldItemState();
	if (ThrowMontage && GetMesh()->GetAnimInstance())
		GetMesh()->GetAnimInstance()->Montage_Play(ThrowMontage, 1.35f);
}

bool AShootCharacter::ResolvePotToss(ACookingMachine*& Pot, FString& Hint) const
{
	Pot = nullptr;
	if (!IsValid(PickingItem)) return false;
	const FVector Forward = GetActorForwardVector().GetSafeNormal2D();
	float Best = MAX_flt;
	for (TActorIterator<ACookingMachine> It(GetWorld()); It; ++It)
	{
		if (!It->IsTossPot() || It->IsHidden()) continue;
		const FVector Offset = It->GetTossMouth() - GetActorLocation();
		const float Distance = Offset.Size();
		const float Aim = FVector::DotProduct(Forward, Offset.GetSafeNormal2D());
		if (Distance > PotTossRange || Aim < 0.70f) continue;
		const float Score = Distance + (1.f - Aim) * 650.f;
		if (Score < Best)
		{
			Best = Score;
			Pot = *It;
		}
	}
	if (!Pot)
	{
		Hint = TEXT("靠近并面向煎锅或汤锅");
		return false;
	}
	if (!Pot->CanReceiveToss(PickingItem->GetItemID()))
	{
		Hint = Pot->IsFinish || Pot->IsFull || Pot->IsWaitingForPlate() ? TEXT("锅里已满") :
			(Pot->OnFire || Pot->Repairing ? TEXT("锅具需要维修") : TEXT("这口锅现在不收这种食材"));
		return false;
	}
	const FVector Start = PickingItem->GetActorLocation();
	const FVector End = Pot->GetTossMouth();
	FCollisionQueryParams Query(SCENE_QUERY_STAT(PotToss), false, this);
	Query.AddIgnoredActor(Pot);
	Query.AddIgnoredActor(PickingItem);
	FVector Prev = Start;
	for (int32 Step = 1; Step <= 8; ++Step)
	{
		const FVector Next = AItemActor::PotTossPoint(Start, End, TossHeight, Step / 8.f);
		if (GetWorld()->LineTraceTestByChannel(Prev, Next, ECC_Visibility, Query))
		{
			Hint = TEXT("投料路线被挡住了");
			return false;
		}
		Prev = Next;
	}
	Hint = Pot->MachineID == 1001 ? TEXT("松开投入煎锅") : TEXT("松开投入汤锅");
	return true;
}

void AShootCharacter::UpdateTossPreview(const FVector& Start, const ACookingMachine& Pot)
{
	const FVector End = Pot.GetTossMouth();
	constexpr int32 DashCount = 16;
	TossPreviewTransforms.Reset(DashCount + 1);
	for (int32 Index = 0; Index < DashCount; ++Index)
	{
		const FVector A = AItemActor::PotTossPoint(Start, End, TossHeight, (Index + 0.16f) / DashCount);
		const FVector B = AItemActor::PotTossPoint(Start, End, TossHeight, (Index + 0.84f) / DashCount);
		const FVector Segment = B - A;
		// The engine sphere is 100 cm wide. Stretch it into a short rounded dash.
		const FVector Scale(Segment.Size() / 100.f, 0.04f, 0.04f);
		TossPreviewTransforms.Emplace(Segment.Rotation().Quaternion(), (A + B) * 0.5f, Scale);
	}
	const FSphere Highlight = Pot.GetTossHighlightSphere();
	constexpr double PreviewMeshRadius = 50.0;
	TossPreviewTransforms.Emplace(FQuat::Identity, Highlight.Center, FVector(Highlight.W / PreviewMeshRadius));
	if (TossPreview->GetInstanceCount() == 0)
	{
		TossPreview->AddInstances(TossPreviewTransforms, false, true, false);
	}
	else
	{
		TossPreview->BatchUpdateInstancesTransforms(0, TossPreviewTransforms, true, true, true);
	}
	TossPreview->SetVisibility(true);
}

void AShootCharacter::UpdateTossHint()
{
	ACookingMachine* Pot = nullptr;
	FString Hint;
	const bool bReady = ResolvePotToss(Pot, Hint);
	if (bReady && IsLocallyControlled())
	{
		UpdateTossPreview(PickingItem->GetActorLocation(), *Pot);
	}
	else
	{
		TossPreview->SetVisibility(false);
	}
	if (auto* PC = Cast<APlayerController>(GetController()))
		TossHint->SetOwnerPlayer(PC->GetLocalPlayer());
	TossHint->SetWorldLocation(Pot ? Pot->GetTossMouth() + FVector::UpVector * 65.f : GetActorLocation() + FVector::UpVector * 120.f);
	TossHint->SetVisibility(true);
	if (auto* Widget = Cast<UInteractionPromptWidget>(TossHint->GetUserWidgetObject()))
		Widget->SetTossHint(Hint, bReady);
}

void AShootCharacter::SetPickingItemStatus()
{
	// Attaching disables overlap and may clear OverlappingItem synchronously.
	// Keep the selected item stable throughout the pickup operation.
	AItemActor* Item = OverlappingItem;
	if (!IsValid(Item)) return;
	AActor* PreAttachActor = Item->GetAttachParentActor();
 	if (PreAttachActor != nullptr)
 	{
		Item->PreAttachActor = PreAttachActor; //FChangeAttachActorEvent
			Item->OnChangeAttachActorEvent.Broadcast();//广播出去，切换了
 	}
	//OverlappingItem->AttachMeshToSocket(GetMesh(), ItemSocketName);
	if (!IsValid(Item)) return;
	Item->AttachMeshToSocket(RetargetMesh, ItemSocketName);

	if (!IsValid(Item)) return;
	Item->SetItemState(EItemState::EIS_Equipped);
	SetPickingItem(Item);
	OnPickEvent();
	CharacterActionState = ECharacterActionState::EAS_Picking;
	CharacterState = ECharacterState::ECS_Holding;

	//设置ik
	if (Item->HandIK_LPoint != nullptr)
	{
		FBIK_Alpha = 1;
		HandIK_LPoint = Item->HandIK_LPoint;
		HandIK_RPoint = Item->HandIK_RPoint;
	}
}

void AShootCharacter::SetPickingItem(AItemActor* Item)
{
	if (bIsPKeyHeld && PickingItem != Item) CancelPotAim();
	const bool bNewItem = Item && PickingItem != Item;
	PickingItem = Item;
	if (bNewItem && !Cast<AOutdoorBasket>(Item) && !Cast<APlateCollectionTray>(Item))
	{
		ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::PickupItem, Item->GetItemID(), Item);
		if (Item->GetMenuFoodID() >= 0)
			ATutorialTaskManager::NotifyAction(GetWorld(), ETutorialTaskType::CollectDish, Item->GetMenuFoodID(), Item);
	}
}

void AShootCharacter::HoldItemInHand(AItemActor* Item, bool bSetAsPickingItem)
{
	if (!Item)
	{
		return;
	}

	// 从树/插槽上摘下，直接挂到角色手部插槽上
	Item->DeAttachMeshToSocket();
	Item->AttachMeshToSocket(RetargetMesh, ItemSocketName);
	Item->SetItemState(EItemState::EIS_Equipped);

	// 设为手持主物体并切换到"手持"状态（仅主物体需要，多个果实时其它只挂手上）
	if (bSetAsPickingItem)
	{
		SetPickingItem(Item);
		OnPickEvent();
		CharacterActionState = ECharacterActionState::EAS_Picking;
		CharacterState = ECharacterState::ECS_Holding;

		if (Item->HandIK_LPoint != nullptr)
		{
			FBIK_Alpha = 1;
			HandIK_LPoint = Item->HandIK_LPoint;
			HandIK_RPoint = Item->HandIK_RPoint;
		}
	}
}

void AShootCharacter::PlayHarvestEffect(FVector SourceLocation)
{
	if (!HarvestEffect || !RetargetMesh)
	{
		return;
	}
	if (!RetargetMesh->DoesSocketExist(HarvestEffectSocket))
	{
		UE_LOG(LogShoot, Warning, TEXT("Harvest effect socket '%s' does not exist"), *HarvestEffectSocket.ToString());
		return;
	}

	UNiagaraComponent* Effect = UNiagaraFunctionLibrary::SpawnSystemAtLocation(
		this, HarvestEffect, SourceLocation, FRotator::ZeroRotator, FVector::OneVector, true, false);
	if (Effect)
	{
		Effect->SetVariableInt(TEXT("User.ParticleCount"), FMath::RandRange(1, 3));
		Effect->SetVariablePosition(TEXT("User.TargetPosition"), RetargetMesh->GetSocketLocation(HarvestEffectSocket));
		Effect->AddTickPrerequisiteComponent(RetargetMesh);
		Effect->AddTickPrerequisiteActor(this);
		Effect->Activate(true);
		ActiveHarvestEffects.Add(Effect);
	}
}

void AShootCharacter::UpdateHarvestEffects()
{
	for (int32 Index = ActiveHarvestEffects.Num() - 1; Index >= 0; --Index)
	{
		UNiagaraComponent* Effect = ActiveHarvestEffects[Index].Get();
		if (!Effect || Effect->IsComplete())
		{
			ActiveHarvestEffects.RemoveAtSwap(Index);
			continue;
		}
		Effect->SetVariablePosition(TEXT("User.TargetPosition"), RetargetMesh->GetSocketLocation(HarvestEffectSocket));
	}
}

