#include "UI/PanEdgeHintWidget.h"
#include "Machine/CookingMachine.h"
#include "Components/StaticMeshComponent.h"
#include "ConvexVolume.h"
#include "Engine/GameViewportClient.h"
#include "Engine/LocalPlayer.h"
#include "SceneView.h"
#include "Rendering/DrawElements.h"
#include "Brushes/SlateRoundedBoxBrush.h"
#include "Styling/CoreStyle.h"
#include "Widgets/Layout/SSpacer.h"

TSharedRef<SWidget> UPanEdgeHintWidget::RebuildWidget()
{
	return SNew(SSpacer);
}

int32 UPanEdgeHintWidget::NativePaint(const FPaintArgs& Args, const FGeometry& Geometry, const FSlateRect& Cull,
	FSlateWindowElementList& Elements, int32 Layer, const FWidgetStyle& Style, bool bEnabled) const
{
	Layer = Super::NativePaint(Args, Geometry, Cull, Elements, Layer, Style, bEnabled);
	const ACookingMachine* Pot = Machine.Get();
	float Remaining;
	if (!Pot || Pot->IsHidden() || !Pot->GetAttentionTimeLeft(Remaining)) return Layer;

	const ULocalPlayer* Player = GetOwningLocalPlayer();
	FSceneViewProjectionData View;
	if (!Player || !Player->ViewportClient || !Player->ViewportClient->Viewport ||
		!Player->GetProjectionData(Player->ViewportClient->Viewport, View)) return Layer;

	const FMatrix Matrix = View.ComputeViewProjectionMatrix();
	FConvexVolume Frustum;
	GetViewFrustumBounds(Frustum, Matrix, true);
	TInlineComponentArray<UStaticMeshComponent*> Parts(Pot);
	for (const UStaticMeshComponent* Part : Parts)
	{
		if (Part->GetStaticMesh() && Part->IsVisible() && !Part->bHiddenInGame &&
			Frustum.IntersectBox(Part->Bounds.Origin, Part->Bounds.BoxExtent)) return Layer;
	}

	const FVector2D Size = Geometry.GetLocalSize();
	const FVector2D Badge(106, 38);
	if (Size.X <= Badge.X + 24 || Size.Y <= Badge.Y + 24) return Layer;
	const FIntRect ViewRect = View.GetConstrainedViewRect();
	const FVector4 Clip = Matrix.TransformFVector4(FVector4(Pot->GetTossMouth(), 1));
	// Clip X/Y preserve the direction even behind the camera (no division by W).
	FVector2D Direction(Clip.X * ViewRect.Width(), -Clip.Y * ViewRect.Height());
	Direction.Normalize();
	if (Direction.IsNearlyZero()) Direction = FVector2D(0, 1);
	const FVector2D Center = Size * 0.5;
	const FVector2D Extent = Center - Badge * 0.5 - FVector2D(12, FMath::Min(76.0, Size.Y * 0.1));
	const double Distance = 1.0 / FMath::Max(FMath::Abs(Direction.X) / Extent.X, FMath::Abs(Direction.Y) / Extent.Y);
	const FVector2D Origin = Center + Direction * Distance - Badge * 0.5;

	const FLinearColor Accent = Remaining <= 0.25f ? FLinearColor(1.f, 0.35f, 0.12f) : FLinearColor(1.f, 0.71f, 0.25f);
	static const FSlateRoundedBoxBrush Back(FLinearColor(0.065f, 0.038f, 0.022f, 0.96f), 16.f);
	const auto BadgeGeometry = Geometry.ToPaintGeometry(FVector2f(Badge), FSlateLayoutTransform(FVector2f(Origin)));
	FSlateDrawElement::MakeBox(Elements, ++Layer, BadgeGeometry, &Back, ESlateDrawEffect::None, Back.TintColor.GetSpecifiedColor());
	const FVector2D Dial(20, 19);
	auto DrawArc = [&](float Fraction, const FLinearColor& Color)
	{
		TArray<FVector2D> Points;
		const int32 Segments = FMath::Max(1, FMath::CeilToInt(32 * Fraction));
		for (int32 I = 0; I <= Segments; ++I)
		{
			const double Angle = UE_TWO_PI * Fraction * I / Segments - UE_HALF_PI;
			Points.Add(Dial + FVector2D(FMath::Cos(Angle), FMath::Sin(Angle)) * 12);
		}
		FSlateDrawElement::MakeLines(Elements, ++Layer, BadgeGeometry, Points, ESlateDrawEffect::None, Color, true, 2.5f);
	};
	DrawArc(1.f, FLinearColor(0.30f, 0.21f, 0.12f));
	DrawArc(Remaining, Accent);
	const FVector2D Side(-Direction.Y, Direction.X);
	const TArray<FVector2D> Arrow{Dial - Direction * 3 + Side * 4, Dial + Direction * 4, Dial - Direction * 3 - Side * 4};
	FSlateDrawElement::MakeLines(Elements, ++Layer, BadgeGeometry, Arrow, ESlateDrawEffect::None, Accent, true, 2.5f);
	const auto TextGeometry = Geometry.ToPaintGeometry(FVector2f(69, 30), FSlateLayoutTransform(FVector2f(Origin + FVector2D(39, 6))));
	static const FSlateFontInfo Font = FCoreStyle::GetDefaultFontStyle("Bold", 14);
	FSlateDrawElement::MakeText(Elements, ++Layer, TextGeometry, NSLOCTEXT("Kitchen", "OffscreenFlip", "可翻面"), Font);
	return Layer;
}

